# ============================================================
# PATHS — app-bestandslocaties
# ============================================================

"""
core/paths.py - Centraal beheer van app-bestandslocaties.

Belangrijk om netjes te scheiden:
  - app_dir() — waar het programma staat (read-only bij PyInstaller)
  - data_dir() — waar configs en data komen: <basis>/data/
  - downloads_dir() — waar gedownloade bestanden komen: <data>/downloads/
  - logs_dir() — log-bestanden: <data>/logs/

Bij eerste start wordt automatisch oude data van direct in <basis>
verhuisd naar <basis>/data/ (migratie). Bestaande installaties
verliezen dus niks.
"""
import os
import sys
import shutil
from pathlib import Path
from typing import Optional


try:
    from uitspraak import uitspraak as _uitspraak
except Exception:
    try:
        from .uitspraak import uitspraak as _uitspraak
    except Exception:  # zonder uitspraak.py gewoon de tekst zelf
        def _uitspraak(t, taal="nl"):
            return t


def app_dir() -> Path:
    """Map waar het programma in staat (executable of script)."""
    try:
        if getattr(sys, "frozen", False):
            return Path(sys.executable).resolve().parent
        return Path(sys.argv[0]).resolve().parent
    except Exception:
        return Path.cwd()


def is_writable(p: Path) -> bool:
    """Test of we in een map kunnen schrijven (zonder ergens te schrijven)."""
    try:
        test = p / ".write_test"
        test.write_text("ok")
        test.unlink()
        return True
    except Exception:
        return False


def _writable_base() -> Path:
    """
    Vind een schrijfbare basis-locatie:
      1. Naast de app zelf
      2. Anders APPDATA/Dravenlock (Windows)
      3. Anders ~/.dravenlock
    """
    p = app_dir()
    if is_writable(p):
        return p
    if os.name == "nt":
        appdata = os.environ.get("APPDATA")
        if appdata:
            d = Path(appdata) / "Dravenlock"
            d.mkdir(parents=True, exist_ok=True)
            return d
    fallback = Path.home() / ".dravenlock"
    fallback.mkdir(parents=True, exist_ok=True)
    return fallback


# Vlag: migratie al uitgevoerd in deze sessie?
_migration_done = False

# Bestanden die we kennen en die naar data/ horen verhuizen
# (bij eerste start na update naar v0.14.2+)
_KNOWN_DATA_FILES = [
    "settings.json", "settings.json.tmp",
    "favorites.json", "favorites.json.tmp",
    "extensions.json", "extensions.json.tmp",
    "history.json", "history.json.tmp",
    "dark_sites.json", "dark_sites.json.tmp",
    "zoom_levels.json", "zoom_levels.json.tmp",
    "vault.enc", "vault.enc.tmp", "vault_recovery.txt",
]

# Submappen die ook horen te verhuizen als ze losliggen
_KNOWN_DATA_DIRS = ["downloads", "tools", "cache"]

# Logs gaan naar logs/ submap binnen data/
_KNOWN_LOG_FILES = [
    "dravenlock.log", "dravenlock.log.1",
    "dravenlock.log.2", "dravenlock.log.3",
]


def _migrate_old_data(base: Path, data: Path):
    """
    Verhuis oude losse data-bestanden van <base> naar <base>/data/.

    Wordt ÉÉN keer bij eerste start uitgevoerd. Idempotent — als er
    geen oude bestanden zijn (of als ze al verhuisd zijn), doet hij niets.
    """
    global _migration_done
    if _migration_done:
        return
    _migration_done = True

    moved_files = []
    moved_dirs = []

    # 1. Losse data-bestanden verhuizen naar data/
    for fname in _KNOWN_DATA_FILES:
        src = base / fname
        if src.exists() and src.is_file():
            dst = data / fname
            if dst.exists():
                # Doel bestaat al — laat origineel staan, gebruiker
                # moet zelf kiezen (we overschrijven niets)
                continue
            try:
                shutil.move(str(src), str(dst))
                moved_files.append(fname)
            except Exception as e:
                print(f"[migratie] kon {fname} niet verhuizen: {e}")

    # 2. Bekende submappen verhuizen
    for dname in _KNOWN_DATA_DIRS:
        src = base / dname
        if src.exists() and src.is_dir():
            dst = data / dname
            if dst.exists():
                continue
            try:
                shutil.move(str(src), str(dst))
                moved_dirs.append(dname)
            except Exception as e:
                print(f"[migratie] kon {dname}/ niet verhuizen: {e}")

    # 3. Log-bestanden verhuizen naar data/logs/
    logs_target = data / "logs"
    moved_logs = []
    for fname in _KNOWN_LOG_FILES:
        src = base / fname
        if src.exists() and src.is_file():
            logs_target.mkdir(parents=True, exist_ok=True)
            dst = logs_target / fname
            if dst.exists():
                continue
            try:
                shutil.move(str(src), str(dst))
                moved_logs.append(fname)
            except Exception as e:
                print(f"[migratie] kon log {fname} niet verhuizen: {e}")

    if moved_files or moved_dirs or moved_logs:
        print(f"[migratie] Verhuisd naar data/: "
              f"{len(moved_files)} bestanden, "
              f"{len(moved_dirs)} mappen, "
              f"{len(moved_logs)} logs")


def data_dir() -> Path:
    """
    Map voor read/write data — nu altijd <basis>/data/.

    Bij eerste aanroep van deze sessie wordt automatisch gemigreerd:
    oude losse bestanden direct in <basis>/ worden verplaatst naar
    deze nieuwe data/-map.
    """
    base = _writable_base()
    data = base / "data"
    data.mkdir(parents=True, exist_ok=True)

    # Eenmalige migratie van oude installaties
    _migrate_old_data(base, data)

    return data


def downloads_dir() -> Path:
    """Map voor gedownloade bestanden."""
    d = data_dir() / "downloads"
    d.mkdir(parents=True, exist_ok=True)
    return d


def tools_dir() -> Path:
    """Map voor hulpprogramma's zoals yt-dlp en ffmpeg."""
    d = data_dir() / "tools"
    d.mkdir(parents=True, exist_ok=True)
    return d


def cache_dir() -> Path:
    """Map voor tijdelijke bestanden (browser cache, etc)."""
    d = data_dir() / "cache"
    d.mkdir(parents=True, exist_ok=True)
    return d


def logs_dir() -> Path:
    """Map voor log-bestanden — data/logs/."""
    d = data_dir() / "logs"
    d.mkdir(parents=True, exist_ok=True)
    return d


# ============================================================
# LOGGING — TeeStream + rotatie
# ============================================================

"""
core/logging_setup.py - Persistente logging voor Dravenlock Browser.

Schrijft alle `print()` output ook naar dravenlock.log, met rotatie
(bewaar 3 sessies). Belangrijk voor diagnose — geleerde les uit
DeskButler: zonder log zijn stille crashes onmogelijk te vinden.

De TeeStream techniek: vervang sys.stdout en sys.stderr met objecten
die zowel naar het origineel als naar het bestand schrijven.
"""
import sys
import os
import datetime as _datetime_mod
from pathlib import Path
from typing import IO


def get_log_dir() -> Path:
    """Locatie voor logs — binnen <data>/logs/."""
    # (intra-import gestript: from core.paths import logs_dir)
    return logs_dir()


def rotate_logs(log_dir: Path, base_name: str = "dravenlock.log",
                keep: int = 3):
    """
    Rotteer log-bestanden: dravenlock.log.2 → .3 → weg, .1 → .2, log → .1.
    Bewaart maximaal `keep` oude logs.
    """
    base = log_dir / base_name
    if not base.exists():
        return
    # Oudste eerst verwijderen
    oldest = log_dir / f"{base_name}.{keep}"
    if oldest.exists():
        try:
            oldest.unlink()
        except Exception:
            pass
    # Vervolgens elk omhoog schuiven
    for i in range(keep - 1, 0, -1):
        src = log_dir / f"{base_name}.{i}"
        dst = log_dir / f"{base_name}.{i + 1}"
        if src.exists():
            try:
                src.rename(dst)
            except Exception:
                pass
    # En de actieve log naar .1
    try:
        base.rename(log_dir / f"{base_name}.1")
    except Exception:
        pass


class TeeStream:
    """
    Schrijft naar zowel een origineel stream (console) als een bestand.
    Wordt gebruikt om sys.stdout en sys.stderr te vervangen zodat
    alle print() output ook in het log-bestand komt.
    """

    def __init__(self, original: IO, file: IO):
        self.original = original
        self.file = file

    def write(self, data):
        try:
            self.original.write(data)
        except Exception:
            pass
        try:
            self.file.write(data)
            self.file.flush()
        except Exception:
            pass

    def flush(self):
        try:
            self.original.flush()
        except Exception:
            pass
        try:
            self.file.flush()
        except Exception:
            pass


_log_file_handle = None
_log_path: Path = None


def setup_logging() -> Path:
    """
    Initialiseer persistente logging. Roep dit aan VROEG in main(),
    voordat andere modules iets gaan loggen.

    Returnt het pad naar het log-bestand.
    """
    global _log_file_handle, _log_path

    log_dir = get_log_dir()
    rotate_logs(log_dir)
    _log_path = log_dir / "dravenlock.log"

    try:
        _log_file_handle = open(_log_path, "w", encoding="utf-8", buffering=1)
        # Header
        _log_file_handle.write(
            f"=== Dravenlock log gestart {_datetime_mod.datetime.now().isoformat()} ===\n"
            f"Log-locatie: {_log_path}\n"
            f"Python: {sys.version}\n"
            f"Platform: {sys.platform}\n"
            f"Werkmap: {os.getcwd()}\n"
            f"{'=' * 60}\n"
        )
        _log_file_handle.flush()
        # Hijack stdout en stderr
        sys.stdout = TeeStream(sys.__stdout__, _log_file_handle)
        sys.stderr = TeeStream(sys.__stderr__, _log_file_handle)
        print(f"[logging] Logs worden geschreven naar: {_log_path}")
    except Exception as e:
        print(f"[logging] kon log-bestand niet openen: {e}")
        _log_path = None

    return _log_path


def get_log_path() -> Path:
    """Het actieve log-pad (of None als logging niet werd opgezet)."""
    return _log_path


def close_logging():
    """Sluit het log-bestand netjes af bij afsluiten van de app."""
    global _log_file_handle
    if _log_file_handle:
        try:
            _log_file_handle.write(
                f"=== Dravenlock log afgesloten "
                f"{_datetime_mod.datetime.now().isoformat()} ===\n"
            )
            _log_file_handle.flush()
            _log_file_handle.close()
        except Exception:
            pass
        _log_file_handle = None


