"""
core/config.py - Centraal beheer van settings (settings.json).

Vervangt het ad-hoc lezen/schrijven van JSON dat overal door browser.py
verspreid stond. Eén plek voor:
  - Lezen en schrijven van settings.json
  - Defaults beheren (welke instelling heeft welke startwaarde)
  - Type-veilige getters

Gebruik:
    # (intra-import gestript: from core.config import config)
    homepage = config.get("homepage", "https://duckduckgo.com")
    config.set("zoom_level", 1.25)
"""
import json
import os
import sys
from pathlib import Path
from typing import Any, Dict, Optional


# ----------------------------------------------------------------------
# Locatie van settings — naast de app, met %APPDATA% als fallback
# ----------------------------------------------------------------------
def get_settings_file() -> Path:
    """Geef het pad naar settings.json terug (binnen data/-map)."""
    # (intra-import gestript: from core.paths import data_dir)
    return data_dir() / "settings.json"


# ----------------------------------------------------------------------
# Default-waarden voor alle instellingen
# ----------------------------------------------------------------------
DEFAULTS: Dict[str, Any] = {
    # Algemeen
    # Taal: leeg betekent "nog niet gekozen, detecteer OS-taal".
    # Wordt bij eerste run automatisch gevuld door init_from_config()
    # in core/lang.py. Bestaande config.json's met "nl" of "en" als
    # waarde blijven gewoon zo, want we lezen alleen de OS-taal
    # wanneer er nog niets is ingevuld.
    "language": "",
    "first_run": True,

    # Browser
    "homepage": "https://duckduckgo.com",
    "search_engine": "duckduckgo",
    "default_zoom": 1.0,
    "restore_tabs_on_start": False,
    "open_links_in_new_tab": True,

    # AdBlock
    "adblock_enabled": True,

    # Voorlezen (TTS via NeuVoice)
    "tts_voice": "Leon",
    "tts_speed": 0.85,
    "tts_show_button": True,

    # E-mail (SMTP) voor contactformulier
    "smtp_provider": "transip",
    "smtp_host": "smtp.transip.email",
    "smtp_port": 587,
    "smtp_encryption": "starttls",
    "smtp_user": "",
    "smtp_from": "",

    # Privacy
    "clear_history_on_exit": False,
    "auto_accept_cookies": True,
    "block_third_party_cookies": False,
    "vault_autolock_minutes": 5,
    "clipboard_clear_seconds": 30,

    # Geschiedenis
    "history_enabled": True,
    "history_retention_days": 90,  # 0 = onbeperkt

    # Updates
    "check_updates_on_start": True,
    "last_update_check": 0,

    # UI
    "window_width": 1200,
    "window_height": 800,
    "window_maximized": False,
    "show_status_bar": True,
}


class Config:
    """Settings-beheerder. Gebruik via de globale `config` singleton."""

    def __init__(self):
        self._file = get_settings_file()
        self._data: Dict[str, Any] = {}
        self._load()

    def _load(self):
        if not self._file.exists():
            self._data = dict(DEFAULTS)
            return
        try:
            with open(self._file, "r", encoding="utf-8") as f:
                self._data = json.load(f)
        except Exception as e:
            print(f"[config] laden faalde, gebruik defaults: {e}")
            self._data = dict(DEFAULTS)

    def _save(self):
        try:
            # Atomair: eerst naar .tmp, dan rename
            tmp = self._file.with_suffix(self._file.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self._data, f, indent=2, ensure_ascii=False)
            if self._file.exists():
                self._file.unlink()
            tmp.rename(self._file)
        except Exception as e:
            print(f"[config] opslaan faalde: {e}")

    def get(self, key: str, default: Any = None) -> Any:
        """Lees een setting. Valt terug op DEFAULTS, dan op `default`."""
        if key in self._data:
            return self._data[key]
        if key in DEFAULTS:
            return DEFAULTS[key]
        return default

    def set(self, key: str, value: Any):
        """Sla een setting op en schrijf direct naar disk."""
        self._data[key] = value
        self._save()

    def update(self, **kwargs):
        """Sla meerdere settings tegelijk op (één schrijf-actie)."""
        self._data.update(kwargs)
        self._save()

    def reset(self, key: Optional[str] = None):
        """Reset één key naar default, of alle settings."""
        if key is None:
            self._data = dict(DEFAULTS)
        elif key in DEFAULTS:
            self._data[key] = DEFAULTS[key]
        elif key in self._data:
            del self._data[key]
        self._save()

    def file_path(self) -> Path:
        """Geef het pad naar settings.json terug (voor debug-doeleinden)."""
        return self._file


# Globale singleton — overal te importeren als `from core.config import config`
config = Config()


