# ----------------------------------------------------------------------
# Singleton state
# ----------------------------------------------------------------------
_current_lang: str = "nl"


def set_language(lang_code: str):
    """Wijzig de actieve taal. Valt terug op NL als onbekend."""
    global _current_lang
    if lang_code in TRANSLATIONS:
        _current_lang = lang_code
    else:
        _current_lang = "nl"


def detect_os_language() -> str:
    """
    Detecteer de taal van het besturingssysteem en geef de
    bijbehorende Dravenlock-taalcode terug. Op dit moment
    ondersteunen we alleen Nederlands en Engels, dus alles wat
    niet NL is wordt EN. Bij onbekend valt het terug op NL omdat
    Dravenlock een Nederlandse app is van origine.

    Eerst proberen we QLocale (PySide6) want die respecteert de
    Windows-instellingen het meest betrouwbaar. Bij een fout
    valt het terug op de standaard Python locale-module.
    """
    try:
        
        # name() geeft iets als "nl_NL", "en_US", "de_DE"
        loc_name = QLocale.system().name()
        if loc_name:
            lang_part = loc_name.split("_")[0].lower()
            if lang_part == "nl":
                return "nl"
            if lang_part == "en":
                return "en"
            # Andere talen vallen terug op Engels want dat is
            # waarschijnlijker dat de gebruiker dat kan lezen
            # dan Nederlands.
            return "en"
    except Exception:
        pass

    try:
        import locale
        loc = locale.getdefaultlocale()[0] or ""
        lang_part = loc.split("_")[0].lower()
        if lang_part == "nl":
            return "nl"
        if lang_part == "en":
            return "en"
        return "en"
    except Exception:
        pass

    return "nl"


def init_from_config():
    """
    Laad de taal uit de config en pas hem toe als actieve taal.
    Wordt bij browser-start eenmaal aangeroepen om de gebruikers-
    voorkeur op te halen.

    Wanneer de config nog geen taal-keuze bevat (eerste run of
    handmatig leeg gemaakt), detecteren we de OS-taal en slaan die
    op. Op die manier krijgt een gebruiker direct de juiste taal te
    zien zonder dat hij iets hoeft in te stellen. Pas wanneer hij
    bewust een andere taal kiest in Instellingen wordt die opgeslagen
    en bewaard voor volgende sessies.
    """
    try:
        # (intra-import gestript: from core.config import config)
        stored = config.get("language", "")
        if stored:
            # Gebruiker heeft eerder een keuze gemaakt (of de
            # default zat erin); respecteer die.
            set_language(stored)
        else:
            # Geen voorkeur opgeslagen: detecteer OS-taal en
            # bewaar die als nieuwe default zodat de keuze
            # consistent blijft bij volgende sessies.
            detected = detect_os_language()
            set_language(detected)
            try:
                config.set("language", detected)
            except Exception:
                pass
    except Exception:
        set_language("nl")


def get_language() -> str:
    """Geef de huidige taalcode terug."""
    return _current_lang


def _(key: str, *args) -> str:
    """
    Lookup van een vertaling op key. Bij ontbrekende key valt terug op
    de Engelse versie, en als die ook ontbreekt op de key zelf zodat
    de gebruiker tenminste iets zinvols ziet voor diagnostiek.

    Optionele args worden via .format() ingevoegd voor strings met
    placeholders zoals "Pagina laden: {0}".
    """
    table = TRANSLATIONS.get(_current_lang, {})
    text = table.get(key)
    if text is None:
        # Fallback naar Engels
        text = TRANSLATIONS.get("en", {}).get(key)
    if text is None:
        # Laatste redmiddel: de key zelf
        text = key
    if args:
        try:
            text = text.format(*args)
        except (IndexError, KeyError):
            pass
    return text


def translate_html(html: str) -> str:
    """
    Vervang {{key}} markers in een HTML-string door hun vertaling.
    Onbekende keys worden ongemoeid gelaten zodat ze opvallen tijdens
    ontwikkeling. Whitespace tussen accolades en key wordt getolereerd
    zodat zowel {{key}} als {{ key }} werken.
    """
    table = TRANSLATIONS.get(_current_lang, {})
    fallback = TRANSLATIONS.get("en", {})

    def replace(match):
        key = match.group(1).strip()
        text = table.get(key)
        if text is None:
            text = fallback.get(key)
        if text is None:
            return match.group(0)
        return text

    return re.sub(r"\{\{\s*([a-zA-Z0-9_]+)\s*\}\}", replace, html)


# Naamtabellen voor weekdagen en maanden, geindexeerd op taalcode.
# Python's datetime.strftime gebruikt de C-locale die op verschillende
# Windows-systemen anders staat ingesteld dan de Windows-display-
# taal. Door zelf de mapping te doen weten we zeker dat de datum
# in de app-taal verschijnt, niet in de system-locale.
_WEEKDAY_NAMES = {
    "nl": ["maandag", "dinsdag", "woensdag", "donderdag",
           "vrijdag", "zaterdag", "zondag"],
    "en": ["Monday", "Tuesday", "Wednesday", "Thursday",
           "Friday", "Saturday", "Sunday"],
}

_MONTH_NAMES = {
    "nl": ["januari", "februari", "maart", "april", "mei", "juni",
           "juli", "augustus", "september", "oktober", "november",
           "december"],
    "en": ["January", "February", "March", "April", "May", "June",
           "July", "August", "September", "October", "November",
           "December"],
}


def format_date_long(dt) -> str:
    """
    Geef een datum als "zaterdag 31 mei 2026" of "Saturday 31 May
    2026" terug, afhankelijk van de huidige app-taal. Gebruikt onze
    eigen naamtabellen in plaats van datetime.strftime omdat die
    onbetrouwbaar is met locale-instellingen op Windows.
    """
    lang = _current_lang if _current_lang in _WEEKDAY_NAMES else "nl"
    weekday = _WEEKDAY_NAMES[lang][dt.weekday()]
    month = _MONTH_NAMES[lang][dt.month - 1]
    return f"{weekday} {dt.day} {month} {dt.year}"


# ============================================================
# STYLING — Dravenlock-thema
# ============================================================

"""
core/styling.py - Het Dravenlock-thema, centraal beheerd.

Eén plek voor alle kleuren, fonts, en stylesheets. Modules importeren
hieruit zodat de UI consistent is en straks gemakkelijk aanpasbaar.

DRAVENLOCK-PALETTE
==================
Donker, strak, met een cyaan-blauwe accent. Gebaseerd op de visuele
identiteit van het origineel.

  zwart       #000000   hoofdvenster-achtergrond
  diep-grijs  #0a0a0a   input-velden, code-blokken
  donker-1    #111111   dialogen, panels
  donker-2    #1a1a1a   verhoogde elementen, hover
  rand        #262626   subtiele scheidingen
  border      #333333   randen van controls
  tekst-dim   #888888   secundaire tekst, hints
  tekst       #eeeeee   primaire tekst (zacht-wit)
  accent      #00aaff   actie-kleur (Dravenlock-cyaan)
  succes      #00cc66
  waarschuw   #ffaa00
  fout        #ff4444
"""




# ----------------------------------------------------------------------
# Kleur-paletten — toegankelijk als COLOR.accent etc.
# ----------------------------------------------------------------------
class COLOR:
    """Alle Dravenlock-kleuren als string-constanten."""
    bg_main = "#000000"
    bg_deep = "#0a0a0a"
    bg_1 = "#111111"
    bg_2 = "#1a1a1a"
    bg_3 = "#262626"

    border = "#333333"
    border_hover = "#444444"

    text_dim = "#888888"
    text = "#eeeeee"
    text_bright = "#ffffff"

    accent = "#00aaff"
    accent_dark = "#0077bb"
    accent_glow = "rgba(0, 170, 255, 0.4)"

    success = "#00cc66"
    warning = "#ffaa00"
    error = "#ff4444"


# ----------------------------------------------------------------------
# Fonts
# ----------------------------------------------------------------------
DEFAULT_FONT_FAMILY = "Segoe UI"
DEFAULT_FONT_SIZE = 11
TITLE_FONT_SIZE = 16
MONO_FONT_FAMILY = "Consolas"


def base_font(size: int = None) -> QFont:
    """Standaard UI-font."""
    f = QFont(DEFAULT_FONT_FAMILY, size or DEFAULT_FONT_SIZE)
    return f


def title_font(size: int = None) -> QFont:
    """Vetgedrukt titel-font."""
    f = QFont(DEFAULT_FONT_FAMILY, size or TITLE_FONT_SIZE, QFont.Bold)
    return f


def mono_font(size: int = None) -> QFont:
    """Monospace font voor code en URLs."""
    f = QFont(MONO_FONT_FAMILY, size or DEFAULT_FONT_SIZE)
    return f


# ----------------------------------------------------------------------
# Global application stylesheet — wordt toegepast op QApplication
# ----------------------------------------------------------------------
def get_global_stylesheet() -> str:
    """
    Het globale Dravenlock-thema voor de hele applicatie.
    Wordt toegepast met `app.setStyleSheet(get_global_stylesheet())`.
    """
    c = COLOR
    return f"""
        /* ===== Hoofdvenster ===== */
        QMainWindow, QDialog {{
            background: {c.bg_main};
            color: {c.text};
        }}

        /* ===== Tabs ===== */
        QTabWidget::pane {{
            background: {c.bg_main};
            border: 1px solid {c.border};
            border-radius: 4px;
        }}
        QTabBar::tab {{
            background: {c.bg_1};
            color: {c.text_dim};
            padding: 10px 18px;
            padding-right: 36px;
            margin-right: 2px;
            border: 1px solid {c.border};
            border-bottom: none;
            border-top-left-radius: 4px;
            border-top-right-radius: 4px;
            min-width: 180px;
            max-width: 280px;
            font-size: 14px;
        }}
        QTabBar::tab:hover {{
            color: {c.text};
            background: {c.bg_2};
        }}
        QTabBar::tab:selected {{
            background: {c.bg_2};
            color: #cccccc;
            border-bottom: 2px solid #999999;
            font-weight: bold;
        }}
        /* Custom close-button voor tabs. Aangezien we Qt's standaard
           close-button hebben uitgezet en zelf een QToolButton
           toevoegen via setTabButton, hebben we deze styling nodig
           voor onze eigen knop. De Unicode-tekst wordt door Qt's
           font-engine gerenderd wat veel betrouwbaarder is dan
           SVG-data-URLs in stylesheets. */
        QToolButton#tabCloseButton {{
            background: transparent;
            color: #cccccc;
            border: none;
            border-radius: 3px;
            font-weight: bold;
        }}
        QToolButton#tabCloseButton:hover {{
            background: rgba(255, 255, 255, 0.15);
            color: #ffffff;
        }}
        QToolButton#tabCloseButton:pressed {{
            background: rgba(255, 255, 255, 0.25);
        }}

        /* ===== Verticale tabs (Settings-venster) =====
           Specifieke regels voor tab-widgets met objectName "verticalTabs"
           zodat we de Settings-tabs aan de zijkant kunnen stijlen zonder
           de browser-tabs bovenaan te beinvloeden. */
        QTabWidget#verticalTabs::pane {{
            background: {c.bg_main};
            border: 1px solid {c.border};
            border-radius: 4px;
            border-left: none;
        }}

        /* De tab-balk zelf krijgt een eigen achtergrond zodat hij
           visueel als een navigatie-paneel aanvoelt, vergelijkbaar met
           hoe de Snelgids zijn navigatie heeft. */
        QTabWidget#verticalTabs > QTabBar {{
            background: {c.bg_deep};
        }}

        QTabWidget#verticalTabs > QTabBar::tab {{
            background: {c.bg_deep};
            color: {c.text_dim};
            padding: 14px 20px;
            margin: 0;
            border: none;
            border-bottom: 1px solid {c.border};
            border-radius: 0;
            min-width: 180px;
            min-height: 36px;
            font-size: 14px;
            text-align: left;
        }}

        QTabWidget#verticalTabs > QTabBar::tab:hover {{
            background: {c.bg_1};
            color: {c.text};
        }}

        /* Geselecteerde tab krijgt een cyaan rechterrand die naar de
           inhoud wijst, in plaats van een onderrand zoals horizontale
           tabs. Dat past beter bij de verticale orientatie. */
        QTabWidget#verticalTabs > QTabBar::tab:selected {{
            background: {c.bg_2};
            color: {c.accent};
            border-right: 3px solid {c.accent};
            font-weight: bold;
        }}

        /* ===== Toolbar ===== */
        QToolBar {{
            background: {c.bg_1};
            border: none;
            border-bottom: 1px solid {c.border};
            spacing: 4px;
            padding: 4px;
        }}

        /* ===== Knoppen ===== */
        QPushButton {{
            background: {c.bg_2};
            color: {c.text};
            border: 1px solid {c.border};
            border-radius: 4px;
            padding: 6px 14px;
            min-height: 20px;
        }}
        QPushButton:hover {{
            border-color: {c.accent};
            color: {c.accent};
        }}
        QPushButton:pressed {{
            background: {c.bg_3};
        }}
        QPushButton:disabled {{
            background: {c.bg_1};
            color: {c.text_dim};
            border-color: {c.bg_3};
        }}

        /* Variant: primary action — geaccentueerd */
        QPushButton[primary="true"] {{
            background: {c.accent};
            color: {c.bg_main};
            border: 1px solid {c.accent};
            font-weight: bold;
        }}
        QPushButton[primary="true"]:hover {{
            background: {c.accent_dark};
            border-color: {c.accent_dark};
            color: {c.text};
        }}

        /* Variant: gevaar (verwijderen, annuleren) */
        QPushButton[danger="true"] {{
            background: {c.bg_2};
            color: {c.error};
            border: 1px solid {c.error};
        }}
        QPushButton[danger="true"]:hover {{
            background: {c.error};
            color: {c.text_bright};
        }}

        /* ===== Inputs ===== */
        QLineEdit, QTextEdit, QPlainTextEdit, QComboBox, QSpinBox {{
            background: {c.bg_deep};
            color: {c.text};
            border: 1px solid {c.border};
            border-radius: 4px;
            padding: 6px 8px;
            selection-background-color: {c.accent};
            selection-color: {c.bg_main};
        }}
        QLineEdit:focus, QTextEdit:focus, QPlainTextEdit:focus,
        QComboBox:focus, QSpinBox:focus {{
            border-color: {c.accent};
        }}

        /* ===== Labels ===== */
        QLabel {{
            color: {c.text};
            background: transparent;
        }}

        /* ===== Lijsten en bomen ===== */
        QListWidget, QTreeWidget, QTableWidget {{
            background: {c.bg_deep};
            color: {c.text};
            border: 1px solid {c.border};
            border-radius: 4px;
            alternate-background-color: {c.bg_1};
        }}
        QListWidget::item, QTreeWidget::item {{
            padding: 6px;
            border-bottom: 1px solid {c.bg_2};
        }}
        QListWidget::item:hover, QTreeWidget::item:hover {{
            background: {c.bg_2};
        }}
        QListWidget::item:selected, QTreeWidget::item:selected {{
            background: {c.accent};
            color: {c.bg_main};
        }}
        QHeaderView::section {{
            background: {c.bg_1};
            color: {c.text};
            padding: 6px;
            border: 1px solid {c.border};
        }}

        /* ===== Menu's ===== */
        QMenu {{
            background: {c.bg_1};
            color: {c.text};
            border: 1px solid {c.border};
            padding: 6px;
            font-size: 14px;
        }}
        QMenu::item {{
            padding: 10px 32px 10px 16px;
            border-radius: 3px;
            min-width: 240px;
        }}
        QMenu::item:selected {{
            background: {c.accent};
            color: {c.bg_main};
        }}
        QMenu::item:disabled {{
            color: {c.text_dim};
            font-weight: bold;
            font-size: 12px;
            padding: 6px 16px 2px 16px;
        }}
        QMenu::separator {{
            height: 1px;
            background: {c.border};
            margin: 6px 8px;
        }}
        /* Sub-menu indicator: ▶ rechts in beeld */
        QMenu::right-arrow {{
            image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10' viewBox='0 0 10 10'><path d='M3 2 L7 5 L3 8' stroke='%23eeeeee' stroke-width='1.5' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>");
            width: 10px;
            height: 10px;
            margin-right: 8px;
        }}

        /* ===== Scrollbars ===== */
        QScrollBar:vertical {{
            background: {c.bg_1};
            width: 12px;
            border: none;
        }}
        QScrollBar::handle:vertical {{
            background: {c.bg_3};
            min-height: 30px;
            border-radius: 6px;
        }}
        QScrollBar::handle:vertical:hover {{
            background: {c.accent};
        }}
        QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{
            background: transparent;
            height: 0;
        }}
        QScrollBar:horizontal {{
            background: {c.bg_1};
            height: 12px;
            border: none;
        }}
        QScrollBar::handle:horizontal {{
            background: {c.bg_3};
            min-width: 30px;
            border-radius: 6px;
        }}
        QScrollBar::handle:horizontal:hover {{
            background: {c.accent};
        }}
        QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {{
            background: transparent;
            width: 0;
        }}

        /* ===== Status bar ===== */
        QStatusBar {{
            background: {c.bg_1};
            color: {c.text_dim};
            border-top: 1px solid {c.border};
        }}
        QStatusBar::item {{
            border: none;
        }}

        /* ===== ToolTip ===== */
        QToolTip {{
            background: {c.bg_2};
            color: {c.text};
            border: 1px solid {c.accent};
            padding: 4px 8px;
            border-radius: 3px;
        }}

        /* ===== ProgressBar ===== */
        QProgressBar {{
            background: {c.bg_deep};
            border: 1px solid {c.border};
            border-radius: 4px;
            text-align: center;
            color: {c.text};
        }}
        QProgressBar::chunk {{
            background: {c.accent};
            border-radius: 3px;
        }}

        /* ===== RadioButton ===== */
        QRadioButton {{
            color: {c.text};
            spacing: 8px;
            padding: 4px;
        }}
        QRadioButton::indicator {{
            width: 18px;
            height: 18px;
            border-radius: 10px;
            border: 2px solid {c.border};
            background: {c.bg_deep};
        }}
        QRadioButton::indicator:hover {{
            border-color: {c.text_dim};
        }}
        QRadioButton::indicator:checked {{
            border: 2px solid {c.accent};
            background: qradialgradient(
                cx:0.5, cy:0.5, radius:0.5,
                fx:0.5, fy:0.5,
                stop:0 {c.accent},
                stop:0.5 {c.accent},
                stop:0.55 {c.bg_deep},
                stop:1 {c.bg_deep}
            );
        }}
        QRadioButton::indicator:checked:hover {{
            border: 2px solid #66ccff;
        }}
        QRadioButton:disabled {{
            color: {c.text_dim};
        }}

        /* ===== CheckBox ===== */
        QCheckBox {{
            color: {c.text};
            spacing: 10px;
            padding: 4px;
        }}
        QCheckBox::indicator {{
            width: 22px;
            height: 22px;
            border-radius: 4px;
            border: 2px solid {c.border};
            background: {c.bg_deep};
        }}
        QCheckBox::indicator:hover {{
            border-color: {c.text_dim};
        }}
        QCheckBox::indicator:checked {{
            border: 2px solid {c.accent};
            background: {c.accent};
            /* Wit vinkje via inline SVG data-URL. Voor mensen die
               geen kleur-onderscheid maken is een vorm-marker veel
               duidelijker dan alleen een gevuld blokje. */
            image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 16 16'><path d='M3 8 L6.5 11.5 L13 4.5' stroke='black' stroke-width='2.5' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>");
        }}
        QCheckBox::indicator:checked:hover {{
            border: 2px solid #66ccff;
            background: #66ccff;
        }}
        QCheckBox:disabled {{
            color: {c.text_dim};
        }}
    """


def apply_theme(app: QApplication):
    """Pas het Dravenlock-thema toe op een QApplication."""
    app.setStyleSheet(get_global_stylesheet())
    # Optioneel: een echte dark palette zodat ook niet-stylesheet widgets
    # (zoals systeemcontextmenu's) donker zijn.
    pal = QPalette()
    pal.setColor(QPalette.Window, QColor(COLOR.bg_main))
    pal.setColor(QPalette.WindowText, QColor(COLOR.text))
    pal.setColor(QPalette.Base, QColor(COLOR.bg_deep))
    pal.setColor(QPalette.AlternateBase, QColor(COLOR.bg_1))
    pal.setColor(QPalette.Text, QColor(COLOR.text))
    pal.setColor(QPalette.Button, QColor(COLOR.bg_2))
    pal.setColor(QPalette.ButtonText, QColor(COLOR.text))
    pal.setColor(QPalette.Highlight, QColor(COLOR.accent))
    pal.setColor(QPalette.HighlightedText, QColor(COLOR.bg_main))
    pal.setColor(QPalette.ToolTipBase, QColor(COLOR.bg_2))
    pal.setColor(QPalette.ToolTipText, QColor(COLOR.text))
    app.setPalette(pal)


# ----------------------------------------------------------------------
# Helper-functies voor accent-knoppen en gevaar-knoppen
# ----------------------------------------------------------------------
def make_primary(widget: QWidget):
    """Markeer een knop als primary-action (cyan accent)."""
    widget.setProperty("primary", True)
    widget.style().unpolish(widget)
    widget.style().polish(widget)


def make_danger(widget: QWidget):
    """Markeer een knop als danger-action (rode rand)."""
    widget.setProperty("danger", True)
    widget.style().unpolish(widget)
    widget.style().polish(widget)


# ============================================================
# ADBLOCK — URL request interceptor
# ============================================================

"""
core/adblock.py - AdBlocker via QWebEngineUrlRequestInterceptor.

Hou onderdrukt requests naar bekende advertentie- en tracking-domeinen
voordat ze worden uitgevoerd. Snel en effectief — het zelfde patroon
als uBlock Origin (op netwerkniveau).

Domain-lijst is ingebouwd; later kan deze geladen worden uit een
externe lijst (EasyList) als die actueel gehouden moet worden.
"""



# ----------------------------------------------------------------------
# Block-lijst — substring match in host.
# Een korte verstandige basis. Voor bredere dekking kan later EasyList
# worden geïntegreerd.
# ----------------------------------------------------------------------
BLOCKED_HOSTS = {
    # Google ad-netwerken
    "doubleclick.net",
    "googleadservices.com",
    "googlesyndication.com",
    "googletagmanager.com",
    "googletagservices.com",
    "google-analytics.com",
    "googletraveladservices.com",
    "adservice.google.com",

    # Facebook-tracking
    "facebook.com/tr",
    "connect.facebook.net",

    # Amazon-ads
    "amazon-adsystem.com",

    # Microsoft / Bing
    "bing.com/ads",
    "ads.microsoft.com",

    # Algemene ad-netwerken
    "outbrain.com",
    "taboola.com",
    "criteo.com",
    "criteo.net",
    "adsrvr.org",
    "pubmatic.com",
    "rubiconproject.com",
    "openx.net",
    "adnxs.com",
    "advertising.com",
    "moatads.com",
    "scorecardresearch.com",
    "quantserve.com",

    # Tracking / analytics
    "hotjar.com",
    "mouseflow.com",
    "fullstory.com",
    "mixpanel.com",
    "segment.io",
    "segment.com",
    "amplitude.com",
}


class AdBlockInterceptor(QWebEngineUrlRequestInterceptor):
    """
    Blokkeer netwerk-verzoeken naar bekende advertentie-hosts.

    Werkt op profile-niveau, dus elke tab in dat profiel krijgt de
    interceptor. Toepassen via:
        profile.setUrlRequestInterceptor(AdBlockInterceptor())
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self._enabled = True
        self._blocked_count = 0

    def set_enabled(self, on: bool):
        """Zet adblock aan of uit."""
        self._enabled = on

    def is_enabled(self) -> bool:
        return self._enabled

    def blocked_count(self) -> int:
        """Aantal blokkades sinds opstart."""
        return self._blocked_count

    def interceptRequest(self, info):
        """Wordt aangeroepen voor élk netwerk-verzoek."""
        if not self._enabled:
            return
        url = info.requestUrl().toString().lower()
        for blocked in BLOCKED_HOSTS:
            if blocked in url:
                info.block(True)
                self._blocked_count += 1
                # Niet loggen — anders raakt de log vol op zware sites
                return


# ============================================================
# VAULT — AES-256-GCM wachtwoordkluis
# ============================================================

"""
core/vault.py - Versleutelde wachtwoordkluis.

ENCRYPTIE-OPZET
===============

Master-password → PBKDF2-HMAC-SHA256 (600.000 iteraties) → 32-byte AES-key
                                                              ↓
Per entry: AES-256-GCM encryptie met random 12-byte nonce per encrypt
           Output: nonce + ciphertext + auth-tag (samen base64-encoded)

Het master-password wordt NOOIT opgeslagen — alleen een verifier-blob
(known plaintext "DRAVENLOCK_VAULT_OK" versleuteld) zodat we kunnen
controleren of een ingevoerd password correct is.

BESTANDSFORMAAT (vault.enc)
==========================
{
  "version": 1,
  "salt": "<base64 16 bytes>",
  "iterations": 600000,
  "verifier": "<base64 encrypted verifier>",
  "recovery_enabled": false,
  "recovery_blob": null,  // alleen als recovery aan staat
  "entries": [
    {
      "id": "v_<uuid>",
      "data": "<base64 encrypted JSON-entry>",
      "added": 1717000000,
      "modified": 1717000000
    }
  ]
}

Een entry plaintext (vóór encryptie) is een JSON met:
  {site, username, password, url, notes}
"""
import base64
import json
import os
import secrets
import sys
import time
import uuid
from pathlib import Path
from typing import Optional, List, Dict, Tuple

try:
    from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    _CRYPTO_OK = True
except ImportError as e:
    _CRYPTO_OK = False
    _CRYPTO_ERROR = str(e)


# Bekende plaintext om master-password te verifiëren
VERIFIER_PLAINTEXT = b"DRAVENLOCK_VAULT_OK_v1"

# PBKDF2 iteraties — NIST 2024 aanbeveling is 600.000+ voor SHA-256
PBKDF2_ITERATIONS = 600_000

# AES-GCM nonce-grootte (12 bytes is standaard)
NONCE_SIZE = 12
SALT_SIZE = 16
KEY_SIZE = 32  # AES-256


def is_crypto_available() -> bool:
    """True als de cryptography library beschikbaar is."""
    return _CRYPTO_OK


def crypto_error_message() -> str:
    """Foutmelding als cryptography niet beschikbaar is."""
    if _CRYPTO_OK:
        return ""
    return (
        f"De 'cryptography' library is niet geïnstalleerd. "
        f"Voer uit: pip install cryptography\n\n"
        f"Originele fout: {_CRYPTO_ERROR}"
    )


# ----------------------------------------------------------------------
# Lokatie van vault-bestand
# ----------------------------------------------------------------------
def get_vault_file() -> Path:
    """Geef het pad naar vault.enc terug."""
    try:
        # (intra-import gestript: from core.paths import data_dir)
        return data_dir() / "vault.enc"
    except Exception:
        # Fallback als paths-module niet beschikbaar
        if getattr(sys, "frozen", False):
            return Path(sys.executable).resolve().parent / "vault.enc"
        return Path(sys.argv[0]).resolve().parent / "vault.enc"


# ----------------------------------------------------------------------
# Lage-niveau crypto-helpers
# ----------------------------------------------------------------------
def derive_key(password: str, salt: bytes,
               iterations: int = PBKDF2_ITERATIONS) -> bytes:
    """
    Leid een 256-bit AES-key af uit master-password + salt.

    PBKDF2-HMAC-SHA256 met 600.000 iteraties (NIST 2024 aanbeveling).
    Dit maakt brute-force aanvallen extreem duur — een aanvaller moet
    600k SHA-256 berekeningen doen per password-poging.
    """
    if not _CRYPTO_OK:
        raise RuntimeError(crypto_error_message())
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=KEY_SIZE,
        salt=salt,
        iterations=iterations,
    )
    return kdf.derive(password.encode("utf-8"))


def encrypt_data(plaintext: bytes, key: bytes) -> str:
    """
    Versleutel data met AES-256-GCM en geef terug als base64-string.

    Format: nonce(12) + ciphertext + auth-tag(16)
    """
    aesgcm = AESGCM(key)
    nonce = secrets.token_bytes(NONCE_SIZE)
    ciphertext = aesgcm.encrypt(nonce, plaintext, None)
    blob = nonce + ciphertext  # ciphertext bevat al de auth-tag
    return base64.b64encode(blob).decode("ascii")


def decrypt_data(blob_b64: str, key: bytes) -> bytes:
    """
    Ontsleutel een base64-blob terug naar plaintext.
    Werpt InvalidTag als de key fout is of de data is gewijzigd.
    """
    blob = base64.b64decode(blob_b64)
    nonce = blob[:NONCE_SIZE]
    ciphertext = blob[NONCE_SIZE:]
    aesgcm = AESGCM(key)
    return aesgcm.decrypt(nonce, ciphertext, None)


# ----------------------------------------------------------------------
# Vault-klasse
# ----------------------------------------------------------------------
class Vault:
    """
    Versleutelde wachtwoordkluis.

    Werkstroom:
        v = Vault()
        if not v.exists():
            v.create("mijn-master-password")  # eerste keer
        v.unlock("mijn-master-password")  # daarna
        v.add_entry("Site", "user", "pass")
        v.lock()
    """

    def __init__(self):
        self._file = get_vault_file()
        self._key: Optional[bytes] = None  # actieve AES-key (na unlock)
        self._data: Dict = {}              # vault-bestand inhoud
        self._unlocked = False
        self._last_activity = 0.0          # voor auto-lock

    def file_path(self) -> Path:
        return self._file

    def exists(self) -> bool:
        """True als er al een vault.enc is."""
        return self._file.exists()

    def is_unlocked(self) -> bool:
        return self._unlocked

    # ------------------------------------------------------------------
    # Aanmaken / unlock / lock
    # ------------------------------------------------------------------
    def create(self, master_password: str,
               enable_recovery: bool = False,
               recovery_code: Optional[str] = None) -> bool:
        """
        Maak een nieuwe vault aan met dit master-password.

        Als enable_recovery=True, dan moet recovery_code worden meegegeven —
        die wordt gebruikt om een tweede versie van de key te versleutelen,
        zodat de vault ook geopend kan worden met de recovery code.

        Faalt als er al een vault bestaat (geen overschrijven).
        """
        if not _CRYPTO_OK:
            raise RuntimeError(crypto_error_message())
        if self.exists():
            raise RuntimeError("Er bestaat al een vault. Verwijder hem "
                               "eerst handmatig als je opnieuw wilt beginnen.")
        if not master_password or len(master_password) < 1:
            raise ValueError("Master-password mag niet leeg zijn")

        salt = secrets.token_bytes(SALT_SIZE)
        key = derive_key(master_password, salt)

        # Verifier: versleutel een bekende plaintext zodat we later kunnen
        # checken of een ingevoerd password klopt
        verifier = encrypt_data(VERIFIER_PLAINTEXT, key)

        data = {
            "version": 1,
            "salt": base64.b64encode(salt).decode("ascii"),
            "iterations": PBKDF2_ITERATIONS,
            "verifier": verifier,
            "recovery_enabled": False,
            "recovery_blob": None,
            "entries": [],
        }

        # Recovery: leid een TWEEDE key af uit de recovery_code en versleutel
        # daarmee de ECHTE key. Zo kan iemand met de recovery-code de
        # echte key herstellen — zonder die ooit op disk te zien.
        if enable_recovery and recovery_code:
            recovery_salt = secrets.token_bytes(SALT_SIZE)
            recovery_key = derive_key(recovery_code, recovery_salt)
            # Versleutel de PRIMAIRE key zelf
            encrypted_primary = encrypt_data(key, recovery_key)
            data["recovery_enabled"] = True
            data["recovery_blob"] = {
                "salt": base64.b64encode(recovery_salt).decode("ascii"),
                "encrypted_key": encrypted_primary,
            }

        self._data = data
        self._save()
        self._key = key
        self._unlocked = True
        self._last_activity = time.time()
        print("[vault] nieuwe vault aangemaakt")
        return True

    def unlock(self, master_password: str) -> bool:
        """
        Open de vault met master-password. True bij succes, False bij
        fout password.
        """
        if not _CRYPTO_OK:
            raise RuntimeError(crypto_error_message())
        if not self.exists():
            raise RuntimeError("Geen vault aanwezig — gebruik create() eerst")
        self._load()

        salt = base64.b64decode(self._data["salt"])
        iterations = self._data.get("iterations", PBKDF2_ITERATIONS)
        key = derive_key(master_password, salt, iterations)

        # Verifier checken
        try:
            decrypted = decrypt_data(self._data["verifier"], key)
            if decrypted != VERIFIER_PLAINTEXT:
                return False
        except Exception:
            return False

        self._key = key
        self._unlocked = True
        self._last_activity = time.time()
        print("[vault] geopend met master-password")
        return True

    def unlock_with_recovery(self, recovery_code: str) -> bool:
        """
        Open vault met recovery-code (als ingesteld). True bij succes.

        Werkt als de gebruiker recovery had aangezet bij aanmaak. Dit
        herstelt de originele key, dus daarna kan worden gewerkt zoals
        bij een gewone unlock.
        """
        if not _CRYPTO_OK:
            raise RuntimeError(crypto_error_message())
        if not self.exists():
            raise RuntimeError("Geen vault aanwezig")
        self._load()
        if not self._data.get("recovery_enabled"):
            raise RuntimeError(
                "Recovery is niet ingeschakeld voor deze vault. "
                "Zonder master-password is er geen toegang mogelijk."
            )

        rb = self._data["recovery_blob"]
        recovery_salt = base64.b64decode(rb["salt"])
        recovery_key = derive_key(recovery_code, recovery_salt)
        try:
            primary_key = decrypt_data(rb["encrypted_key"], recovery_key)
        except Exception:
            return False

        # Verifier double-check
        try:
            decrypted = decrypt_data(self._data["verifier"], primary_key)
            if decrypted != VERIFIER_PLAINTEXT:
                return False
        except Exception:
            return False

        self._key = primary_key
        self._unlocked = True
        self._last_activity = time.time()
        print("[vault] geopend met recovery-code")
        return True

    def lock(self):
        """
        Sluit de vault. Wist de key uit geheugen. Daarna moet er
        opnieuw worden ge-unlocked.
        """
        if self._key is not None:
            # Best-effort overschrijven van de key in memory
            try:
                # Niet 100% veilig in Python (immutable bytes) maar wel
                # netjes voor onze intentie
                self._key = b"\x00" * KEY_SIZE
            except Exception:
                pass
        self._key = None
        self._unlocked = False
        print("[vault] gesloten")

    # ------------------------------------------------------------------
    # Activity tracking + auto-lock
    # ------------------------------------------------------------------
    def touch(self):
        """Markeer activiteit. Voor auto-lock-logica."""
        if self._unlocked:
            self._last_activity = time.time()

    def seconds_idle(self) -> float:
        """Tijd in seconden sinds laatste activiteit. 0 als gelocked."""
        if not self._unlocked:
            return 0.0
        return time.time() - self._last_activity

    def auto_lock_check(self, timeout_seconds: int) -> bool:
        """
        Lock automatisch als er te lang geen activiteit was.
        Returnt True als er werd gelocked.
        """
        if self._unlocked and self.seconds_idle() > timeout_seconds:
            self.lock()
            return True
        return False

    # ------------------------------------------------------------------
    # Master-password wijzigen
    # ------------------------------------------------------------------
    def change_master_password(self, current: str, new: str) -> bool:
        """
        Wijzig master-password. Vault moet ge-unlocked zijn EN we
        verifiëren ook nog 'current' tegen het verifier-blob.

        Strategie: ontsleutel alle entries met de oude key, genereer
        nieuwe salt + nieuwe key uit nieuw password, versleutel alles
        opnieuw, en sla op.
        """
        if not self._unlocked:
            raise RuntimeError("Vault moet eerst worden ge-unlocked")
        if not new:
            raise ValueError("Nieuw password mag niet leeg zijn")

        # Verifieer huidige password
        salt = base64.b64decode(self._data["salt"])
        iterations = self._data.get("iterations", PBKDF2_ITERATIONS)
        current_key = derive_key(current, salt, iterations)
        try:
            decrypted = decrypt_data(self._data["verifier"], current_key)
            if decrypted != VERIFIER_PLAINTEXT:
                return False
        except Exception:
            return False

        # Ontsleutel alle entries met huidige key
        plaintext_entries = []
        for e in self._data["entries"]:
            try:
                pt = decrypt_data(e["data"], self._key)
                plaintext_entries.append({
                    "id": e["id"],
                    "plaintext": pt,
                    "added": e.get("added", int(time.time())),
                    "modified": e.get("modified", int(time.time())),
                })
            except Exception as ex:
                print(f"[vault] entry {e['id']} kon niet ontsleuteld worden: {ex}")
                continue

        # Nieuwe salt + nieuwe key
        new_salt = secrets.token_bytes(SALT_SIZE)
        new_key = derive_key(new, new_salt)
        new_verifier = encrypt_data(VERIFIER_PLAINTEXT, new_key)

        # Versleutel alle entries opnieuw
        new_entries = []
        for e in plaintext_entries:
            new_entries.append({
                "id": e["id"],
                "data": encrypt_data(e["plaintext"], new_key),
                "added": e["added"],
                "modified": e["modified"],
            })

        # Recovery-blob ongeldig maken (gebruiker moet opnieuw instellen)
        self._data["salt"] = base64.b64encode(new_salt).decode("ascii")
        self._data["iterations"] = PBKDF2_ITERATIONS
        self._data["verifier"] = new_verifier
        self._data["entries"] = new_entries
        self._data["recovery_enabled"] = False
        self._data["recovery_blob"] = None

        self._save()
        self._key = new_key
        self._last_activity = time.time()
        print("[vault] master-password gewijzigd")
        return True

    # ------------------------------------------------------------------
    # CRUD voor entries
    # ------------------------------------------------------------------
    def _check_unlocked(self):
        if not self._unlocked:
            raise RuntimeError("Vault is vergrendeld — eerst unlock()")

    def add_entry(self, site: str, username: str, password: str,
                  url: str = "", notes: str = "") -> str:
        """Voeg een entry toe. Returnt het ID."""
        self._check_unlocked()
        entry_id = f"v_{uuid.uuid4().hex[:10]}"
        plaintext = json.dumps({
            "site": site,
            "username": username,
            "password": password,
            "url": url,
            "notes": notes,
        }, ensure_ascii=False).encode("utf-8")
        encrypted = encrypt_data(plaintext, self._key)
        now = int(time.time())
        self._data["entries"].append({
            "id": entry_id,
            "data": encrypted,
            "added": now,
            "modified": now,
        })
        self._save()
        self.touch()
        return entry_id

    def get_entry(self, entry_id: str) -> Optional[Dict]:
        """
        Ontsleutel en geef één entry terug, of None.
        Returnt: {id, site, username, password, url, notes, added, modified}
        """
        self._check_unlocked()
        for e in self._data["entries"]:
            if e["id"] == entry_id:
                try:
                    pt = decrypt_data(e["data"], self._key)
                    fields = json.loads(pt.decode("utf-8"))
                    fields["id"] = entry_id
                    fields["added"] = e.get("added", 0)
                    fields["modified"] = e.get("modified", 0)
                    self.touch()
                    return fields
                except Exception as ex:
                    print(f"[vault] decrypt faalde voor {entry_id}: {ex}")
                    return None
        return None

    def list_entries(self) -> List[Dict]:
        """
        Geef ALLE entries terug, ontsleuteld.

        Let op: dit ontsleutelt alles in geheugen. Voor display in een
        lijst is dit normaal — bij sluiten gaat het direct weg.
        """
        self._check_unlocked()
        out = []
        for e in self._data["entries"]:
            try:
                pt = decrypt_data(e["data"], self._key)
                fields = json.loads(pt.decode("utf-8"))
                fields["id"] = e["id"]
                fields["added"] = e.get("added", 0)
                fields["modified"] = e.get("modified", 0)
                out.append(fields)
            except Exception as ex:
                print(f"[vault] decrypt faalde voor {e['id']}: {ex}")
        self.touch()
        return out

    def update_entry(self, entry_id: str, **kwargs) -> bool:
        """
        Wijzig velden van een entry. Geldige kwargs:
        site, username, password, url, notes.
        """
        self._check_unlocked()
        for e in self._data["entries"]:
            if e["id"] == entry_id:
                # Ontsleutel, wijzig, opnieuw versleutel
                try:
                    pt = decrypt_data(e["data"], self._key)
                    fields = json.loads(pt.decode("utf-8"))
                except Exception:
                    return False
                for k in ("site", "username", "password", "url", "notes"):
                    if k in kwargs:
                        fields[k] = kwargs[k]
                new_pt = json.dumps(fields, ensure_ascii=False).encode("utf-8")
                e["data"] = encrypt_data(new_pt, self._key)
                e["modified"] = int(time.time())
                self._save()
                self.touch()
                return True
        return False

    def remove_entry(self, entry_id: str) -> bool:
        """Verwijder een entry."""
        self._check_unlocked()
        before = len(self._data["entries"])
        self._data["entries"] = [
            e for e in self._data["entries"] if e["id"] != entry_id
        ]
        if len(self._data["entries"]) < before:
            self._save()
            self.touch()
            return True
        return False

    def find_for_url(self, url: str) -> List[Dict]:
        """
        Zoek entries waarvan de URL overeenkomt met de gegeven URL.
        Gebruikt host-vergelijking (bv. accounts.google.com matcht google.com).
        """
        self._check_unlocked()
        from urllib.parse import urlparse
        try:
            target_host = urlparse(url).hostname or ""
        except Exception:
            return []
        if not target_host:
            return []
        target_host = target_host.lower()

        matches = []
        for entry in self.list_entries():
            entry_url = entry.get("url", "")
            if not entry_url:
                continue
            try:
                entry_host = (urlparse(entry_url).hostname or "").lower()
            except Exception:
                continue
            if not entry_host:
                continue
            # Match: identiek, of doelsite is subdomein van entry
            if target_host == entry_host or target_host.endswith("." + entry_host):
                matches.append(entry)
        return matches

    def count(self) -> int:
        """Aantal entries (zonder unlock)."""
        if not self._data and self.exists():
            self._load()
        return len(self._data.get("entries", []))

    # ------------------------------------------------------------------
    # Recovery beheren
    # ------------------------------------------------------------------
    def has_recovery(self) -> bool:
        if not self._data and self.exists():
            self._load()
        return bool(self._data.get("recovery_enabled"))

    def set_recovery(self, recovery_code: Optional[str]):
        """
        Stel een recovery-code in (None = uitschakelen).
        Vault moet ge-unlocked zijn (we hebben de primaire key nodig).
        """
        self._check_unlocked()
        if not recovery_code:
            self._data["recovery_enabled"] = False
            self._data["recovery_blob"] = None
        else:
            recovery_salt = secrets.token_bytes(SALT_SIZE)
            recovery_key = derive_key(recovery_code, recovery_salt)
            encrypted_primary = encrypt_data(self._key, recovery_key)
            self._data["recovery_enabled"] = True
            self._data["recovery_blob"] = {
                "salt": base64.b64encode(recovery_salt).decode("ascii"),
                "encrypted_key": encrypted_primary,
            }
        self._save()

    # ------------------------------------------------------------------
    # Bestand-I/O
    # ------------------------------------------------------------------
    def _load(self):
        if not self._file.exists():
            return
        try:
            with open(self._file, "r", encoding="utf-8") as f:
                self._data = json.load(f)
        except Exception as e:
            print(f"[vault] load faalde: {e}")
            raise RuntimeError(f"Vault-bestand kan niet worden gelezen: {e}")

    def _save(self):
        try:
            # Atomair schrijven: eerst naar .tmp, dan rename
            tmp = self._file.with_suffix(self._file.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self._data, f, indent=2, ensure_ascii=False)
            # Op Windows kan rename naar bestaand bestand falen — eerst weg
            if self._file.exists():
                self._file.unlink()
            tmp.rename(self._file)
        except Exception as e:
            print(f"[vault] save faalde: {e}")
            raise


# Singleton — met unieke prefix om collision met andere managers te voorkomen
_vault_instance: Optional[Vault] = None


def get_vault() -> Vault:
    global _vault_instance
    if _vault_instance is None:
        _vault_instance = Vault()
    return _vault_instance


# ----------------------------------------------------------------------
# Password-generator (handig voor "wachtwoord genereren" knop)
# ----------------------------------------------------------------------
def generate_password(length: int = 20,
                      include_symbols: bool = True,
                      exclude_ambiguous: bool = True) -> str:
    """
    Genereer een veilig random wachtwoord.

    exclude_ambiguous: laat 0/O, 1/l/I weg om typfouten te voorkomen.
    """
    import string
    alphabet = string.ascii_letters + string.digits
    if include_symbols:
        alphabet += "!@#$%^&*-_=+?"
    if exclude_ambiguous:
        ambiguous = "0O1lI"
        alphabet = "".join(c for c in alphabet if c not in ambiguous)
    return "".join(secrets.choice(alphabet) for _ in range(length))


def password_strength(password: str) -> Tuple[int, str]:
    """
    Schat de sterkte van een wachtwoord.
    Returnt (score 0-100, label-string).
    """
    if not password:
        return 0, "Leeg"
    score = 0
    length = len(password)
    # Lengte-component
    score += min(50, length * 4)
    # Variatie-component
    has_lower = any(c.islower() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_digit = any(c.isdigit() for c in password)
    has_symbol = any(not c.isalnum() for c in password)
    variety = sum([has_lower, has_upper, has_digit, has_symbol])
    score += variety * 12
    # Veel herhaling = aftrekken
    unique_chars = len(set(password))
    if unique_chars < length / 2:
        score -= 10
    score = max(0, min(100, score))

    if score < 30:
        label = "Zeer zwak"
    elif score < 50:
        label = "Zwak"
    elif score < 70:
        label = "Matig"
    elif score < 85:
        label = "Sterk"
    else:
        label = "Zeer sterk"
    return score, label


# ============================================================
# AUTOFILL — JS-injectie voor login-formulieren
# ============================================================

"""
core/autofill.py - Veilige auto-fill voor login-formulieren.

WERKWIJZE
=========
1. Python-zijde haalt entry op uit de vault (die moet ge-unlocked zijn)
2. Het credentials-dict {username, password} wordt via json.dumps()
   serialized — NOOIT via string-concatenatie ingevoegd in JS
3. De JS-functie krijgt het object als argument, niet als embedded string
4. JS zoekt de juiste velden en vult ze in, met fallbacks per veld-type

VEILIGHEID
==========
- Credentials worden alleen ingevoegd via een tijdelijke variabele
  binnen een IIFE (immediately-invoked function expression) zodat ze
  niet aan window blijven hangen
- We bewerken NOOIT velden met type="hidden" (kan een trap zijn)
- We focussen op login-formulieren — andere formulieren (zoek, etc)
  blijven onaangetast
- Bij events: dispatching van 'input' en 'change' zodat moderne
  frameworks (React, Vue) doorhebben dat het veld gewijzigd is
"""
import json

# JavaScript-template voor het invullen. Wordt aangeroepen met:
#   runJavaScript(AUTOFILL_JS.replace("__CREDS__", json.dumps(creds)))
# Het __CREDS__ token wordt vervangen door een geldig JSON-object —
# json.dumps() zorgt voor correcte escaping (geen apostrof-bug).
AUTOFILL_JS = r"""
(function() {
    'use strict';
    try {
        var creds = __CREDS__;
        if (!creds || typeof creds !== 'object') {
            return JSON.stringify({ok: false, reason: 'invalid_creds'});
        }

        var username = creds.username || '';
        var password = creds.password || '';

        // Strategie: zoek visible password-veld eerst (sterkste signaal voor
        // login-formulier). Werk vandaaruit terug naar het bijbehorende
        // username-veld (zelfde form, of het dichtstbij liggend input).

        function isVisible(el) {
            if (!el) return false;
            if (el.type === 'hidden') return false;
            if (el.disabled) return false;
            var style = window.getComputedStyle(el);
            if (style.display === 'none') return false;
            if (style.visibility === 'hidden') return false;
            var rect = el.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return false;
            return true;
        }

        function setValue(el, value) {
            if (!el || !value) return false;
            // React/Vue trick: stel waarde in via native setter zodat
            // de framework de wijziging detecteert
            var nativeSetter = Object.getOwnPropertyDescriptor(
                window.HTMLInputElement.prototype, 'value'
            ).set;
            nativeSetter.call(el, value);
            // Trigger events die frameworks verwachten
            el.dispatchEvent(new Event('input', {bubbles: true}));
            el.dispatchEvent(new Event('change', {bubbles: true}));
            return true;
        }

        // 1. Vind het wachtwoord-veld
        var passwordFields = Array.from(
            document.querySelectorAll('input[type="password"]')
        ).filter(isVisible);

        if (passwordFields.length === 0) {
            return JSON.stringify({
                ok: false, reason: 'no_password_field',
                found_inputs: document.querySelectorAll('input').length
            });
        }

        // Bij meerdere password-velden: pak het eerste zichtbare
        // (bij register-formulieren staat password vaak boven confirm)
        var pwdField = passwordFields[0];

        // 2. Vind het username-veld — meerdere strategieën in volgorde
        var userField = null;

        // 2a. In hetzelfde form, eerste text/email-input boven het password
        var form = pwdField.form;
        if (form) {
            var formInputs = Array.from(form.querySelectorAll(
                'input[type="text"], input[type="email"], input[type="tel"], input:not([type])'
            )).filter(isVisible);

            // Eerst proberen: dat input dat directly above the password staat
            // (in document-volgorde)
            for (var i = 0; i < formInputs.length; i++) {
                if (formInputs[i].compareDocumentPosition(pwdField)
                        & Node.DOCUMENT_POSITION_FOLLOWING) {
                    userField = formInputs[i];
                    // Niet breaken — laatste match vóór password is beter
                }
            }
        }

        // 2b. Fallback: ALLE inputs op de pagina
        if (!userField) {
            var allInputs = Array.from(document.querySelectorAll(
                'input[type="text"], input[type="email"], input[type="tel"], input:not([type])'
            )).filter(isVisible);
            for (var i = 0; i < allInputs.length; i++) {
                if (allInputs[i].compareDocumentPosition(pwdField)
                        & Node.DOCUMENT_POSITION_FOLLOWING) {
                    userField = allInputs[i];
                }
            }
        }

        // 2c. Heuristisch op autocomplete/name attribute
        if (!userField) {
            var candidates = document.querySelectorAll(
                'input[autocomplete="username"], input[autocomplete="email"], ' +
                'input[name*="user" i], input[name*="email" i], ' +
                'input[name*="login" i], input[id*="user" i], input[id*="email" i]'
            );
            for (var i = 0; i < candidates.length; i++) {
                if (isVisible(candidates[i])) {
                    userField = candidates[i];
                    break;
                }
            }
        }

        // 3. Vul de velden in
        var filled = {username: false, password: false};
        if (userField && username) {
            filled.username = setValue(userField, username);
        }
        if (pwdField && password) {
            filled.password = setValue(pwdField, password);
        }

        // Focus laatste ingevulde veld zodat user direct submit kan
        if (filled.password) {
            try { pwdField.focus(); } catch(e) {}
        }

        // Schoonmaak: wis lokale variabelen die credentials hadden
        creds = null;
        username = '';
        password = '';

        return JSON.stringify({
            ok: true,
            filled_username: filled.username,
            filled_password: filled.password,
            user_field_found: userField !== null,
            password_fields_found: passwordFields.length,
        });
    } catch (e) {
        return JSON.stringify({ok: false, reason: 'exception',
                               error: String(e)});
    }
})();
"""


def build_autofill_script(username: str, password: str) -> str:
    """
    Bouw een uitvoerbaar JS-script door __CREDS__ te vervangen door
    het JSON-object met credentials.

    Gebruik json.dumps() — niet handmatig string-formatteren.
    Dit voorkomt apostrof/quote-bugs uit de oude browser.py.
    """
    creds = {"username": username or "", "password": password or ""}
    creds_json = json.dumps(creds)
    return AUTOFILL_JS.replace("__CREDS__", creds_json)


def parse_autofill_result(raw) -> dict:
    """
    Parseer het JSON-resultaat van AUTOFILL_JS terug naar een dict.

    De JS gebruikt JSON.stringify() — Qt kan het als string of dict
    teruggeven, afhankelijk van versie. We handlen beide.

    Geleerde les uit DeskButler: PySide6 marshaling van complexe
    objecten geeft soms JSON-string ipv dict.
    """
    if raw is None:
        return {"ok": False, "reason": "callback_null"}
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str):
        try:
            return json.loads(raw)
        except Exception as e:
            return {"ok": False, "reason": "parse_error", "error": str(e)}
    return {"ok": False, "reason": "unexpected_type",
            "type": type(raw).__name__}


# ============================================================
# FAVORITES — favorieten met mappen
# ============================================================

"""
core/favorites.py - Beheer van browser-favorieten met mappen.

Opslag: <data-dir>/favorites.json
Structuur:
{
  "folders": [
    {
      "id": "f_1234",
      "name": "Werk",
      "favorites": [
        {"id": "b_5678", "title": "...", "url": "...", "added": 1717000000}
      ]
    }
  ],
  "root_favorites": [
    {"id": "b_root1", "title": "...", "url": "...", "added": 1717000000}
  ]
}

Favorieten in 'root_favorites' staan los van een map.

Migratie uit DeskButler — daar al uitgebreid getest. Aanpassingen:
- Gebruikt onze core/paths.py voor de bestandslocatie
- Unieke singleton-naam (_favorites_manager) zoals afgesproken na de
  collision-bug uit DeskButler v6.7
"""
import json
import time
import uuid
from pathlib import Path
from typing import Optional, List, Dict

# (intra-import gestript: from core.paths import data_dir)


def get_favorites_file() -> Path:
    """Het pad naar favorites.json."""
    return data_dir() / "favorites.json"


class FavoritesManager:
    """
    Centraal beheer van favorieten met mappen.

    API:
        mgr = get_favorites_manager()
        mgr.add(title, url, folder_id=None)
        mgr.remove(fav_id)
        mgr.add_folder(name)
        mgr.remove_folder(folder_id)
        mgr.rename_folder(folder_id, new_name)
        mgr.move_to_folder(fav_id, folder_id)
        mgr.all_folders()
        mgr.root_favorites()
        mgr.find(fav_id)
        mgr.is_favorited(url)
    """

    def __init__(self):
        self._file = get_favorites_file()
        self._data: Dict = {"folders": [], "root_favorites": []}
        self._load()

    def _load(self):
        if not self._file.exists():
            return
        try:
            with open(self._file, "r", encoding="utf-8") as f:
                self._data = json.load(f)
            if "folders" not in self._data:
                self._data["folders"] = []
            if "root_favorites" not in self._data:
                self._data["root_favorites"] = []
        except Exception as e:
            print(f"[favorites] laden faalde: {e}")
            self._data = {"folders": [], "root_favorites": []}

    def _save(self):
        try:
            # Atomair schrijven: eerst naar .tmp, dan rename
            tmp = self._file.with_suffix(self._file.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(self._data, f, indent=2, ensure_ascii=False)
            if self._file.exists():
                self._file.unlink()
            tmp.rename(self._file)
        except Exception as e:
            print(f"[favorites] opslaan faalde: {e}")

    # ------------------------------------------------------------------
    # Favorieten
    # ------------------------------------------------------------------
    def add(self, title: str, url: str,
            folder_id: Optional[str] = None) -> Optional[str]:
        """
        Voeg een favoriet toe. Retourneert het ID, of None bij duplicaat.
        Bij duplicate URL (waar dan ook): niet toevoegen.
        """
        if self._url_exists(url):
            print(f"[favorites] URL bestaat al: {url}")
            return None
        fav_id = f"b_{uuid.uuid4().hex[:10]}"
        item = {
            "id": fav_id,
            "title": (title or url)[:200],
            "url": url,
            "added": int(time.time()),
        }
        if folder_id:
            folder = self._find_folder(folder_id)
            if folder is not None:
                folder["favorites"].append(item)
            else:
                self._data["root_favorites"].append(item)
        else:
            self._data["root_favorites"].append(item)
        self._save()
        return fav_id

    def remove(self, fav_id: str) -> bool:
        """Verwijder een favoriet ongeacht waar hij staat."""
        before = len(self._data["root_favorites"])
        self._data["root_favorites"] = [
            f for f in self._data["root_favorites"] if f["id"] != fav_id
        ]
        if len(self._data["root_favorites"]) < before:
            self._save()
            return True
        for folder in self._data["folders"]:
            before = len(folder["favorites"])
            folder["favorites"] = [
                f for f in folder["favorites"] if f["id"] != fav_id
            ]
            if len(folder["favorites"]) < before:
                self._save()
                return True
        return False

    def update(self, fav_id: str, title: str = None,
               url: str = None) -> bool:
        """Wijzig een bestaande favoriet."""
        fav = self.find(fav_id)
        if not fav:
            return False
        if title is not None:
            fav["title"] = title[:200]
        if url is not None:
            fav["url"] = url
        self._save()
        return True

    def move_to_folder(self, fav_id: str,
                       folder_id: Optional[str]) -> bool:
        """Verplaats een favoriet naar een map (None = root)."""
        fav = self.find(fav_id)
        if not fav:
            return False
        # Verwijder uit huidige plek
        self._data["root_favorites"] = [
            f for f in self._data["root_favorites"] if f["id"] != fav_id
        ]
        for folder in self._data["folders"]:
            folder["favorites"] = [
                f for f in folder["favorites"] if f["id"] != fav_id
            ]
        # Plaats op nieuwe plek
        if folder_id:
            target = self._find_folder(folder_id)
            if target:
                target["favorites"].append(fav)
            else:
                self._data["root_favorites"].append(fav)
        else:
            self._data["root_favorites"].append(fav)
        self._save()
        return True

    def find(self, fav_id: str) -> Optional[Dict]:
        """Zoek een favoriet op ID."""
        for f in self._data["root_favorites"]:
            if f["id"] == fav_id:
                return f
        for folder in self._data["folders"]:
            for f in folder["favorites"]:
                if f["id"] == fav_id:
                    return f
        return None

    def find_by_url(self, url: str) -> Optional[Dict]:
        """Zoek een favoriet op URL."""
        for f in self._data["root_favorites"]:
            if f["url"] == url:
                return f
        for folder in self._data["folders"]:
            for f in folder["favorites"]:
                if f["url"] == url:
                    return f
        return None

    def _url_exists(self, url: str) -> bool:
        return self.find_by_url(url) is not None

    def is_favorited(self, url: str) -> bool:
        """Check of een URL al een favoriet is."""
        return self._url_exists(url)

    # ------------------------------------------------------------------
    # Mappen
    # ------------------------------------------------------------------
    def add_folder(self, name: str) -> str:
        """Maak een nieuwe map aan."""
        folder_id = f"f_{uuid.uuid4().hex[:10]}"
        self._data["folders"].append({
            "id": folder_id,
            "name": name[:80],
            "favorites": [],
        })
        self._save()
        return folder_id

    def remove_folder(self, folder_id: str,
                      move_to_root: bool = True) -> bool:
        """
        Verwijder een map. Bij move_to_root=True gaan de favorieten in
        die map naar root (anders worden ook zij verwijderd).
        """
        target = self._find_folder(folder_id)
        if not target:
            return False
        if move_to_root and target["favorites"]:
            self._data["root_favorites"].extend(target["favorites"])
        self._data["folders"] = [
            f for f in self._data["folders"] if f["id"] != folder_id
        ]
        self._save()
        return True

    def rename_folder(self, folder_id: str, new_name: str) -> bool:
        folder = self._find_folder(folder_id)
        if not folder:
            return False
        folder["name"] = new_name[:80]
        self._save()
        return True

    def _find_folder(self, folder_id: str) -> Optional[Dict]:
        for f in self._data["folders"]:
            if f["id"] == folder_id:
                return f
        return None

    # ------------------------------------------------------------------
    # Lezen
    # ------------------------------------------------------------------
    def all_folders(self) -> List[Dict]:
        return list(self._data["folders"])

    def root_favorites(self) -> List[Dict]:
        return list(self._data["root_favorites"])

    def total_count(self) -> int:
        n = len(self._data["root_favorites"])
        for f in self._data["folders"]:
            n += len(f["favorites"])
        return n


# Singleton — unieke prefix om collision met andere managers te voorkomen
# (lesson learned uit DeskButler v6.7: _manager botst tussen modules in
# single-file build)
_favorites_manager: Optional[FavoritesManager] = None


def get_favorites_manager() -> FavoritesManager:
    global _favorites_manager
    if _favorites_manager is None:
        _favorites_manager = FavoritesManager()
    return _favorites_manager


# ============================================================
# EXTENSIONS — userscript-systeem
# ============================================================

"""
core/browser_extensions.py - Browser-extensies systeem.

Een lichtgewicht userscript-systeem waarmee JavaScript wordt
geïnjecteerd in webpagina's. Geen volledige Tampermonkey-clone,
wel een werkbare subset met de meest gebruikte features.

ARCHITECTUUR
============

  ExtensionsManager (singleton)
    │
    ├── ingebouwde extensies (vast in code, niet bewerkbaar):
    │     - YouTube zonder ads
    │     - Cookie-meldingen automatisch accepteren
    │     - Eenvoudige Dark Reader (CSS filter)
    │
    └── gebruikers-extensies (toegevoegd via UI, in extensions.json):
          - Eigen scripts via editor

GEBRUIK IN BROWSER
==================

In WebTab.load_finished signal:
    manager = get_extensions_manager()
    for ext in manager.enabled_for_url(url):
        page.runJavaScript(ext.js)

OPSLAG (extensions.json)
========================

Alleen gebruikers-extensies én aan/uit-status. Builtin-scripts staan
in code (read-only). Bestand:

{
  "user_extensions": [
    {"id": "u_...", "name": "...", "description": "...",
     "url_pattern": "*", "js": "...", "enabled": true}
  ],
  "builtin_states": {
    "youtube_ads_bypass": false,
    "cookie_accept": true,
    ...
  }
}
"""
import json
import uuid
import fnmatch
from pathlib import Path
from typing import List, Optional, Dict
from urllib.parse import urlparse

# (intra-import gestript: from core.paths import data_dir)


def get_extensions_file() -> Path:
    """Het pad naar extensions.json."""
    return data_dir() / "extensions.json"


# ----------------------------------------------------------------------
# BrowserExtension class
# ----------------------------------------------------------------------
class BrowserExtension:
    """
    Een browser-extensie = stukje JS dat in passende pagina's draait.

    Velden:
      ext_id      : unieke ID
      name        : zichtbare naam
      description : uitleg voor gebruiker
      url_pattern : glob-patroon waar het script werkt ('*' = alles)
      js          : de JavaScript-code zelf
      enabled     : aan/uit
      type_       : 'builtin' of 'user' (builtin is read-only)
    """

    def __init__(self, ext_id: str, name: str, description: str,
                 js: str, url_pattern: str = "*",
                 enabled: bool = False, type_: str = "user"):
        self.ext_id = ext_id
        self.name = name
        self.description = description
        self.url_pattern = url_pattern or "*"
        self.js = js
        self.enabled = enabled
        self.type = type_

    def matches_url(self, url: str) -> bool:
        """Check of deze extensie voor een gegeven URL geldt."""
        if not url:
            return False
        if self.url_pattern == "*" or not self.url_pattern:
            return True
        # Eenvoudig glob-patroon match (case-insensitive)
        url_lower = url.lower()
        pattern = self.url_pattern.lower()
        if fnmatch.fnmatch(url_lower, pattern):
            return True
        # Probeer ook alleen host-match voor "*example.com*" stijl patterns
        try:
            host = urlparse(url).hostname or ""
            if host and fnmatch.fnmatch(host.lower(), pattern):
                return True
        except Exception:
            pass
        return False

    def to_dict(self) -> dict:
        """Serialiseren voor JSON-opslag."""
        return {
            "id": self.ext_id,
            "name": self.name,
            "description": self.description,
            "url_pattern": self.url_pattern,
            "js": self.js,
            "enabled": self.enabled,
        }


# ----------------------------------------------------------------------
# Ingebouwde extensies — vaste set, niet bewerkbaar
# ----------------------------------------------------------------------

# 1. YouTube Ads-Bypass (gebaseerd op MIT-licensed greasyfork-script
#    door WakeUpNeo, met onze taal-aanpassing en kortere code)
_YOUTUBE_ADS_BYPASS_JS = r"""
(function() {
    if (window.__dravenlock_yt_ads) return;
    window.__dravenlock_yt_ads = true;
    if (!/youtube\.com/.test(location.host)) return;
    'use strict';

    var SELECTORS_HIDE = [
        '.ytp-ad-message-container',
        'ytd-player-legacy-desktop-watch-ads-renderer',
        'ytd-ad-slot-renderer',
        '#masthead-ad',
        '.yt-mealbar-promo-renderer',
        '.ytp-ad-player-overlay-layout__player-card-container',
        '.ytp-ad-player-overlay',
        '.ad-showing > video',
        '.ad-interrupting > video',
        '#player-ads',
        '.ytp-ad-image-overlay',
        '.ytp-cued-thumbnail-overlay',
        '.ytp-ad-avatar',
        '.ytp-ad-button-vm',
        'ytd-rich-item-renderer:has(ytd-ad-slot-renderer)',
        'ytd-in-feed-ad-layout-renderer'
    ];

    var s = document.createElement('style');
    s.textContent = SELECTORS_HIDE.join(', ') +
        ' { display:flex !important; visibility:hidden !important; ' +
        'opacity:0 !important; pointer-events:none !important; ' +
        'height:1px !important; width:1px !important; overflow:hidden !important; }' +
        '.ytp-ad-skip-button-modern, .ytp-skip-ad-button, .ytp-ad-skip-button ' +
        '{ display:flex !important; border:1px solid yellow !important; ' +
        'background-color:rgba(247,241,40,0.6) !important; }';
    (document.head || document.documentElement).appendChild(s);

    var player = null, obs = null, video = null;
    var lastSkip = 0, adActive = false;

    function isAdActive() {
        return player && (
            player.classList.contains('ad-showing') ||
            player.classList.contains('ad-interrupting')
        );
    }

    function skipAd() {
        if (!video) return;
        if (!video.muted) { video.muted = true; }
        if (video.playbackRate !== 2.0) { video.playbackRate = 2.0; }
        if (isFinite(video.duration) && video.duration > 0) {
            video.currentTime = video.duration - 0.1;
        }
        if (video.paused) { try { video.play(); } catch(e){} }
    }

    function check() {
        if (!video || !video.isConnected) video = document.querySelector('video');
        if (!video) return;
        var now = Date.now();
        if (now - lastSkip < 500) return;
        lastSkip = now;
        if (isAdActive()) {
            adActive = true;
            skipAd();
        } else if (adActive) {
            adActive = false;
            if (video.muted) video.muted = false;
            if (video.playbackRate > 1) video.playbackRate = 1;
        }
    }

    function setup() {
        player = document.querySelector('#movie_player, .html5-video-player');
        if (player && !obs) {
            obs = new MutationObserver(check);
            obs.observe(player, {attributes: true, attributeFilter: ['class']});
            check();
        }
    }

    window.addEventListener('yt-navigate-finish', setup);
    window.addEventListener('yt-page-data-updated', setup);
    window.addEventListener('load', setup);

    var tries = 0;
    var retry = setInterval(function() {
        setup();
        if (obs || tries > 10) clearInterval(retry);
        tries++;
    }, 1000);

    console.log('[Dravenlock] YouTube Ads-Bypass actief');
})();
"""

# 2. Cookie-meldingen automatisch wegklikken
_COOKIE_ACCEPT_JS = r"""
(function() {
    if (window.__dravenlock_cookie) return;
    window.__dravenlock_cookie = true;

    // Veel-gebruikte selectoren voor cookie-accept knoppen
    var selectors = [
        // Tekst-based (we zoeken knoppen met deze tekst)
        // Specifieke bekende cookie-banner systemen:
        '#onetrust-accept-btn-handler',
        '#cookieAcceptButton',
        '.cc-allow', '.cc-accept-all', '.cc-dismiss',
        '#cookie-accept', '#cookie-agree',
        '#CybotCookiebotDialogBodyButtonAccept',
        '.cookie-accept', '.cookies-accept',
        '[data-cookieconsent="accept"]',
        '[aria-label*="accept" i][aria-label*="cookie" i]',
    ];

    var textKeywords = [
        'accept all', 'accept', 'agree', 'i agree',
        'alles accepteren', 'akkoord', 'sta toe',
        'tout accepter', 'accepter',
    ];

    function tryClick() {
        // Eerst selectoren
        for (var i = 0; i < selectors.length; i++) {
            var el = document.querySelector(selectors[i]);
            if (el && !el.__dvl_clicked) {
                el.__dvl_clicked = true;
                try { el.click(); console.log('[Dravenlock] cookie geaccepteerd via', selectors[i]); return; } catch(e){}
            }
        }
        // Dan op tekst
        var buttons = document.querySelectorAll('button, a[role="button"]');
        for (var i = 0; i < buttons.length; i++) {
            var btn = buttons[i];
            if (btn.__dvl_clicked) continue;
            var text = (btn.textContent || '').toLowerCase().trim();
            if (text.length > 30) continue;
            for (var j = 0; j < textKeywords.length; j++) {
                if (text === textKeywords[j] || text === textKeywords[j] + ' all' || text === textKeywords[j] + ' alles') {
                    btn.__dvl_clicked = true;
                    try { btn.click(); console.log('[Dravenlock] cookie geaccepteerd via tekst:', text); return; } catch(e){}
                }
            }
        }
    }

    // Probeer direct én na DOM-mutaties (cookie-banners verschijnen vaak laat)
    tryClick();
    setTimeout(tryClick, 500);
    setTimeout(tryClick, 1500);
    setTimeout(tryClick, 3000);
})();
"""

# 3. Eenvoudige Dark Reader (CSS-filter inversie)
_DARK_READER_JS = r"""
(function() {
    if (window.__dravenlock_dark) return;
    window.__dravenlock_dark = true;
    // Eenvoudige donker-modus via CSS-filters. Niet zo geavanceerd als
    // de echte Dark Reader, maar wel licht en breed werkend.
    var s = document.createElement('style');
    s.textContent = `
        html {
            filter: invert(0.9) hue-rotate(180deg) !important;
            background: #181818 !important;
        }
        img, video, picture, canvas, [style*="background-image"] {
            filter: invert(1) hue-rotate(180deg) !important;
        }
        iframe { filter: invert(1) hue-rotate(180deg) !important; }
    `;
    (document.head || document.documentElement).appendChild(s);
})();
"""


# Cookie Banner Killer: verbergt cookie-banners volledig zonder iets
# te accepteren of weigeren. Anders dan _COOKIE_ACCEPT_JS dat op
# "Accepteren" klikt, gebruikt deze extensie CSS om de banners
# onzichtbaar te maken plus periodieke cleanup van toegevoegde DOM
# elementen. Voor mensen die liever niets accepteren maar ook geen
# zin hebben in de "Weigeren" zoektocht.
_COOKIE_KILLER_JS = r"""
(function() {
    'use strict';

    // Specifieke selectors voor bekende cookie-banner systemen.
    // Lijst gebaseerd op de open-source EasyList Cookie filterlijsten
    // en specifieke observaties op YouTube en Google.
    var SPECIFIC = [
        // === Generieke "cookie" en "consent" in id/class ===
        '[id*="cookie" i]', '[class*="cookie" i]',
        '[id*="consent" i]', '[class*="consent" i]',
        '[id*="gdpr" i]', '[class*="gdpr" i]',
        '[id*="cookiebar" i]', '[class*="cookiebar" i]',
        '[id*="cookiemelding" i]', '[class*="cookiemelding" i]',
        // === Bekende CMP-platformen ===
        '#onetrust-banner-sdk', '#onetrust-consent-sdk',
        '#CybotCookiebotDialog', '#CybotCookiebotDialogBodyUnderlay',
        '#cmpwrapper', '#cmpbox', '#cmpcontainer',
        '.qc-cmp2-container', '.qc-cmp-ui-container',
        '#didomi-host', '#didomi-notice',
        '.fc-consent-root', '.fc-dialog-container',
        '#truste-consent-track', '.truste_overlay',
        '[id^="sp_message_container"]',
        // === YouTube specifiek ===
        'ytd-consent-bump-v2-lightbox',
        'tp-yt-paper-dialog',
        'ytd-popup-container',
        // === Google specifiek ===
        '#cnsw', '#cnsh', '#lb',
        'c-wiz[jsrenderer*="consent"]',
    ];

    // Sleutelwoorden voor inhoudelijke detectie. Sommige banners
    // (zoals Google's nieuwere varianten) hebben geen herkenbare
    // id/class en moeten op tekst worden gevonden.
    var KEYWORDS = [
        'voordat je verdergaat', 'voordat je verder gaat',
        'before you continue', 'accept all', 'accept cookies',
        'we use cookies', 'we and our partners',
        'cookie policy', 'alle cookies', 'cookies accepteren',
        'wir verwenden cookies', 'cookies akzeptieren',
        'nous utilisons des cookies', 'aceptar cookies',
    ];

    function removeBanners() {
        // 1. Specifieke selectors: gewoon weghalen uit DOM
        try {
            SPECIFIC.forEach(function(sel) {
                document.querySelectorAll(sel).forEach(function(el) {
                    el.remove();
                });
            });
        } catch (e) {}

        // 2. Inhoudelijke detectie: zoek modal-achtige containers
        //    die een cookie-tekst bevatten, en verwijder die.
        try {
            var candidates = document.querySelectorAll(
                '[role="dialog"], [aria-modal="true"], ' +
                'dialog, ' +
                'div[class*="modal" i], div[class*="overlay" i], ' +
                'div[class*="dialog" i], div[class*="popup" i]'
            );
            candidates.forEach(function(el) {
                if (!el || !el.isConnected) return;
                // Skip te kleine elementen
                var rect = el.getBoundingClientRect();
                if (rect.width < 200 || rect.height < 100) return;

                var text = (el.innerText || '').toLowerCase().slice(0, 800);
                if (!text) return;

                for (var i = 0; i < KEYWORDS.length; i++) {
                    if (text.indexOf(KEYWORDS[i]) !== -1) {
                        el.remove();
                        break;
                    }
                }
            });
        } catch (e) {}

        // 3. Body-overlay overlay-divs die gefixeerd op het scherm
        //    plakken en de pagina overschaduwen — als ze cookie-
        //    teksten bevatten kunnen we ze ook weghalen.
        try {
            var overlays = document.querySelectorAll(
                'body > div, body > section, body > aside'
            );
            overlays.forEach(function(el) {
                if (!el || !el.isConnected) return;
                var style = window.getComputedStyle(el);
                if (style.position !== 'fixed' &&
                    style.position !== 'sticky') return;

                var rect = el.getBoundingClientRect();
                if (rect.width < 200 || rect.height < 100) return;

                var text = (el.innerText || '').toLowerCase().slice(0, 800);
                for (var i = 0; i < KEYWORDS.length; i++) {
                    if (text.indexOf(KEYWORDS[i]) !== -1) {
                        el.remove();
                        break;
                    }
                }
            });
        } catch (e) {}

        // 4. Reset body-scroll dat banners vaak blokkeren
        try {
            document.documentElement.style.overflow = 'auto';
            document.body.style.overflow = 'auto';
            document.body.style.position = 'static';
            ['no-scroll', 'noscroll', 'overflow-hidden',
             'modal-open', 'cookie-open', 'has-modal']
                .forEach(function(cls) {
                    document.documentElement.classList.remove(cls);
                    document.body.classList.remove(cls);
                });
        } catch (e) {}
    }

    // Eerste run zo snel mogelijk
    removeBanners();

    // Herhaal periodiek omdat sommige sites banners later inladen
    // of opnieuw proberen te tonen nadat we ze hebben verwijderd
    setTimeout(removeBanners, 200);
    setTimeout(removeBanners, 600);
    setTimeout(removeBanners, 1500);
    setTimeout(removeBanners, 3000);
    setTimeout(removeBanners, 6000);

    // MutationObserver voor banners die later in de DOM verschijnen
    // (lazy-loaded scripts, animaties, etc.)
    function startObserver() {
        if (!document.body) return;
        var observer = new MutationObserver(function(mutations) {
            for (var i = 0; i < mutations.length; i++) {
                if (mutations[i].addedNodes &&
                    mutations[i].addedNodes.length > 0) {
                    removeBanners();
                    return;
                }
            }
        });
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
    }

    if (document.body) {
        startObserver();
    } else {
        document.addEventListener('DOMContentLoaded', startObserver);
    }
})();
"""


