# JS dat alleen extract doet (geen DOM-vervanging) — geeft titel +
# content terug zodat Python er een aparte data-URL van kan maken
EXTRACT_ONLY_JS = r"""
(function() {
    'use strict';
    try {
        function clean(article) {
            var trash = article.querySelectorAll(
                'script, style, iframe, noscript, nav, aside, header, footer, ' +
                'form, button, .advertisement, .ad, .ads, .comments, .comment, ' +
                '.sidebar, .share, .social, .related, .related-posts, ' +
                '.newsletter, .subscribe, .popup, ' +
                '.menu, .navigation, .navbar, .breadcrumbs, ' +
                '[class*="advertisement" i], [class*="banner-ad" i], ' +
                '[class*="cookie" i], [class*="paywall" i], ' +
                '[role="navigation"], [role="banner"], [role="contentinfo"], ' +
                '[role="complementary"]'
            );
            for (var i = 0; i < trash.length; i++) {
                try { trash[i].remove(); } catch(e) {}
            }
        }

        function getCandidates() {
            var out = [];
            var articles = document.querySelectorAll('article');
            for (var i = 0; i < articles.length; i++) {
                out.push({el: articles[i], source: 'article'});
            }
            var main = document.querySelector('main');
            if (main) out.push({el: main, source: 'main'});
            var sel = [
                '.post-content', '.entry-content', '.article-content',
                '.article-body', '.post-body', '.story-body',
                '[itemprop="articleBody"]', '.markdown-body',
            ];
            for (var i = 0; i < sel.length; i++) {
                var el = document.querySelector(sel[i]);
                if (el) out.push({el: el, source: 'class:' + sel[i]});
            }
            var divs = document.querySelectorAll('div, section');
            var bestDiv = null, bestScore = 0;
            for (var i = 0; i < divs.length; i++) {
                var el = divs[i];
                var ps = el.querySelectorAll(':scope > p, :scope > div > p');
                if (ps.length < 3) continue;
                var textLen = 0;
                for (var j = 0; j < ps.length; j++) textLen += ps[j].textContent.length;
                if (textLen > bestScore) { bestDiv = el; bestScore = textLen; }
            }
            if (bestDiv && bestScore > 500) {
                out.push({el: bestDiv, source: 'heuristic-p'});
            }
            return out;
        }

        function findArticle() {
            var candidates = getCandidates();
            if (candidates.length === 0) return null;
            var best = null, bestSize = 0;
            for (var i = 0; i < candidates.length; i++) {
                var clone = candidates[i].el.cloneNode(true);
                clean(clone);
                var effectiveText = clone.textContent.trim();
                var pCount = clone.querySelectorAll('p').length;
                var score = effectiveText.length * (1 + pCount * 0.1);
                if (score > bestSize) {
                    best = {
                        el: clone,  // gebruik clean kopie direct
                        source: candidates[i].source,
                        textLength: effectiveText.length,
                    };
                    bestSize = score;
                }
            }
            if (best && best.textLength >= 500) return best;
            return null;
        }

        function findTitle() {
            var h1 = document.querySelector('h1');
            if (h1 && h1.textContent.trim()) return h1.textContent.trim();
            return document.title || '';
        }

        function findByline() {
            var sel = [
                '[rel="author"]', '.author', '.byline', '.post-author',
                '[itemprop="author"]', '.article-author',
            ];
            for (var i = 0; i < sel.length; i++) {
                var el = document.querySelector(sel[i]);
                if (el && el.textContent.trim()) {
                    return el.textContent.trim().substring(0, 100);
                }
            }
            return '';
        }

        var found = findArticle();
        if (!found) {
            return JSON.stringify({
                ok: false,
                reason: 'no_substantial_article',
                hint: 'Geen artikel-blok met genoeg tekst gevonden (min. 500 tekens).'
            });
        }

        var article = found.el;

        // Maak relatieve URLs absoluut
        var imgs = article.querySelectorAll('img');
        for (var i = 0; i < imgs.length; i++) {
            try {
                var src = imgs[i].getAttribute('src');
                if (src) imgs[i].setAttribute('src', new URL(src, document.baseURI).href);
            } catch(e) {}
        }
        var links = article.querySelectorAll('a');
        for (var i = 0; i < links.length; i++) {
            try {
                var href = links[i].getAttribute('href');
                if (href) links[i].setAttribute('href', new URL(href, document.baseURI).href);
            } catch(e) {}
        }

        return JSON.stringify({
            ok: true,
            title: findTitle(),
            byline: findByline(),
            content: article.innerHTML,
            text_length: found.textLength,
            source: found.source,
            origin: window.location.href,
        });
    } catch (e) {
        return JSON.stringify({ok: false, reason: 'exception', error: String(e)});
    }
})();
"""


def build_standalone_html(title: str, byline: str, content: str,
                            origin: str, source: str = "?",
                            text_length: int = 0) -> str:
    """
    Bouw een standalone HTML-pagina voor reader (voor "nieuwe tab" modus).

    De pagina heeft een licht/donker theme-toggle die werkt met
    localStorage zodat de voorkeur tussen artikelen behouden blijft.
    """
    # Escape de strings die in attribute-context komen
    def esc(s: str) -> str:
        return (str(s)
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace('"', "&quot;")
                .replace("'", "&#039;"))

    title_safe = esc(title)
    byline_html = (
        f'<div class="byline">{esc(byline)}</div>' if byline else ""
    )
    origin_safe = esc(origin)

    # JS voor theme-toggle (gebruikt localStorage, dat werkt in
    # data:-URLs WEL want het is opaque origin)
    theme_js = r"""
function setTheme(t) {
    document.documentElement.dataset.theme = t;
    try { localStorage.setItem('dvl-reader-theme', t); } catch(e) {}
}
function toggleTheme() {
    var t = document.documentElement.dataset.theme || 'dark';
    setTheme(t === 'dark' ? 'light' : 'dark');
}
(function() {
    var saved = 'dark';
    try { saved = localStorage.getItem('dvl-reader-theme') || 'dark'; } catch(e) {}
    setTheme(saved);
})();
"""

    return f"""<!DOCTYPE html>
<html lang="nl" data-theme="dark">
<head>
<meta charset="utf-8">
<title>📖 {title_safe}</title>
<style>
:root[data-theme="dark"] {{
    --bg: #1a1a1a; --text: #eeeeee; --dim: #888888; --code-bg: #000;
}}
:root[data-theme="light"] {{
    --bg: #f4ede0; --text: #222222; --dim: #666666; --code-bg: #eee;
}}
html, body {{
    background: var(--bg); color: var(--text);
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 18px; line-height: 1.7;
    margin: 0; padding: 0;
}}
.wrap {{ max-width: 720px; margin: 0 auto; padding: 40px 24px 80px 24px; }}
.toolbar {{
    position: sticky; top: 0; background: var(--bg);
    border-bottom: 1px solid color-mix(in srgb, var(--dim) 30%, transparent);
    padding: 12px 24px; margin: -40px -24px 32px -24px;
    display: flex; gap: 12px; align-items: center; z-index: 1000;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 14px;
}}
.toolbar button {{
    background: var(--bg); color: var(--text);
    border: 1px solid var(--dim); border-radius: 4px;
    padding: 6px 12px; font-size: 14px; cursor: pointer;
    font-family: inherit;
}}
.toolbar button:hover {{ border-color: #00aaff; color: #00aaff; }}
.toolbar .info {{ color: var(--dim); font-size: 12px; }}
.toolbar a {{ color: var(--dim); text-decoration: none; }}
.toolbar a:hover {{ color: #00aaff; }}
h1.title {{
    margin: 16px 0 8px 0; font-size: 32px; line-height: 1.3;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}}
.byline {{
    color: var(--dim); font-size: 14px; font-style: italic;
    margin: 0 0 32px 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}}
.content p {{ margin: 0 0 1em 0; }}
.content h1, .content h2, .content h3, .content h4 {{
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    margin: 1.5em 0 0.5em 0; line-height: 1.3;
}}
.content a {{ color: #00aaff; text-decoration: underline; }}
.content img {{ max-width: 100%; height: auto; display: block; margin: 1em auto; border-radius: 4px; }}
.content blockquote {{
    border-left: 3px solid #00aaff; padding: 8px 16px; margin: 1em 0;
    color: var(--dim); font-style: italic;
}}
.content pre, .content code {{
    background: var(--code-bg); padding: 2px 6px; border-radius: 3px;
    font-family: 'Consolas', monospace; font-size: 0.9em;
}}
.content pre {{ padding: 12px; overflow-x: auto; }}
.content ul, .content ol {{ padding-left: 1.5em; }}
.meta {{
    color: var(--dim); font-size: 12px; margin-top: 32px;
    padding-top: 16px; border-top: 1px solid color-mix(in srgb, var(--dim) 30%, transparent);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}}
.meta a {{ color: #00aaff; }}
</style>
</head>
<body>
<div class="wrap">
    <div class="toolbar">
        <button onclick="toggleTheme()">🌓 Thema</button>
        <span class="info">📖 Reader · {text_length:,} tekens · bron: {esc(source)}</span>
    </div>
    <h1 class="title">{title_safe}</h1>
    {byline_html}
    <div class="content">{content}</div>
    <div class="meta">
        Originele bron: <a href="{origin_safe}">{origin_safe}</a>
    </div>
</div>
<script>{theme_js}</script>
</body>
</html>"""


def build_data_url(html: str) -> str:
    """Maak een data:text/html;base64,... URL die kan worden geopend."""
    encoded = base64.b64encode(html.encode("utf-8")).decode("ascii")
    return f"data:text/html;base64,{encoded}"


# ============================================================
# DARK MODE — per-tab donker met host-geheugen
# ============================================================

"""
core/dark_mode.py - Per-tab dark mode toggle met opslag per host.

Werking:
  - Toggle injecteert CSS-filter via JavaScript
  - State wordt onthouden per host in dark_sites.json
  - Bij paginalaad: als deze host eerder donker was → auto-toggle

VERSCHIL MET EXTENSIE
=====================
De Dark Reader extensie (in v0.5) is GLOBAAL — aan = altijd aan voor
elke pagina. Deze per-tab versie:
  - Werkt op één tab tegelijk via een knop
  - Onthoudt per origin (host) of de gebruiker hem aan had
  - Bij navigatie naar zelfde host: weer aan
  - Bij navigatie naar andere host: respecteert die zijn voorkeur
"""
import json
import threading
from pathlib import Path
from typing import Optional, Set
from urllib.parse import urlparse

# (intra-import gestript: from core.paths import data_dir)


def get_dark_sites_file() -> Path:
    return data_dir() / "dark_sites.json"


# JavaScript dat de donkere modus aanzet (idempotent)
ENABLE_JS = r"""
(function() {
    if (window.__dravenlock_dark_active) {
        return JSON.stringify({already_active: true});
    }
    try {
        var s = document.createElement('style');
        s.id = 'dvl-dark-mode-style';
        s.textContent = `
            html {
                filter: invert(0.92) hue-rotate(180deg) !important;
                background: #181818 !important;
            }
            img, video, picture, canvas, svg, iframe,
            [style*="background-image"] {
                filter: invert(1) hue-rotate(180deg) !important;
            }
        `;
        (document.head || document.documentElement).appendChild(s);
        window.__dravenlock_dark_active = true;
        return JSON.stringify({ok: true});
    } catch (e) {
        return JSON.stringify({ok: false, error: String(e)});
    }
})();
"""


# JavaScript dat de donkere modus uitzet
DISABLE_JS = r"""
(function() {
    try {
        var s = document.getElementById('dvl-dark-mode-style');
        if (s) s.remove();
        window.__dravenlock_dark_active = false;
        return JSON.stringify({ok: true});
    } catch (e) {
        return JSON.stringify({ok: false, error: String(e)});
    }
})();
"""


# Check of dark mode actief is in deze tab
CHECK_JS = r"""
(function() {
    return JSON.stringify({active: !!window.__dravenlock_dark_active});
})();
"""


def parse_result(raw) -> dict:
    """Parseer JS-resultaat (string of dict)."""
    if raw is None:
        return {"ok": False, "reason": "callback_null"}
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str):
        try:
            return json.loads(raw)
        except Exception:
            return {"ok": False, "reason": "parse_error"}
    return {"ok": False, "reason": "unknown_type"}


def get_host(url: str) -> str:
    """Haal de host uit een URL. Returnt lege string bij fout."""
    if not url:
        return ""
    try:
        host = urlparse(url).hostname or ""
        return host.lower()
    except Exception:
        return ""


# ----------------------------------------------------------------------
# DarkModeManager — onthoudt welke hosts donker moeten zijn
# ----------------------------------------------------------------------
class DarkModeManager:
    """
    Beheer van per-host dark mode voorkeuren.

    Opslag: <data-map>/dark_sites.json
    Format: {"version": 1, "hosts": ["example.com", "wikipedia.org"]}
    """

    def __init__(self):
        self._file = get_dark_sites_file()
        self._hosts: Set[str] = set()
        self._lock = threading.Lock()
        self._load()

    def is_dark(self, url: str) -> bool:
        """Check of deze URL (op basis van host) donker moet zijn."""
        host = get_host(url)
        if not host:
            return False
        with self._lock:
            # Match: exact OF subdomein-van-saved
            # bv. "nl.wikipedia.org" matcht saved "wikipedia.org"
            if host in self._hosts:
                return True
            for saved in self._hosts:
                if host.endswith("." + saved):
                    return True
        return False

    def set_dark(self, url: str, dark: bool):
        """Markeer of deze URL's host donker moet zijn."""
        host = get_host(url)
        if not host:
            return
        with self._lock:
            if dark:
                self._hosts.add(host)
            else:
                # Verwijder zowel exacte host als parent
                self._hosts.discard(host)
                # Als de saved entry een parent is van deze host:
                # verwijder ook (zodat subdomein opt-out werkt)
                parents_to_remove = [
                    s for s in self._hosts if host.endswith("." + s)
                ]
                for p in parents_to_remove:
                    self._hosts.discard(p)
        self._save()

    def all_hosts(self) -> list:
        """Alle opgeslagen hosts (voor settings-overzicht later)."""
        with self._lock:
            return sorted(self._hosts)

    def clear_all(self):
        """Wis alle voorkeuren."""
        with self._lock:
            self._hosts = set()
        self._save()

    def _load(self):
        if not self._file.exists():
            return
        try:
            with open(self._file, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                self._hosts = set(data.get("hosts", []))
            elif isinstance(data, list):
                self._hosts = set(data)
            print(f"[dark_mode] {len(self._hosts)} hosts geladen")
        except Exception as e:
            print(f"[dark_mode] laden faalde: {e}")

    def _save(self):
        try:
            with self._lock:
                data = {
                    "version": 1,
                    "hosts": sorted(self._hosts),
                }
            tmp = self._file.with_suffix(self._file.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            if self._file.exists():
                self._file.unlink()
            tmp.rename(self._file)
        except Exception as e:
            print(f"[dark_mode] opslaan faalde: {e}")


# Singleton met unieke prefix
_dark_mode_manager: Optional[DarkModeManager] = None


def get_dark_mode_manager() -> DarkModeManager:
    global _dark_mode_manager
    if _dark_mode_manager is None:
        _dark_mode_manager = DarkModeManager()
    return _dark_mode_manager


# ============================================================
# MAGNIFIER — pagina-zoom, tekst-zoom, loep
# ============================================================

"""
core/magnifier.py - Drie magnifier-varianten:

  A. Pagina-zoom    — Qt's setZoomFactor (alles wordt groter)
  B. Tekst-zoom     — JS injecteert CSS dat font-size verhoogt
  C. Loep           — JS toont een vergrootglas-cirkel die de muis volgt

Alle drie via dezelfde knop in main_window — dropdown met de keuzes.

OPSLAG
======
Per-host zoom-niveaus worden onthouden in <data-map>/zoom_levels.json,
zodat een site die je op 1.25× zet bij volgend bezoek ook op 1.25× komt.
"""
import json
import threading
from pathlib import Path
from typing import Optional, Dict
from urllib.parse import urlparse

# (intra-import gestript: from core.paths import data_dir)


def get_zoom_file() -> Path:
    return data_dir() / "zoom_levels.json"


def get_host(url: str) -> str:
    if not url:
        return ""
    try:
        return (urlparse(url).hostname or "").lower()
    except Exception:
        return ""


# ----------------------------------------------------------------------
# A. Pagina-zoom — onthoudt per host
# ----------------------------------------------------------------------
ZOOM_MIN = 0.5
ZOOM_MAX = 3.0
ZOOM_STEP = 0.1
ZOOM_DEFAULT = 1.0


class ZoomManager:
    """Per-host zoom-niveau opslag."""

    def __init__(self):
        self._file = get_zoom_file()
        self._zoom: Dict[str, float] = {}
        self._lock = threading.Lock()
        self._load()

    def get(self, url: str) -> float:
        """Krijg het opgeslagen zoom-niveau voor deze URL's host."""
        host = get_host(url)
        if not host:
            return ZOOM_DEFAULT
        with self._lock:
            return self._zoom.get(host, ZOOM_DEFAULT)

    def set(self, url: str, factor: float):
        """Sla een zoom-niveau op voor deze URL's host."""
        host = get_host(url)
        if not host:
            return
        # Begrens
        factor = max(ZOOM_MIN, min(ZOOM_MAX, factor))
        # 1.0 = default → niet opslaan (kleinere file, schoner)
        with self._lock:
            if abs(factor - ZOOM_DEFAULT) < 0.01:
                self._zoom.pop(host, None)
            else:
                self._zoom[host] = round(factor, 2)
        self._save()

    def clear(self, url: str):
        """Wis zoom voor deze host (terug naar default)."""
        self.set(url, ZOOM_DEFAULT)

    def all_hosts(self) -> dict:
        with self._lock:
            return dict(self._zoom)

    def _load(self):
        if not self._file.exists():
            return
        try:
            with open(self._file, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                # Filter alleen valide entries
                self._zoom = {
                    str(k): float(v)
                    for k, v in data.get("hosts", {}).items()
                    if isinstance(v, (int, float))
                    and ZOOM_MIN <= float(v) <= ZOOM_MAX
                }
            print(f"[zoom] {len(self._zoom)} hosts geladen")
        except Exception as e:
            print(f"[zoom] laden faalde: {e}")

    def _save(self):
        try:
            with self._lock:
                data = {"version": 1, "hosts": dict(self._zoom)}
            tmp = self._file.with_suffix(self._file.suffix + ".tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            if self._file.exists():
                self._file.unlink()
            tmp.rename(self._file)
        except Exception as e:
            print(f"[zoom] opslaan faalde: {e}")


_zoom_manager: Optional[ZoomManager] = None


def get_zoom_manager() -> ZoomManager:
    global _zoom_manager
    if _zoom_manager is None:
        _zoom_manager = ZoomManager()
    return _zoom_manager


