TEXT_ZOOM_ENABLE_JS = r"""
(function() {
    'use strict';
    try {
        var STEP = arguments_step_placeholder;  // wordt vervangen door Python
        var existing = document.getElementById('dvl-text-zoom-style');
        var currentSize = parseFloat(
            (existing && existing.dataset.size) || '100'
        );
        var newSize = Math.max(50, Math.min(300, currentSize + STEP));

        if (!existing) {
            existing = document.createElement('style');
            existing.id = 'dvl-text-zoom-style';
            (document.head || document.documentElement).appendChild(existing);
        }
        existing.dataset.size = String(newSize);
        existing.textContent = `
            html { font-size: ${newSize}% !important; }
            body { font-size: ${newSize}% !important; }
        `;
        return JSON.stringify({ok: true, size: newSize});
    } catch (e) {
        return JSON.stringify({ok: false, error: String(e)});
    }
})();
"""

TEXT_ZOOM_RESET_JS = r"""
(function() {
    try {
        var s = document.getElementById('dvl-text-zoom-style');
        if (s) s.remove();
        return JSON.stringify({ok: true});
    } catch (e) {
        return JSON.stringify({ok: false, error: String(e)});
    }
})();
"""


def build_text_zoom_js(step: int) -> str:
    """
    Bouw het tekst-zoom JS met een specifieke step (in percentage-punten).
    Bijv. +20, -20, of een absolute waarde.
    """
    return TEXT_ZOOM_ENABLE_JS.replace(
        "arguments_step_placeholder", str(int(step))
    )


