"""
ui/dialogs/favorite_edit_dialog.py - Dialoog voor het bewerken van
een favoriet (titel, URL, map).
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, make_primary)
# (intra-import gestript: from core.favorites import get_favorites_manager)


class EditFavoriteDialog(QDialog):
    """
    Dialoog om titel, URL, en map van een favoriet te bewerken.

    Gebruik:
        dlg = EditFavoriteDialog(fav={...}, current_folder_id="f_..." or None)
        if dlg.exec() == QDialog.Accepted:
            new_title = dlg.title()
            new_url = dlg.url()
            new_folder = dlg.folder_id()  # kan None zijn
    """

    def __init__(self, fav: dict, current_folder_id: str = None, parent=None):
        super().__init__(parent)
        self._fav = dict(fav)  # kopie, zodat we niet inplace muteren
        self._current_folder_id = current_folder_id
        self._new_folder_id = current_folder_id
        self.setWindowTitle("Favoriet bewerken")
        self.setMinimumSize(560, 320)
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(14)

        title = QLabel("⭐ Favoriet bewerken")
        title.setFont(title_font())
        layout.addWidget(title)

        form = QFormLayout()
        form.setSpacing(10)

        self.txt_title = QLineEdit(self._fav.get("title", ""))
        self.txt_title.setFont(base_font(12))
        self.txt_title.setMinimumHeight(36)
        form.addRow(self._lbl("Titel:"), self.txt_title)

        self.txt_url = QLineEdit(self._fav.get("url", ""))
        self.txt_url.setFont(base_font(12))
        self.txt_url.setMinimumHeight(36)
        form.addRow(self._lbl("URL:"), self.txt_url)

        self.cmb_folder = QComboBox()
        self.cmb_folder.setFont(base_font(12))
        self.cmb_folder.setMinimumHeight(36)
        self.cmb_folder.addItem("(geen map)", None)
        for folder in get_favorites_manager().all_folders():
            self.cmb_folder.addItem(f"📁  {folder['name']}", folder["id"])
        # Selecteer huidige map
        for i in range(self.cmb_folder.count()):
            if self.cmb_folder.itemData(i) == self._current_folder_id:
                self.cmb_folder.setCurrentIndex(i)
                break
        form.addRow(self._lbl("Map:"), self.cmb_folder)

        layout.addLayout(form)
        layout.addStretch()

        btn_row = QHBoxLayout()
        btn_row.addStretch()

        self.btn_save = QPushButton("✓ Opslaan")
        self.btn_save.setFont(QFont(base_font().family(),
                                     base_font().pointSize(), QFont.Bold))
        self.btn_save.setMinimumHeight(44)
        self.btn_save.setMinimumWidth(140)
        make_primary(self.btn_save)
        self.btn_save.clicked.connect(self._on_save)
        btn_row.addWidget(self.btn_save)

        btn_cancel = QPushButton("✕ Annuleren")
        btn_cancel.setFont(base_font())
        btn_cancel.setMinimumHeight(44)
        btn_cancel.setMinimumWidth(140)
        btn_cancel.clicked.connect(self.reject)
        btn_row.addWidget(btn_cancel)

        layout.addLayout(btn_row)

    def _lbl(self, t: str) -> QLabel:
        lbl = QLabel(t)
        lbl.setFont(base_font())
        return lbl

    def _on_save(self):
        title = self.txt_title.text().strip()
        url = self.txt_url.text().strip()
        if not title or not url:
            QMessageBox.warning(self, "Velden ontbreken",
                                "Titel en URL zijn beide verplicht.")
            return
        self._fav["title"] = title
        self._fav["url"] = url
        self._new_folder_id = self.cmb_folder.currentData()
        self.accept()

    def title(self) -> str:
        return self._fav["title"]

    def url(self) -> str:
        return self._fav["url"]

    def folder_id(self):
        return self._new_folder_id


