"""
ui/dialogs/extension_edit_dialog.py - Dialoog voor het bewerken
van een gebruikers-extensie (naam, URL-patroon, JavaScript).
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, mono_font, make_primary)


class ExtensionEditDialog(QDialog):
    """
    Dialoog om een gebruikers-extensie te bewerken (of nieuwe te maken).

    Gebruik:
        dlg = ExtensionEditDialog(ext=None, parent=self)  # nieuwe
        dlg = ExtensionEditDialog(ext=existing_ext, parent=self)

        if dlg.exec() == QDialog.Accepted:
            values = dlg.values()  # dict
    """

    def __init__(self, ext=None, parent=None):
        super().__init__(parent)
        self.is_edit = ext is not None
        self._ext = ext
        self.setWindowTitle(
            "Extensie bewerken" if self.is_edit else "Nieuwe extensie"
        )
        self.setMinimumSize(720, 600)
        self._build_ui()
        if self._ext:
            self._fill_from_ext()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(14)

        icon = "✏️" if self.is_edit else "🧩"
        title = QLabel(
            f"{icon} {'Extensie bewerken' if self.is_edit else 'Nieuwe extensie'}"
        )
        title.setFont(title_font())
        layout.addWidget(title)

        # Form: naam, URL-patroon, beschrijving
        form = QFormLayout()
        form.setSpacing(10)

        self.txt_name = QLineEdit()
        self.txt_name.setFont(base_font(12))
        self.txt_name.setMinimumHeight(36)
        self.txt_name.setPlaceholderText("Bijv. 'Mijn aangepaste script'")
        form.addRow(self._lbl("Naam:"), self.txt_name)

        self.txt_url_pattern = QLineEdit()
        self.txt_url_pattern.setFont(mono_font(12))
        self.txt_url_pattern.setMinimumHeight(36)
        self.txt_url_pattern.setText("*")
        self.txt_url_pattern.setPlaceholderText("* (alles) of *example.com*")
        form.addRow(self._lbl("URL-patroon:"), self.txt_url_pattern)

        self.txt_description = QLineEdit()
        self.txt_description.setFont(base_font(12))
        self.txt_description.setMinimumHeight(36)
        self.txt_description.setPlaceholderText("Korte uitleg wat het script doet")
        form.addRow(self._lbl("Beschrijving:"), self.txt_description)

        layout.addLayout(form)

        # JavaScript editor
        layout.addWidget(self._lbl("JavaScript-code:"))
        self.txt_js = QPlainTextEdit()
        self.txt_js.setFont(mono_font(11))
        self.txt_js.setPlaceholderText(
            "// Hier komt je JavaScript code.\n"
            "// Tip: gebruik een IIFE om global namespace te beschermen:\n"
            "(function() {\n"
            "    'use strict';\n"
            "    console.log('Mijn script werkt!');\n"
            "})();"
        )
        self.txt_js.setStyleSheet(
            f"QPlainTextEdit {{ background:{COLOR.bg_deep}; "
            f"color:{COLOR.text}; border:1px solid {COLOR.border}; "
            f"border-radius:4px; padding:8px; "
            f"selection-background-color:{COLOR.accent}; }}"
        )
        layout.addWidget(self.txt_js, 1)

        # Info-blokje
        info = QLabel(
            "⚠ Wees voorzichtig: scripts kunnen toegang hebben tot data op "
            "de pagina. Plak alleen JavaScript van bronnen die je vertrouwt."
        )
        info.setFont(base_font())
        info.setWordWrap(True)
        info.setStyleSheet(
            f"color:{COLOR.warning}; padding:8px; "
            f"background:{COLOR.bg_2}; border-radius:4px; "
            f"border-left:3px solid {COLOR.warning};"
        )
        layout.addWidget(info)

        # Knoppen
        btn_row = QHBoxLayout()
        btn_row.addStretch()

        self.btn_save = QPushButton("✓ Opslaan")
        self.btn_save.setFont(QFont(base_font().family(),
                                     base_font().pointSize(), QFont.Bold))
        self.btn_save.setMinimumHeight(44)
        self.btn_save.setMinimumWidth(140)
        make_primary(self.btn_save)
        self.btn_save.clicked.connect(self._on_save)
        btn_row.addWidget(self.btn_save)

        btn_cancel = QPushButton("✕ Annuleren")
        btn_cancel.setFont(base_font())
        btn_cancel.setMinimumHeight(44)
        btn_cancel.setMinimumWidth(140)
        btn_cancel.clicked.connect(self.reject)
        btn_row.addWidget(btn_cancel)

        layout.addLayout(btn_row)

    def _lbl(self, t):
        lbl = QLabel(t)
        lbl.setFont(base_font())
        return lbl

    def _fill_from_ext(self):
        self.txt_name.setText(self._ext.name)
        self.txt_url_pattern.setText(self._ext.url_pattern)
        self.txt_description.setText(self._ext.description)
        self.txt_js.setPlainText(self._ext.js)

    def _on_save(self):
        if not self.txt_name.text().strip():
            QMessageBox.warning(self, "Naam ontbreekt",
                                "Geef de extensie een naam.")
            return
        if not self.txt_js.toPlainText().strip():
            QMessageBox.warning(self, "Geen code",
                                "Het JavaScript-veld is leeg.")
            return
        self.accept()

    def values(self) -> dict:
        return {
            "name": self.txt_name.text().strip(),
            "url_pattern": self.txt_url_pattern.text().strip() or "*",
            "description": self.txt_description.text().strip(),
            "js": self.txt_js.toPlainText(),
        }


