"""
ui/dialogs/download_dialog.py - Dialoog voor format-keuze bij downloaden.

Toont de URL bovenaan + radiobuttons per beschikbaar format,
gegroepeerd in 'Video' en 'Audio'. Beschrijving onder elke optie.
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, mono_font, make_primary)
# (intra-import gestript: from core.downloader import get_format_choices)


class DownloadFormatDialog(QDialog):
    """
    Dialoog: kies format om te downloaden.

    Gebruik:
        dlg = DownloadFormatDialog(url, parent=self)
        if dlg.exec() == QDialog.Accepted:
            format_id = dlg.format_id()
    """

    def __init__(self, url: str, parent=None):
        super().__init__(parent)
        self._url = url
        self._selected_format_id = None
        self._button_group = QButtonGroup(self)
        self.setWindowTitle("Downloaden")
        self.setMinimumSize(640, 560)
        self._build_ui()

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(12)

        title = QLabel("⬇️ Video / audio downloaden")
        title.setFont(title_font())
        layout.addWidget(title)

        # URL tonen
        url_box = QLabel(self._url)
        url_box.setFont(mono_font(10))
        url_box.setWordWrap(True)
        url_box.setStyleSheet(
            f"QLabel {{ background:{COLOR.bg_deep}; "
            f"color:{COLOR.accent}; padding:10px; "
            f"border:1px solid {COLOR.border}; border-radius:4px; }}"
        )
        url_box.setMaximumHeight(60)
        layout.addWidget(url_box)

        # Sectie: Video
        layout.addWidget(self._section_header("🎬 Video"))
        layout.addWidget(self._build_format_group(audio=False))

        # Sectie: Audio
        layout.addWidget(self._section_header("🎵 Audio"))
        layout.addWidget(self._build_format_group(audio=True))

        layout.addStretch()

        # Knoppen
        btn_row = QHBoxLayout()
        btn_row.addStretch()

        self.btn_download = QPushButton("⬇️ Downloaden")
        self.btn_download.setFont(QFont(base_font().family(),
                                         base_font().pointSize(), QFont.Bold))
        self.btn_download.setMinimumHeight(44)
        self.btn_download.setMinimumWidth(160)
        make_primary(self.btn_download)
        self.btn_download.clicked.connect(self._on_download)
        btn_row.addWidget(self.btn_download)

        btn_cancel = QPushButton("✕ Annuleren")
        btn_cancel.setFont(base_font())
        btn_cancel.setMinimumHeight(44)
        btn_cancel.setMinimumWidth(140)
        btn_cancel.clicked.connect(self.reject)
        btn_row.addWidget(btn_cancel)

        layout.addLayout(btn_row)

    def _section_header(self, text: str) -> QLabel:
        lbl = QLabel(text)
        lbl.setFont(QFont(base_font().family(), 12, QFont.Bold))
        lbl.setStyleSheet(f"color:{COLOR.accent}; padding-top:6px;")
        return lbl

    def _build_format_group(self, audio: bool) -> QWidget:
        """Bouw een box met radio-buttons voor video of audio formaten."""
        container = QFrame()
        container.setStyleSheet(
            f"QFrame {{ background:{COLOR.bg_1}; "
            f"border:1px solid {COLOR.border}; border-radius:6px; "
            f"padding:6px; }}"
        )
        v = QVBoxLayout(container)
        v.setSpacing(6)
        v.setContentsMargins(10, 8, 10, 8)

        for fid, label, desc, is_audio in get_format_choices():
            if is_audio != audio:
                continue
            radio = QRadioButton(label)
            radio.setFont(QFont(base_font().family(),
                                base_font().pointSize() + 1, QFont.Bold))
            radio.setProperty("format_id", fid)
            # Extra grote indicator + duidelijke styling — overschrijft global
            # waar nodig om bij donker thema goed zichtbaar te zijn
            radio.setStyleSheet(
                f"QRadioButton {{ padding: 6px; color: {COLOR.text}; }}"
                f"QRadioButton::indicator {{ width: 22px; height: 22px; }}"
                f"QRadioButton:checked {{ color: {COLOR.accent}; }}"
            )
            self._button_group.addButton(radio)
            v.addWidget(radio)

            desc_lbl = QLabel(f"        {desc}")
            desc_lbl.setFont(base_font())
            desc_lbl.setStyleSheet(
                f"color:{COLOR.text_dim}; padding:2px 4px 8px 20px;"
            )
            desc_lbl.setWordWrap(True)
            v.addWidget(desc_lbl)

        # Eerste video-format is standaard geselecteerd
        if not audio:
            for btn in self._button_group.buttons():
                if btn.property("format_id") == "mp4_best":
                    btn.setChecked(True)
                    break

        return container

    def _on_download(self):
        chosen = self._button_group.checkedButton()
        if not chosen:
            return
        self._selected_format_id = chosen.property("format_id")
        self.accept()

    def format_id(self) -> str:
        return self._selected_format_id

    def url(self) -> str:
        return self._url


# ============================================================
# WEB TAB — QWebEngineView wrapper
# ============================================================

"""
ui/web_tab.py - Eén tabblad met een QWebEngineView.

Inclusief:
  - CustomWebPage subclass voor:
      * createWindow (target="_blank" links → nieuwe tab)
      * javaScriptConsoleMessage (log naar dravenlock.log)
  - Helper-signals voor de hoofdwindow (titel-wijziging, etc)
  - Rechtsklik-context-menu met "Downloaden..." optie
  - Auto-injectie van enabled extensies bij paginalaad
"""







class FindBar(QWidget):
    """
    Zoek-balk voor "Zoeken op pagina". Verschijnt boven de webview
    wanneer de gebruiker Ctrl+F drukt of via het rechtsklik-menu
    de actie kiest. Bevat een tekstveld, vorige/volgende knoppen,
    een match-teller en een sluit-knop.

    De feitelijke zoekfunctie loopt via QWebEnginePage.findText()
    die zelf alle highlighting en scrollen-naar-resultaat regelt.
    """

    closed = Signal()  # signal voor wanneer de balk wordt gesloten

    def __init__(self, web_view, parent=None):
        super().__init__(parent)
        self._view = web_view
        self._match_count = 0
        self._current_match = 0

        # Achtergrond en rand zodat de balk visueel duidelijk
        # boven de webpagina hangt
        self.setStyleSheet("""
            FindBar {
                background: #1a1a1a;
                border-bottom: 1px solid #333333;
            }
            QLineEdit {
                background: #0d0d0d;
                color: #ffffff;
                border: 2px solid #333333;
                border-radius: 4px;
                padding: 4px 8px;
                font-size: 14px;
            }
            QLineEdit:focus {
                border-color: #00aaff;
            }
            QPushButton {
                background: #2a2a2a;
                color: #eeeeee;
                border: 1px solid #444444;
                border-radius: 4px;
                font-size: 14px;
                font-weight: bold;
            }
            QPushButton:hover {
                background: #383838;
                border-color: #00aaff;
            }
            QPushButton:pressed {
                background: #1a1a1a;
            }
            QLabel {
                color: #aaaaaa;
                font-size: 13px;
            }
        """)

        # (intra-import gestript: from core.lang import _)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(8, 6, 8, 6)
        layout.setSpacing(6)

        # Stretch vooraan en achteraan zodat de balk gecentreerd
        # uitlijnt in de breedte van het venster. De content tussen
        # de stretches blijft compact, ongeacht hoe breed het venster
        # is.
        layout.addStretch()

        # Label "Zoeken:" links van het tekstveld voor duidelijkheid
        self.lbl_find = QLabel(_("find_label"))
        layout.addWidget(self.lbl_find)

        self.input = QLineEdit()
        self.input.setPlaceholderText(_("find_placeholder"))
        self.input.setFixedWidth(280)
        self.input.textChanged.connect(self._on_text_changed)
        self.input.returnPressed.connect(self._find_next)
        layout.addWidget(self.input)

        self.match_label = QLabel("")
        # Vaste breedte (geen minimum) voorkomt dat het label
        # uitgerekt wordt als de tekst lang is, wat eerder een
        # rendering-glitch gaf waarbij hij dubbel leek te
        # verschijnen.
        self.match_label.setFixedWidth(80)
        self.match_label.setAlignment(Qt.AlignCenter)
        layout.addWidget(self.match_label)

        self.btn_prev = QPushButton("▲")
        self.btn_prev.setToolTip(_("find_prev"))
        self.btn_prev.setFixedSize(36, 32)
        self.btn_prev.clicked.connect(self._find_prev)
        layout.addWidget(self.btn_prev)

        self.btn_next = QPushButton("▼")
        self.btn_next.setToolTip(_("find_next"))
        self.btn_next.setFixedSize(36, 32)
        self.btn_next.clicked.connect(self._find_next)
        layout.addWidget(self.btn_next)

        self.btn_close = QPushButton("✕")
        self.btn_close.setToolTip(_("find_close"))
        self.btn_close.setFixedSize(36, 32)
        self.btn_close.clicked.connect(self.hide_and_clear)
        layout.addWidget(self.btn_close)

        # Stretch achteraan voor centreren
        layout.addStretch()

        # Esc-toets binnen het tekstveld sluit de balk
        self._sc_esc = QShortcut(QKeySequence(Qt.Key_Escape), self)
        self._sc_esc.activated.connect(self.hide_and_clear)
        self._sc_esc.setContext(Qt.WidgetWithChildrenShortcut)

    def show_and_focus(self):
        """Toon de balk, vul tekstveld met huidige selectie, focus."""
        # Als er tekst is geselecteerd in de webview, vul die alvast
        # in het zoekveld zodat de gebruiker niet hoeft te typen.
        try:
            selected = self._view.page().selectedText() or ""
            if selected.strip():
                self.input.setText(selected.strip()[:200])
                self.input.selectAll()
        except Exception:
            pass
        self.show()
        self.input.setFocus()
        if self.input.text():
            self.input.selectAll()
            self._do_find(self.input.text())

    def hide_and_clear(self):
        """Verberg de balk en wis de highlighting in de webview."""
        try:
            self._view.findText("")  # leeg = clear highlights
        except Exception:
            pass
        self.hide()
        self.closed.emit()

    def _on_text_changed(self, text):
        """Live zoeken terwijl de gebruiker typt."""
        self._do_find(text)

    def _do_find(self, text, backward=False):
        """Roep findText() aan met juiste flags en update label."""
        
        flags = QWebEnginePage.FindFlag(0)
        if backward:
            flags |= QWebEnginePage.FindBackward

        if not text:
            self.match_label.setText("")
            try:
                self._view.findText("")
            except Exception:
                pass
            return

        # QtWebEngine 6.3+ heeft een callback met FindTextResult die
        # match-aantallen geeft. Bij oudere versies fallback op een
        # eenvoudige found/not found indicatie.
        try:
            # (intra-import gestript: from core.lang import _)
            def _cb(result):
                try:
                    nb = result.numberOfMatches()
                    idx = result.activeMatch()
                    if nb > 0:
                        self.match_label.setText(
                            f"{idx} / {nb}"
                        )
                        self.input.setStyleSheet("")
                    else:
                        self.match_label.setText(_("find_no_match"))
                        self.input.setStyleSheet(
                            "QLineEdit { border-color: #aa3333; }"
                        )
                except Exception:
                    pass
            self._view.findText(text, flags, _cb)
        except Exception:
            # Fallback: oude API zonder callback
            try:
                self._view.findText(text, flags)
                self.match_label.setText("")
            except Exception:
                pass

    def _find_next(self):
        self._do_find(self.input.text(), backward=False)

    def _find_prev(self):
        self._do_find(self.input.text(), backward=True)


class CustomWebPage(QWebEnginePage):
    """
    Subclass van QWebEnginePage met twee belangrijke uitbreidingen:

    1. createWindow - target="_blank" links openen in nieuwe tab
       (zonder dit blijven die kliks zonder effect — geleerde les uit DeskButler)

    2. javaScriptConsoleMessage - console.log/warn/error in webpagina's
       naar dravenlock.log met prefix [JS]
    """

    # Signal: een link wil een nieuwe tab openen — de hoofdwindow vangt op
    new_tab_requested = Signal(object)  # returns the new page

    def __init__(self, profile: QWebEngineProfile, parent=None):
        super().__init__(profile, parent)
        self._browser_window = None  # wordt gezet door WebTab

    def set_browser_window(self, window):
        """Geef referentie naar het hoofdvenster, voor createWindow."""
        self._browser_window = window

    def javaScriptConsoleMessage(self, level, msg, line, src):
        """Log console-berichten uit webpagina's naar dravenlock.log."""
        try:
            lvl = int(level.value) if hasattr(level, "value") else int(level)
        except Exception:
            lvl = 0
        tags = {0: "INFO", 1: "WARN", 2: "ERR "}
        tag = tags.get(lvl, "?   ")
        m = msg if len(msg) < 400 else msg[:400] + "..."
        try:
            print(f"[JS {tag}] {m}    ({src}:{line})")
        except Exception:
            pass

    def createWindow(self, window_type):
        """
        Wordt aangeroepen bij:
          - target="_blank" links
          - middle-click op een link
          - window.open() vanuit JavaScript

        We maken een nieuwe tab in onze browser-window en retourneren
        de page daarvan, zodat Qt de URL daar automatisch naartoe navigeert.
        """
        if self._browser_window is None:
            print("[browser] createWindow: geen window bekend, link genegeerd")
            return None
        try:
            print("[browser] createWindow: nieuwe tab voor link")
            new_tab = self._browser_window.new_tab(url="", switch_to=True)
            return new_tab.page
        except Exception as e:
            print(f"[browser] createWindow faalde: {e}")
            return None


class WebTab(QWidget):
    """
    Eén tabblad met een QWebEngineView + onze CustomWebPage.

    Signals:
        url_changed(QUrl) — wanneer de URL van deze tab wijzigt
        title_changed(str) — wanneer de pagina-titel wijzigt
        load_finished(bool) — wanneer een pagelaad eindigt (ok=success)
    """

    url_changed = Signal(QUrl)
    title_changed = Signal(str)
    load_finished = Signal(bool)

    def __init__(self, browser_window=None, url: str = ""):
        super().__init__()
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)

        self.view = QWebEngineView()
        # Gebruik default-profile zodat AdBlock-interceptor werkt
        profile = QWebEngineProfile.defaultProfile()
        self.page = CustomWebPage(profile, self.view)
        self.page.set_browser_window(browser_window)
        self.view.setPage(self.page)

        # Doorgeef-signals
        self.view.urlChanged.connect(self.url_changed.emit)
        self.view.titleChanged.connect(self.title_changed.emit)
        self.view.titleChanged.connect(self._on_title_changed)
        self.view.loadFinished.connect(self.load_finished.emit)

        # Find-bar voor "Zoeken op pagina". Initieel verborgen,
        # wordt getoond via Ctrl+F of het rechtsklik-menu.
        self.find_bar = FindBar(self.view, self)
        self.find_bar.hide()
        layout.addWidget(self.find_bar)

        layout.addWidget(self.view)

        # Custom context menu (rechtsklik)
        self.view.setContextMenuPolicy(Qt.CustomContextMenu)
        self.view.customContextMenuRequested.connect(self._on_context_menu)
        self._browser_window = browser_window

        # Bij elke succesvolle pagelaad: enabled extensies injecteren
        self.view.loadFinished.connect(self._on_load_finished)

        if url:
            self.load(url)

    def show_find_bar(self):
        """Toon de zoekbalk en geef hem focus."""
        self.find_bar.show_and_focus()

    def _on_context_menu(self, pos):
        """
        Rechtsklik in webpagina: toon uitgebreid menu met klembord-
        acties, navigatie, pagina-acties en tools. We bouwen het menu
        zelf op in plaats van Qt's default te gebruiken, zodat de
        volgorde en groepering consistent zijn met de oude versie.
        """
        
        # (intra-import gestript: from core.lang import _)

        menu = QMenu(self)
        page = self.view.page()
        url = self.current_url()
        has_url = bool(url and url != "about:blank")

        # Check of er tekst is geselecteerd. QWebEnginePage.selectedText()
        # geeft synchroon de huidige selectie terug, dus we kunnen
        # daarop besluiten of we de Kopieer-actie tonen.
        selected_text = ""
        try:
            selected_text = page.selectedText() or ""
        except Exception:
            pass
        has_selection = bool(selected_text.strip())

        # === Groep 1: Klembord ===
        # Kopieer-actie alleen tonen wanneer er iets is geselecteerd,
        # want anders is hij toch grijs. Op die manier blijft het
        # menu kort en relevant voor de huidige situatie.
        if has_selection:
            act_copy = menu.addAction(_("ctx_copy"))
            act_copy.triggered.connect(
                lambda: page.triggerAction(QWebEnginePage.Copy)
            )

        act_paste = menu.addAction(_("ctx_paste"))
        act_paste.triggered.connect(
            lambda: page.triggerAction(QWebEnginePage.Paste)
        )

        act_select_all = menu.addAction(_("ctx_select_all"))
        act_select_all.triggered.connect(
            lambda: page.triggerAction(QWebEnginePage.SelectAll)
        )

        menu.addSeparator()

        # === Groep 2: Navigatie ===
        act_back = menu.addAction(_("ctx_back"))
        act_back.triggered.connect(self.view.back)
        act_back.setEnabled(self.view.history().canGoBack())

        act_forward = menu.addAction(_("ctx_forward"))
        act_forward.triggered.connect(self.view.forward)
        act_forward.setEnabled(self.view.history().canGoForward())

        act_reload = menu.addAction(_("ctx_reload"))
        act_reload.triggered.connect(self.view.reload)

        act_home = menu.addAction(_("ctx_home"))
        if (self._browser_window
                and hasattr(self._browser_window, "_on_home")):
            act_home.triggered.connect(self._browser_window._on_home)
        else:
            act_home.setEnabled(False)

        menu.addSeparator()

        # === Groep 3: Pagina-acties ===
        act_copy_url = menu.addAction(_("ctx_copy_url"))
        act_copy_url.triggered.connect(self._copy_current_url)
        act_copy_url.setEnabled(has_url)

        act_fav = menu.addAction(_("ctx_add_favorite"))
        if (self._browser_window
                and hasattr(self._browser_window,
                            "_on_add_to_favorites")):
            act_fav.triggered.connect(
                self._browser_window._on_add_to_favorites
            )
            act_fav.setEnabled(has_url)
        else:
            act_fav.setEnabled(False)

        act_new_tab = menu.addAction(_("ctx_new_tab"))
        if (self._browser_window
                and hasattr(self._browser_window, "new_tab")):
            act_new_tab.triggered.connect(
                lambda: self._browser_window.new_tab()
            )
        else:
            act_new_tab.setEnabled(False)

        # Pagina downloaden (de feature die er al was)
        if has_url:
            act_download = menu.addAction(_("ctx_download_page"))
            act_download.triggered.connect(
                lambda: self._on_download_request(url)
            )

        menu.addSeparator()

        # === Groep 4: Tools ===
        act_find = menu.addAction(_("ctx_find_on_page"))
        act_find.triggered.connect(self.show_find_bar)
        act_find.setEnabled(has_url)

        act_reader = menu.addAction(_("ctx_reader_mode"))
        if (self._browser_window
                and hasattr(self._browser_window, "_activate_reader")):
            act_reader.triggered.connect(
                lambda: self._browser_window._activate_reader(
                    in_new_tab=False
                )
            )
            act_reader.setEnabled(has_url)
        else:
            act_reader.setEnabled(False)

        act_screenshot = menu.addAction(_("ctx_screenshot"))
        if (self._browser_window
                and hasattr(self._browser_window, "_take_screenshot")):
            act_screenshot.triggered.connect(
                lambda: self._browser_window._take_screenshot(
                    mode="visible", ask_path=True
                )
            )
        else:
            act_screenshot.setEnabled(False)

        act_magnifier = menu.addAction(_("ctx_magnifier"))
        if (self._browser_window
                and hasattr(self._browser_window,
                            "_on_magnifier_menu")):
            act_magnifier.triggered.connect(
                self._browser_window._on_magnifier_menu
            )
            act_magnifier.setEnabled(has_url)
        else:
            act_magnifier.setEnabled(False)

        # Print via QWebEnginePage's eigen print-actie
        act_print = menu.addAction(_("ctx_print"))
        act_print.triggered.connect(self._print_page)
        act_print.setEnabled(has_url)

        # Pagina-bron bekijken via Qt's ViewSource actie
        act_source = menu.addAction(_("ctx_view_source"))
        act_source.triggered.connect(
            lambda: page.triggerAction(QWebEnginePage.ViewSource)
        )
        act_source.setEnabled(has_url)

        menu.exec(self.view.mapToGlobal(pos))

    def _print_page(self):
        """
        Sla de huidige pagina op als PDF. QtWebEngine's printToPdf
        werkt betrouwbaarder dan het systeem-print-dialoog (dat geen
        preview kan tonen voor QtWebEngine-content en op sommige
        Windows-systemen helemaal niets doet). De gebruiker kiest
        een opslag-locatie en daarna rendert QtWebEngine de pagina
        asynchroon als PDF.
        """
        try:
            
            # (intra-import gestript: from core.paths import downloads_dir)
            # (intra-import gestript: from core.lang import _)

            # Stel voorgestelde bestandsnaam voor op basis van titel
            title = self.view.title() or "pagina"
            # Verwijder ongeldige tekens uit bestandsnaam
            safe = "".join(
                c if c.isalnum() or c in " -_" else "_"
                for c in title
            )[:80].strip()
            if not safe:
                safe = "pagina"

            default_path = str(downloads_dir() / f"{safe}.pdf")

            path, _selected = QFileDialog.getSaveFileName(
                self,
                _("ctx_print_save_as"),
                default_path,
                "PDF (*.pdf)"
            )
            if not path:
                return
            if not path.lower().endswith(".pdf"):
                path += ".pdf"

            def on_pdf_done(data):
                """Callback: schrijf de PDF-bytes naar disk."""
                try:
                    if not data:
                        print("[webtab] PDF leeg ontvangen")
                        return
                    with open(path, "wb") as f:
                        f.write(data)
                    print(f"[webtab] PDF opgeslagen: {path}")
                except Exception as e:
                    print(f"[webtab] PDF schrijven faalde: {e}")

            # QtWebEngine printToPdf met callback variant
            self.view.page().printToPdf(on_pdf_done)

        except Exception as e:
            import traceback
            traceback.print_exc()
            print(f"[webtab] print faalde: {e}")

    def _on_download_request(self, url: str):
        """Roep main_window's downloader aan via parent-window."""
        if self._browser_window and hasattr(self._browser_window, "_on_open_downloader"):
            try:
                self._browser_window._on_open_downloader(url)
            except Exception as e:
                print(f"[webtab] download-request faalde: {e}")

    def _copy_current_url(self):
        
        url = self.current_url()
        if url:
            QApplication.clipboard().setText(url)

    def _on_title_changed(self, title: str):
        """Update titel van laatste history-entry voor deze URL."""
        try:
            # (intra-import gestript: from core.history import get_history_manager)
            get_history_manager().update_title(self.current_url(), title)
        except Exception:
            pass

    def _on_load_finished(self, ok: bool):
        """Bij paginalaad: injecteer extensies + log in geschiedenis + dark mode."""
        if not ok:
            return
        url = self.current_url()

        # 1. Log naar geschiedenis (skipt automatisch ongeldige URLs)
        try:
            # (intra-import gestript: from core.history import get_history_manager)
            # Titel halen we via een aparte titleChanged-event als hij
            # nog niet bekend is — geef nu wat we hebben
            title = ""
            try:
                title = self.view.title() or ""
            except Exception:
                pass
            get_history_manager().add(url, title)
        except Exception as e:
            print(f"[history] log faalde: {e}")

        # 2. Injecteer enabled extensies die matchen
        try:
            # (intra-import gestript: from core.browser_extensions import get_extensions_manager)
            mgr = get_extensions_manager()
            matching = mgr.enabled_for_url(url)
            if matching:
                print(f"[extensions] {len(matching)} script(s) voor {url[:60]}")
                for ext in matching:
                    try:
                        self.page.runJavaScript(ext.js)
                    except Exception as e:
                        print(f"[extensions] {ext.name} faalde: {e}")
        except Exception as e:
            print(f"[extensions] injectie-fout: {e}")

        # 3. Per-tab dark mode: auto-toggle als deze host eerder donker was
        try:
            # (intra-import gestript: from core.dark_mode import get_dark_mode_manager, ENABLE_JS)
            if get_dark_mode_manager().is_dark(url):
                print(f"[dark_mode] auto-aan voor {url[:60]}")
                self.page.runJavaScript(ENABLE_JS)
        except Exception as e:
            print(f"[dark_mode] auto-toggle faalde: {e}")

        # 4. Per-host zoom-niveau: stel in op opgeslagen waarde
        try:
            # (intra-import gestript: from core.magnifier import get_zoom_manager)
            saved_zoom = get_zoom_manager().get(url)
            if abs(saved_zoom - self.view.zoomFactor()) > 0.01:
                self.view.setZoomFactor(saved_zoom)
                if abs(saved_zoom - 1.0) > 0.01:
                    print(f"[zoom] auto: {int(saved_zoom*100)}% voor {url[:60]}")
        except Exception as e:
            print(f"[zoom] auto-toggle faalde: {e}")

    def load(self, url: str):
        """Laad een URL. Niet-URLs worden gezocht via de zoekmachine."""
        if not url:
            return
        # Schemas die we direct accepteren (geen zoek-fallback)
        direct_schemes = (
            "http://", "https://", "file://", "about:",
            "data:", "javascript:", "view-source:",
            "dravenlock://",
        )
        if not url.startswith(direct_schemes):
            # Heuristiek: bevat 'punt' en geen spatie = waarschijnlijk URL
            if "." in url and " " not in url:
                url = "https://" + url
            else:
                # Zoeken via DuckDuckGo (later: instelbare zoekmachine)
                from urllib.parse import quote_plus
                url = f"https://duckduckgo.com/?q={quote_plus(url)}"
        self.view.setUrl(QUrl(url))

    def current_url(self) -> str:
        return self.view.url().toString()

    def stop(self):
        """Stop het laden + media. Voor netjes sluiten van tabs."""
        try:
            self.view.setUrl(QUrl("about:blank"))
        except Exception as e:
            print(f"[browser] tab stop faalde: {e}")


# ============================================================
# VAULT WINDOW — beheer-venster
# ============================================================

"""
ui/vault_window.py - Hoofdvenster van de wachtwoordkluis.

Toont een lijst van alle entries en biedt toevoegen/bewerken/verwijderen.
Per entry: site, gebruikersnaam, en knoppen om wachtwoord te kopiëren
of het bewerk-dialoog te openen.

Bij het openen van het venster is de vault al ge-unlocked (de main
window doet dat eerst). Activiteit in dit venster reset de auto-lock
timer.
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, make_primary, make_danger)
# (intra-import gestript: from core.vault import get_vault)
# (intra-import gestript: from ui.dialogs.vault_entry_dialog import VaultEntryDialog, CLIPBOARD_CLEAR_SECONDS)


class VaultWindow(QMainWindow):
    """Beheer-venster voor de wachtwoordkluis."""

    # Signal voor parent als vault wordt gelocked (bv. door auto-lock)
    vault_locked = Signal()

    def __init__(self, parent=None):
        super().__init__(parent, Qt.Window)
        self.setWindowTitle("🔐 Wachtwoordkluis")
        self.resize(900, 600)
        self._all_entries = []
        self._build_ui()
        self._refresh()

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(16, 14, 16, 14)
        root.setSpacing(10)

        # Header met titel + lock-knop rechts
        header = QHBoxLayout()
        title = QLabel("🔐 Wachtwoordkluis")
        title.setFont(title_font())
        header.addWidget(title)
        header.addStretch()

        self.btn_lock = QPushButton("🔒 Vergrendelen")
        self.btn_lock.setFont(base_font())
        self.btn_lock.setMinimumHeight(36)
        self.btn_lock.setToolTip("Sluit de kluis en wis de sleutel uit geheugen")
        self.btn_lock.clicked.connect(self._on_lock)
        header.addWidget(self.btn_lock)

        root.addLayout(header)

        # Zoek-balk
        search_row = QHBoxLayout()
        search_lbl = QLabel("🔍")
        search_lbl.setFont(base_font(14))
        search_row.addWidget(search_lbl)

        self.txt_search = QLineEdit()
        self.txt_search.setFont(base_font(12))
        self.txt_search.setMinimumHeight(34)
        self.txt_search.setPlaceholderText("Zoek op naam, gebruikersnaam of URL...")
        self.txt_search.textChanged.connect(self._on_search)
        search_row.addWidget(self.txt_search, 1)

        root.addLayout(search_row)

        # Status-info bovenaan
        self.lbl_status = QLabel("")
        self.lbl_status.setFont(base_font())
        self.lbl_status.setStyleSheet(f"color:{COLOR.text_dim}; padding:2px;")
        root.addWidget(self.lbl_status)

        # Lijst van entries
        self.lst = QListWidget()
        self.lst.setFont(base_font(11))
        self.lst.itemDoubleClicked.connect(lambda *_: self._on_edit())
        self.lst.currentItemChanged.connect(self._update_buttons)
        root.addWidget(self.lst, 1)

        # Knoppen onderaan
        btn_row = QHBoxLayout()

        self.btn_add = QPushButton("➕ Toevoegen")
        self.btn_add.setFont(QFont(base_font().family(),
                                    base_font().pointSize(), QFont.Bold))
        self.btn_add.setMinimumHeight(40)
        self.btn_add.setMinimumWidth(140)
        make_primary(self.btn_add)
        self.btn_add.clicked.connect(self._on_add)
        btn_row.addWidget(self.btn_add)

        self.btn_edit = QPushButton("✏️ Bewerken")
        self.btn_edit.setFont(base_font())
        self.btn_edit.setMinimumHeight(40)
        self.btn_edit.setMinimumWidth(120)
        self.btn_edit.clicked.connect(self._on_edit)
        btn_row.addWidget(self.btn_edit)

        self.btn_copy_user = QPushButton("📋 Naam")
        self.btn_copy_user.setFont(base_font())
        self.btn_copy_user.setMinimumHeight(40)
        self.btn_copy_user.setMinimumWidth(110)
        self.btn_copy_user.setToolTip("Kopieer gebruikersnaam naar klembord")
        self.btn_copy_user.clicked.connect(self._on_copy_username)
        btn_row.addWidget(self.btn_copy_user)

        self.btn_copy_pwd = QPushButton("📋 Wachtwoord")
        self.btn_copy_pwd.setFont(base_font())
        self.btn_copy_pwd.setMinimumHeight(40)
        self.btn_copy_pwd.setMinimumWidth(150)
        self.btn_copy_pwd.setToolTip(
            f"Kopieer wachtwoord (auto-wist na {CLIPBOARD_CLEAR_SECONDS}s)"
        )
        self.btn_copy_pwd.clicked.connect(self._on_copy_password)
        btn_row.addWidget(self.btn_copy_pwd)

        btn_row.addStretch()

        self.btn_delete = QPushButton("🗑️ Verwijderen")
        self.btn_delete.setFont(base_font())
        self.btn_delete.setMinimumHeight(40)
        self.btn_delete.setMinimumWidth(140)
        make_danger(self.btn_delete)
        self.btn_delete.clicked.connect(self._on_delete)
        btn_row.addWidget(self.btn_delete)

        root.addLayout(btn_row)

        # Tweede knop-rij: master-password wijzigen + recovery
        btn_row2 = QHBoxLayout()
        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet(f"color:{COLOR.border};")
        root.addWidget(sep)

        btn_change_master = QPushButton("🔑 Master-wachtwoord wijzigen")
        btn_change_master.setFont(base_font())
        btn_change_master.setMinimumHeight(36)
        btn_change_master.clicked.connect(self._on_change_master)
        btn_row2.addWidget(btn_change_master)

        btn_recovery = QPushButton("🛟 Recovery-code beheren")
        btn_recovery.setFont(base_font())
        btn_recovery.setMinimumHeight(36)
        btn_recovery.clicked.connect(self._on_manage_recovery)
        btn_row2.addWidget(btn_recovery)

        btn_row2.addStretch()

        btn_close = QPushButton("Sluiten")
        btn_close.setFont(base_font())
        btn_close.setMinimumHeight(36)
        btn_close.clicked.connect(self.close)
        btn_row2.addWidget(btn_close)

        root.addLayout(btn_row2)

    # ------------------------------------------------------------------
    # Lijst-management
    # ------------------------------------------------------------------
    def _refresh(self):
        """Herlaad de hele lijst van entries vanuit de vault."""
        vault = get_vault()
        if not vault.is_unlocked():
            self.close()
            return
        try:
            self._all_entries = vault.list_entries()
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Kon entries niet laden:\n\n{e}")
            self._all_entries = []
        self._render_list(self._all_entries)
        self.lbl_status.setText(
            f"{len(self._all_entries)} wachtwoorden opgeslagen"
        )
        self._update_buttons()

    def _render_list(self, entries: list):
        """Vul de QListWidget met deze entries."""
        self.lst.clear()
        # Sorteer alfabetisch op site
        sorted_entries = sorted(entries, key=lambda e: e.get("site", "").lower())
        for entry in sorted_entries:
            item = QListWidgetItem()
            site = entry.get("site", "?")
            user = entry.get("username", "")
            url = entry.get("url", "")
            label = f"🔑 {site}"
            if user:
                label += f"   ·   {user}"
            if url:
                # Korte hostname
                try:
                    from urllib.parse import urlparse
                    host = urlparse(url).hostname or url
                    label += f"   ·   {host}"
                except Exception:
                    pass
            item.setText(label)
            item.setData(Qt.UserRole, entry["id"])
            self.lst.addItem(item)

    def _on_search(self, text: str):
        """Filter de lijst op zoekterm."""
        get_vault().touch()
        if not text.strip():
            self._render_list(self._all_entries)
            return
        q = text.lower().strip()
        filtered = [
            e for e in self._all_entries
            if q in e.get("site", "").lower()
            or q in e.get("username", "").lower()
            or q in e.get("url", "").lower()
        ]
        self._render_list(filtered)

    def _update_buttons(self):
        has = self.lst.currentItem() is not None
        # Defensief: knoppen bestaan misschien nog niet (tijdens setup)
        for btn_name in ("btn_edit", "btn_copy_user", "btn_copy_pwd", "btn_delete"):
            if hasattr(self, btn_name):
                getattr(self, btn_name).setEnabled(has)

    def _current_entry_id(self) -> str:
        item = self.lst.currentItem()
        if item:
            return item.data(Qt.UserRole)
        return ""

    # ------------------------------------------------------------------
    # Acties
    # ------------------------------------------------------------------
    def _on_add(self):
        get_vault().touch()
        dlg = VaultEntryDialog(entry=None, parent=self)
        if dlg.exec() != dlg.Accepted:
            return
        v = dlg.values()
        try:
            get_vault().add_entry(
                site=v["site"], username=v["username"], password=v["password"],
                url=v["url"], notes=v["notes"],
            )
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Toevoegen faalde:\n\n{e}")
            return
        self._refresh()

    def _on_edit(self):
        eid = self._current_entry_id()
        if not eid:
            return
        get_vault().touch()
        entry = get_vault().get_entry(eid)
        if not entry:
            QMessageBox.warning(self, "Fout", "Entry niet meer te vinden.")
            self._refresh()
            return
        dlg = VaultEntryDialog(entry=entry, parent=self)
        if dlg.exec() != dlg.Accepted:
            return
        v = dlg.values()
        try:
            get_vault().update_entry(
                eid, site=v["site"], username=v["username"],
                password=v["password"], url=v["url"], notes=v["notes"],
            )
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Bijwerken faalde:\n\n{e}")
            return
        self._refresh()

    def _on_delete(self):
        eid = self._current_entry_id()
        if not eid:
            return
        get_vault().touch()
        entry = get_vault().get_entry(eid)
        if not entry:
            return
        r = QMessageBox.question(
            self, "Verwijderen?",
            f"Wachtwoord voor '{entry.get('site', '?')}' "
            f"definitief verwijderen?\n\nDit kan niet ongedaan worden.",
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if r != QMessageBox.Yes:
            return
        get_vault().remove_entry(eid)
        self._refresh()

    def _on_copy_username(self):
        eid = self._current_entry_id()
        if not eid:
            return
        get_vault().touch()
        entry = get_vault().get_entry(eid)
        if entry and entry.get("username"):
            QApplication.clipboard().setText(entry["username"])
            self.lbl_status.setText(
                f"✓ Gebruikersnaam gekopieerd naar klembord"
            )
            QTimer.singleShot(3000, lambda: self.lbl_status.setText(
                f"{len(self._all_entries)} wachtwoorden opgeslagen"
            ))

    def _on_copy_password(self):
        eid = self._current_entry_id()
        if not eid:
            return
        get_vault().touch()
        entry = get_vault().get_entry(eid)
        if not entry or not entry.get("password"):
            return
        pwd = entry["password"]
        QApplication.clipboard().setText(pwd)
        self.lbl_status.setText(
            f"✓ Wachtwoord gekopieerd — wordt over {CLIPBOARD_CLEAR_SECONDS}s gewist"
        )
        QTimer.singleShot(3000, lambda: self.lbl_status.setText(
            f"{len(self._all_entries)} wachtwoorden opgeslagen"
        ))

        # Auto-clear na 30 sec — alleen als ons wachtwoord nog in klembord staat
        def _clear():
            try:
                if QApplication.clipboard().text() == pwd:
                    QApplication.clipboard().clear()
                    print("[vault] klembord auto-gewist")
            except Exception:
                pass

        QTimer.singleShot(CLIPBOARD_CLEAR_SECONDS * 1000, _clear)

    def _on_lock(self):
        """Sluit de vault handmatig."""
        get_vault().lock()
        self.vault_locked.emit()
        self.close()

    def _on_change_master(self):
        """Wijzig master-wachtwoord."""
        get_vault().touch()
        current, ok = QInputDialog.getText(
            self, "Huidige master-wachtwoord",
            "Voer het huidige master-wachtwoord in:",
            QLineEdit.Password,
        )
        if not ok or not current:
            return
        new, ok = QInputDialog.getText(
            self, "Nieuw master-wachtwoord",
            "Voer het nieuwe master-wachtwoord in:",
            QLineEdit.Password,
        )
        if not ok or not new:
            return
        confirm, ok = QInputDialog.getText(
            self, "Bevestig",
            "Bevestig het nieuwe master-wachtwoord:",
            QLineEdit.Password,
        )
        if not ok:
            return
        if new != confirm:
            QMessageBox.warning(self, "Validatie",
                                "Nieuwe wachtwoorden komen niet overeen.")
            return
        try:
            ok = get_vault().change_master_password(current, new)
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Wijzigen mislukte:\n\n{e}")
            return
        if not ok:
            QMessageBox.warning(self, "Verkeerd wachtwoord",
                                "Het huidige master-wachtwoord klopt niet.")
            return
        QMessageBox.information(
            self, "Gewijzigd",
            "Master-wachtwoord is succesvol gewijzigd.\n\n"
            "⚠ Recovery-code (indien eerder ingesteld) is uitgeschakeld. "
            "Stel hem opnieuw in via 'Recovery-code beheren'."
        )

    def _on_manage_recovery(self):
        """Recovery-code instellen, wijzigen of verwijderen."""
        get_vault().touch()
        v = get_vault()
        if v.has_recovery():
            r = QMessageBox.question(
                self, "Recovery-code",
                "Er is al een recovery-code ingesteld.\n\n"
                "Wat wil je doen?\n"
                "• Ja = Nieuwe recovery-code instellen (oude vervalt)\n"
                "• Nee = Recovery-code uitschakelen",
                QMessageBox.Yes | QMessageBox.No | QMessageBox.Cancel,
                QMessageBox.Cancel,
            )
            if r == QMessageBox.Cancel:
                return
            if r == QMessageBox.No:
                v.set_recovery(None)
                QMessageBox.information(self, "Uitgeschakeld",
                                        "Recovery-code is verwijderd.")
                return

        # Nieuwe code instellen
        # (intra-import gestript: from core.vault import generate_password)
        suggested = generate_password(length=20, include_symbols=False,
                                       exclude_ambiguous=True)
        suggested = "-".join(suggested[i:i+4] for i in range(0, 20, 4))
        code, ok = QInputDialog.getText(
            self, "Recovery-code",
            "Voer een recovery-code in (of gebruik de voorgestelde):",
            QLineEdit.Normal,
            suggested,
        )
        if not ok or not code.strip():
            return
        try:
            v.set_recovery(code.strip())
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Instellen mislukte:\n\n{e}")
            return
        QMessageBox.information(
            self, "Recovery-code ingesteld",
            f"Schrijf deze recovery-code op een veilige plek:\n\n"
            f"    {code}\n\n"
            f"Zonder deze code (of het master-wachtwoord) is er geen "
            f"toegang tot de kluis."
        )

    def closeEvent(self, event):
        """Bij sluiten: vault blijft open, alleen het venster gaat dicht."""
        super().closeEvent(event)


# ============================================================
# FAVORITES WINDOW — beheer-venster
# ============================================================

"""
ui/favorites_window.py - Beheer-venster voor favorieten.

Toont een tree-view met mappen + favorieten erin. Boven elke knop:
- ➕ Nieuwe map
- 🌐 Openen (geselecteerde favoriet in nieuwe tab)
- ✏️ Bewerken
- 🗑️ Verwijderen

Rechtsklik op item: snelmenu.
Dubbelklik op favoriet: openen in nieuwe tab.
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, make_primary, make_danger)
# (intra-import gestript: from core.favorites import get_favorites_manager)


class FavoritesWindow(QMainWindow):
    """Beheer-venster voor favorieten met mappen."""

    # Signaal: gebruiker wil een URL openen (in een nieuwe tab)
    favorite_opened = Signal(str)

    def __init__(self, parent=None):
        super().__init__(parent, Qt.Window)
        self.setWindowTitle("⭐ Favorieten")
        self.resize(900, 700)
        self._build_ui()
        self._populate()

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(16, 14, 16, 14)
        root.setSpacing(10)

        # Titel
        title = QLabel("⭐ Favorieten")
        title.setFont(title_font())
        root.addWidget(title)

        # Info
        info = QLabel(
            "Dubbelklik op een favoriet om hem te openen. "
            "Rechtsklik voor meer opties."
        )
        info.setFont(base_font())
        info.setWordWrap(True)
        info.setStyleSheet(f"color:{COLOR.text_dim}; padding:4px;")
        root.addWidget(info)

        # Tree widget
        self.tree = QTreeWidget()
        self.tree.setFont(base_font(11))
        self.tree.setHeaderLabels(["Naam", "URL"])
        self.tree.setColumnWidth(0, 360)
        self.tree.setRootIsDecorated(True)
        self.tree.setAlternatingRowColors(True)
        self.tree.setContextMenuPolicy(Qt.CustomContextMenu)
        self.tree.customContextMenuRequested.connect(self._on_context_menu)
        self.tree.itemDoubleClicked.connect(self._on_double_click)
        root.addWidget(self.tree, 1)

        # Knoppen onderaan
        btn_row = QHBoxLayout()

        self.btn_new_folder = QPushButton("📁 Nieuwe map")
        self.btn_new_folder.setFont(QFont(base_font().family(),
                                            base_font().pointSize(), QFont.Bold))
        self.btn_new_folder.setMinimumHeight(40)
        self.btn_new_folder.setMinimumWidth(150)
        make_primary(self.btn_new_folder)
        self.btn_new_folder.clicked.connect(self._on_new_folder)
        btn_row.addWidget(self.btn_new_folder)

        self.btn_open = QPushButton("🌐 Openen")
        self.btn_open.setFont(base_font())
        self.btn_open.setMinimumHeight(40)
        self.btn_open.setMinimumWidth(130)
        self.btn_open.clicked.connect(self._on_open_selected)
        btn_row.addWidget(self.btn_open)

        self.btn_edit = QPushButton("✏️ Bewerken")
        self.btn_edit.setFont(base_font())
        self.btn_edit.setMinimumHeight(40)
        self.btn_edit.setMinimumWidth(130)
        self.btn_edit.clicked.connect(self._on_edit_selected)
        btn_row.addWidget(self.btn_edit)

        self.btn_delete = QPushButton("🗑️ Verwijderen")
        self.btn_delete.setFont(base_font())
        self.btn_delete.setMinimumHeight(40)
        self.btn_delete.setMinimumWidth(150)
        make_danger(self.btn_delete)
        self.btn_delete.clicked.connect(self._on_delete_selected)
        btn_row.addWidget(self.btn_delete)

        btn_row.addStretch()

        btn_close = QPushButton("Sluiten")
        btn_close.setFont(base_font())
        btn_close.setMinimumHeight(40)
        btn_close.setMinimumWidth(120)
        btn_close.clicked.connect(self.close)
        btn_row.addWidget(btn_close)

        root.addLayout(btn_row)

    # ------------------------------------------------------------------
    # Tree-populatie
    # ------------------------------------------------------------------
    def _populate(self):
        """Vul de tree opnieuw met alle mappen en favorieten."""
        self.tree.clear()
        mgr = get_favorites_manager()

        # Mappen eerst
        for folder in mgr.all_folders():
            folder_item = QTreeWidgetItem(self.tree)
            count = len(folder["favorites"])
            folder_item.setText(0, f"📁  {folder['name']}  ({count})")
            folder_item.setText(1, "")
            folder_item.setData(0, Qt.UserRole, {
                "type": "folder", "id": folder["id"],
            })
            # Vetgedrukt
            f = folder_item.font(0)
            f.setBold(True)
            folder_item.setFont(0, f)
            # Favorieten in deze map
            for fav in folder["favorites"]:
                fav_item = QTreeWidgetItem(folder_item)
                fav_item.setText(0, f"⭐ {fav['title']}")
                fav_item.setText(1, fav["url"])
                fav_item.setToolTip(1, fav["url"])
                fav_item.setData(0, Qt.UserRole, {
                    "type": "favorite",
                    "id": fav["id"],
                    "folder_id": folder["id"],
                })
            folder_item.setExpanded(True)

        # Root-favorieten
        for fav in mgr.root_favorites():
            fav_item = QTreeWidgetItem(self.tree)
            fav_item.setText(0, f"⭐ {fav['title']}")
            fav_item.setText(1, fav["url"])
            fav_item.setToolTip(1, fav["url"])
            fav_item.setData(0, Qt.UserRole, {
                "type": "favorite",
                "id": fav["id"],
                "folder_id": None,
            })

        self._update_buttons()
        # Connect één keer: bij eerste populate. Daarna blijft signal staan.
        if not getattr(self, "_signal_connected", False):
            self.tree.currentItemChanged.connect(lambda *_: self._update_buttons())
            self._signal_connected = True

    def _update_buttons(self):
        item = self.tree.currentItem()
        data = item.data(0, Qt.UserRole) if item else None
        is_fav = bool(data and data.get("type") == "favorite")
        has_any = item is not None
        self.btn_open.setEnabled(is_fav)
        self.btn_edit.setEnabled(is_fav)
        self.btn_delete.setEnabled(has_any)

    # ------------------------------------------------------------------
    # Acties
    # ------------------------------------------------------------------
    def _selected_data(self) -> dict:
        item = self.tree.currentItem()
        if not item:
            return {}
        return item.data(0, Qt.UserRole) or {}

    def _on_double_click(self, item, _col):
        data = item.data(0, Qt.UserRole) or {}
        if data.get("type") == "favorite":
            fav = get_favorites_manager().find(data["id"])
            if fav:
                self.favorite_opened.emit(fav["url"])

    def _on_open_selected(self):
        data = self._selected_data()
        if data.get("type") != "favorite":
            return
        fav = get_favorites_manager().find(data["id"])
        if fav:
            self.favorite_opened.emit(fav["url"])

    def _on_edit_selected(self):
        data = self._selected_data()
        if data.get("type") != "favorite":
            return
        mgr = get_favorites_manager()
        fav = mgr.find(data["id"])
        if not fav:
            return
        # (intra-import gestript: from ui.dialogs.favorite_edit_dialog import EditFavoriteDialog)
        dlg = EditFavoriteDialog(
            fav=fav,
            current_folder_id=data.get("folder_id"),
            parent=self,
        )
        if dlg.exec() != QDialog.Accepted:
            return
        mgr.update(data["id"], title=dlg.title(), url=dlg.url())
        if dlg.folder_id() != data.get("folder_id"):
            mgr.move_to_folder(data["id"], dlg.folder_id())
        self._populate()

    def _on_delete_selected(self):
        data = self._selected_data()
        if not data:
            return
        if data.get("type") == "folder":
            r = QMessageBox.question(
                self, "Map verwijderen?",
                "Wilt u deze map verwijderen?\n\n"
                "De favorieten in deze map worden niet verwijderd — "
                "ze gaan naar het hoofdniveau.",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if r != QMessageBox.Yes:
                return
            get_favorites_manager().remove_folder(
                data["id"], move_to_root=True
            )
        else:
            r = QMessageBox.question(
                self, "Verwijderen?",
                "Wilt u deze favoriet verwijderen?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if r != QMessageBox.Yes:
                return
            get_favorites_manager().remove(data["id"])
        self._populate()

    def _on_new_folder(self):
        name, ok = QInputDialog.getText(
            self, "Nieuwe map", "Naam voor de nieuwe map:",
        )
        if not ok or not name.strip():
            return
        get_favorites_manager().add_folder(name.strip())
        self._populate()

    def _on_rename_folder(self):
        data = self._selected_data()
        if data.get("type") != "folder":
            return
        mgr = get_favorites_manager()
        # Zoek huidige naam
        current_name = ""
        for folder in mgr.all_folders():
            if folder["id"] == data["id"]:
                current_name = folder["name"]
                break
        new_name, ok = QInputDialog.getText(
            self, "Naam wijzigen",
            "Nieuwe naam:", text=current_name,
        )
        if not ok or not new_name.strip():
            return
        mgr.rename_folder(data["id"], new_name.strip())
        self._populate()

    def _on_context_menu(self, pos):
        item = self.tree.itemAt(pos)
        if not item:
            return
        self.tree.setCurrentItem(item)
        data = item.data(0, Qt.UserRole) or {}
        menu = QMenu(self)
        if data.get("type") == "favorite":
            menu.addAction("🌐  Openen", self._on_open_selected)
            menu.addAction("✏️  Bewerken", self._on_edit_selected)
            menu.addSeparator()
            menu.addAction("🗑️  Verwijderen", self._on_delete_selected)
        elif data.get("type") == "folder":
            menu.addAction("📝  Naam wijzigen", self._on_rename_folder)
            menu.addSeparator()
            menu.addAction("🗑️  Map verwijderen", self._on_delete_selected)
        menu.exec(self.tree.mapToGlobal(pos))


# ============================================================
# EXTENSIONS WINDOW — beheer-venster
# ============================================================

"""
ui/extensions_window.py - Beheer-venster voor browser-extensies.

Toont een lijst van alle extensies (ingebouwd + gebruikers) met:
  - Toggle aan/uit
  - Beschrijving wanneer geselecteerd
  - "Nieuwe extensie" knop voor eigen scripts
  - Bewerken/verwijderen voor user-extensies (niet voor builtins!)
"""




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, make_primary, make_danger)
# (intra-import gestript: from core.browser_extensions import get_extensions_manager)


class ExtensionsWindow(QMainWindow):
    """Beheer-venster voor extensies."""

    # Signaal: extensies gewijzigd — main_window kan tabs verversen
    extensions_changed = Signal()

    def __init__(self, parent=None):
        super().__init__(parent, Qt.Window)
        self.setWindowTitle("🧩 Extensies")
        self.resize(900, 640)
        self._build_ui()
        self._populate()

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(16, 14, 16, 14)
        root.setSpacing(10)

        title = QLabel("🧩 Browser-extensies")
        title.setFont(title_font())
        root.addWidget(title)

        info = QLabel(
            "Schakel ingebouwde extensies aan/uit, of voeg eigen "
            "JavaScript-scripts toe. Scripts worden uitgevoerd op pagina's "
            "die voldoen aan hun URL-patroon."
        )
        info.setFont(base_font())
        info.setWordWrap(True)
        info.setStyleSheet(f"color:{COLOR.text_dim}; padding:4px;")
        root.addWidget(info)

        # Splitter: links lijst, rechts details
        splitter = QSplitter(Qt.Horizontal)

        # Linker paneel: lijst
        self.lst = QListWidget()
        self.lst.setFont(base_font(11))
        self.lst.currentItemChanged.connect(lambda *_: self._on_selection_changed())
        splitter.addWidget(self.lst)

        # Rechter paneel: details
        right = QWidget()
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(8, 0, 0, 0)
        right_layout.setSpacing(8)

        self.lbl_name = QLabel("(geen extensie geselecteerd)")
        self.lbl_name.setFont(title_font(13))
        right_layout.addWidget(self.lbl_name)

        self.lbl_type = QLabel("")
        self.lbl_type.setFont(base_font())
        self.lbl_type.setStyleSheet(f"color:{COLOR.text_dim};")
        right_layout.addWidget(self.lbl_type)

        self.lbl_pattern = QLabel("")
        self.lbl_pattern.setFont(base_font())
        self.lbl_pattern.setStyleSheet(f"color:{COLOR.text_dim};")
        right_layout.addWidget(self.lbl_pattern)

        # Beschrijving in een read-only textedit (scrollbaar)
        self.txt_description = QTextEdit()
        self.txt_description.setReadOnly(True)
        self.txt_description.setFont(base_font(11))
        self.txt_description.setStyleSheet(
            f"QTextEdit {{ background:{COLOR.bg_1}; "
            f"color:{COLOR.text}; border:1px solid {COLOR.border}; "
            f"border-radius:4px; padding:8px; }}"
        )
        right_layout.addWidget(self.txt_description, 1)

        # Aan/uit toggle
        self.chk_enabled = QCheckBox("✓ Ingeschakeld")
        self.chk_enabled.setFont(QFont(base_font().family(),
                                        base_font().pointSize(), QFont.Bold))
        self.chk_enabled.stateChanged.connect(self._on_toggle)
        right_layout.addWidget(self.chk_enabled)

        # Knoppen voor user-extensies (worden disabled voor builtins)
        btn_row = QHBoxLayout()
        self.btn_edit = QPushButton("✏️ Bewerken")
        self.btn_edit.setFont(base_font())
        self.btn_edit.setMinimumHeight(36)
        self.btn_edit.clicked.connect(self._on_edit_user)
        btn_row.addWidget(self.btn_edit)

        self.btn_delete = QPushButton("🗑️ Verwijderen")
        self.btn_delete.setFont(base_font())
        self.btn_delete.setMinimumHeight(36)
        make_danger(self.btn_delete)
        self.btn_delete.clicked.connect(self._on_delete_user)
        btn_row.addWidget(self.btn_delete)
        btn_row.addStretch()
        right_layout.addLayout(btn_row)

        splitter.addWidget(right)
        splitter.setSizes([300, 600])
        root.addWidget(splitter, 1)

        # Bottom-knoppen
        bottom_row = QHBoxLayout()

        self.btn_new = QPushButton("➕ Nieuwe extensie")
        self.btn_new.setFont(QFont(base_font().family(),
                                    base_font().pointSize(), QFont.Bold))
        self.btn_new.setMinimumHeight(40)
        self.btn_new.setMinimumWidth(180)
        make_primary(self.btn_new)
        self.btn_new.clicked.connect(self._on_new)
        bottom_row.addWidget(self.btn_new)

        bottom_row.addStretch()

        btn_close = QPushButton("Sluiten")
        btn_close.setFont(base_font())
        btn_close.setMinimumHeight(40)
        btn_close.setMinimumWidth(120)
        btn_close.clicked.connect(self.close)
        bottom_row.addWidget(btn_close)

        root.addLayout(bottom_row)

    # ------------------------------------------------------------------
    # Populate + selection
    # ------------------------------------------------------------------
    def _populate(self):
        self.lst.clear()
        mgr = get_extensions_manager()

        # Builtins eerst
        for ext in mgr.builtins():
            item = QListWidgetItem()
            check = "✓ " if ext.enabled else "  "
            item.setText(f"{check}{ext.name}")
            item.setData(Qt.UserRole, ext.ext_id)
            self.lst.addItem(item)

        # Sectie-scheider als er gebruikers-extensies zijn
        users = mgr.user_extensions()
        if users:
            sep = QListWidgetItem("─── Eigen extensies ───")
            sep.setFlags(Qt.NoItemFlags)  # niet selecteerbaar
            f = sep.font()
            f.setItalic(True)
            sep.setFont(f)
            sep.setForeground(Qt.gray)
            self.lst.addItem(sep)
            for ext in users:
                item = QListWidgetItem()
                check = "✓ " if ext.enabled else "  "
                item.setText(f"{check}{ext.name}")
                item.setData(Qt.UserRole, ext.ext_id)
                self.lst.addItem(item)

        if self.lst.count() > 0:
            # Selecteer eerste echte item (sla scheider over)
            for i in range(self.lst.count()):
                item = self.lst.item(i)
                if item.flags() & Qt.ItemIsSelectable:
                    self.lst.setCurrentRow(i)
                    break

    def _current_ext(self):
        item = self.lst.currentItem()
        if not item or not (item.flags() & Qt.ItemIsSelectable):
            return None
        ext_id = item.data(Qt.UserRole)
        return get_extensions_manager().get(ext_id)

    def _on_selection_changed(self):
        ext = self._current_ext()
        if not ext:
            self.lbl_name.setText("(geen extensie geselecteerd)")
            self.lbl_type.setText("")
            self.lbl_pattern.setText("")
            self.txt_description.clear()
            self.chk_enabled.setEnabled(False)
            self.btn_edit.setEnabled(False)
            self.btn_delete.setEnabled(False)
            return

        self.lbl_name.setText(ext.name)
        type_label = "🔒 Ingebouwd" if ext.type == "builtin" else "👤 Eigen extensie"
        self.lbl_type.setText(type_label)
        self.lbl_pattern.setText(f"URL-patroon: {ext.url_pattern}")
        self.txt_description.setPlainText(ext.description)

        # Voorkom dat toggle-signal afgaat tijdens setter
        self.chk_enabled.blockSignals(True)
        self.chk_enabled.setChecked(ext.enabled)
        self.chk_enabled.blockSignals(False)
        self.chk_enabled.setEnabled(True)

        # Edit/delete alleen voor user-extensies
        is_user = (ext.type == "user")
        self.btn_edit.setEnabled(is_user)
        self.btn_delete.setEnabled(is_user)

    # ------------------------------------------------------------------
    # Acties
    # ------------------------------------------------------------------
    def _on_toggle(self, state):
        ext = self._current_ext()
        if not ext:
            return
        enabled = (state == Qt.Checked.value)
        get_extensions_manager().set_enabled(ext.ext_id, enabled)
        # Update lijst-item (zonder herpopulate, behoudt selectie)
        item = self.lst.currentItem()
        if item:
            check = "✓ " if enabled else "  "
            item.setText(f"{check}{ext.name}")
        self.extensions_changed.emit()

    def _on_new(self):
        # (intra-import gestript: from ui.dialogs.extension_edit_dialog import ExtensionEditDialog)
        dlg = ExtensionEditDialog(ext=None, parent=self)
        if dlg.exec() != QDialog.Accepted:
            return
        v = dlg.values()
        get_extensions_manager().add_user_extension(
            name=v["name"], description=v["description"],
            js=v["js"], url_pattern=v["url_pattern"],
        )
        self._populate()
        self.extensions_changed.emit()

    def _on_edit_user(self):
        ext = self._current_ext()
        if not ext or ext.type != "user":
            return
        # (intra-import gestript: from ui.dialogs.extension_edit_dialog import ExtensionEditDialog)
        dlg = ExtensionEditDialog(ext=ext, parent=self)
        if dlg.exec() != QDialog.Accepted:
            return
        v = dlg.values()
        get_extensions_manager().update_user_extension(
            ext.ext_id,
            name=v["name"], description=v["description"],
            js=v["js"], url_pattern=v["url_pattern"],
        )
        self._populate()
        self.extensions_changed.emit()

    def _on_delete_user(self):
        ext = self._current_ext()
        if not ext or ext.type != "user":
            return
        r = QMessageBox.question(
            self, "Verwijderen?",
            f"Wilt u de extensie '{ext.name}' verwijderen?\n\n"
            "Dit kan niet ongedaan worden gemaakt.",
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if r != QMessageBox.Yes:
            return
        get_extensions_manager().remove_user_extension(ext.ext_id)
        self._populate()
        self.extensions_changed.emit()


# ============================================================
# IMAGE PICKER WINDOW — thumbnails + opslaan
# ============================================================

"""
ui/image_picker_window.py - Venster met thumbnails van alle gevonden
afbeeldingen, met opslaan-functionaliteit.

Layout:
  - Voortgangsbalk bovenaan ("12 / 47 afbeeldingen geladen")
  - QListWidget met thumbnails (grid-modus)
  - Klikken: details rechts (groot voorbeeld + afmetingen + URL)
  - Knoppen onderaan: 💾 Opslaan als / 📋 URL kopiëren / ⚡ Snel opslaan

Belangrijke design-keuzes:
  - Qt.Window flag → top-level, niet verstopt achter browser
  - WindowStaysOnTopHint zou irritant zijn, dus enkel raise + activate
  - Filter te kleine afbeeldingen (<80px) — meestal icoontjes/tracking
"""
import os
import re
from pathlib import Path




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, mono_font, make_primary)
# (intra-import gestript: from core.image_loader import ImageLoaderThread)
# (intra-import gestript: from core.paths import downloads_dir)


# Filter te kleine afbeeldingen (icoontjes, tracking pixels)
MIN_IMG_SIZE = 80


class ImagePickerWindow(QMainWindow):
    """Venster met thumbnails + opslaan."""

    def __init__(self, images: list, parent=None):
        # Top-level window (Qt.Window) — anders verstopt achter browser
        super().__init__(parent, Qt.Window)
        self.setWindowTitle("🖼️ Afbeeldingspikker")
        self.resize(1100, 760)

        # Filter te kleine afbeeldingen weg
        # Behoud wel afbeeldingen waarvan de afmetingen onbekend zijn
        self.images = [
            img for img in images
            if (img.get("width", 0) == 0 and img.get("height", 0) == 0)
            or (img.get("width", 0) >= MIN_IMG_SIZE
                and img.get("height", 0) >= MIN_IMG_SIZE)
        ]
        print(f"[picker] na filter: {len(self.images)} van {len(images)} "
              f"(min {MIN_IMG_SIZE}px)")

        # Houd raw bytes bij voor opslaan zonder opnieuw downloaden
        self._raw_bytes = {}  # index → bytes

        self._build_ui()
        if self.images:
            self._start_loading()
        else:
            self.lbl_status.setText(
                f"⚠ {len(images)} afbeeldingen gevonden, maar alle waren "
                f"te klein (< {MIN_IMG_SIZE}×{MIN_IMG_SIZE} pixels)."
            )
            self.lbl_status.setStyleSheet(f"color:{COLOR.warning};")

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(16, 14, 16, 14)
        root.setSpacing(10)

        title = QLabel("🖼️ Afbeeldingen op deze pagina")
        title.setFont(title_font())
        root.addWidget(title)

        # Status + voortgangsbalk
        status_row = QHBoxLayout()
        self.lbl_status = QLabel("Bezig met laden van thumbnails...")
        self.lbl_status.setFont(base_font())
        status_row.addWidget(self.lbl_status, 1)

        self.bar = QProgressBar()
        self.bar.setMinimumWidth(220)
        self.bar.setMaximumHeight(20)
        status_row.addWidget(self.bar)
        root.addLayout(status_row)

        # Splitter: lijst links, details rechts
        splitter = QSplitter(Qt.Horizontal)

        # Lijst met thumbnails (grid-modus)
        self.lst = QListWidget()
        self.lst.setViewMode(QListWidget.IconMode)
        self.lst.setIconSize(QSize(140, 140))
        self.lst.setGridSize(QSize(160, 180))
        self.lst.setResizeMode(QListWidget.Adjust)
        self.lst.setMovement(QListWidget.Static)
        self.lst.setSpacing(8)
        self.lst.setSelectionMode(QAbstractItemView.SingleSelection)
        self.lst.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.lst.itemDoubleClicked.connect(lambda *_: self._on_save_as())
        self.lst.currentItemChanged.connect(lambda *_: self._on_selection())
        splitter.addWidget(self.lst)

        # Rechter paneel: details
        right = QWidget()
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(8, 0, 0, 0)
        right_layout.setSpacing(8)

        right_layout.addWidget(self._lbl("Voorbeeld:"))
        self.preview = QLabel()
        self.preview.setAlignment(Qt.AlignCenter)
        self.preview.setMinimumSize(280, 280)
        self.preview.setStyleSheet(
            f"QLabel {{ background:{COLOR.bg_deep}; "
            f"border:1px solid {COLOR.border}; border-radius:4px; }}"
        )
        right_layout.addWidget(self.preview, 1)

        self.lbl_info = QLabel("(klik op een afbeelding voor details)")
        self.lbl_info.setFont(base_font())
        self.lbl_info.setWordWrap(True)
        self.lbl_info.setStyleSheet(f"color:{COLOR.text_dim};")
        right_layout.addWidget(self.lbl_info)

        self.lbl_url = QLabel("")
        self.lbl_url.setFont(mono_font(9))
        self.lbl_url.setWordWrap(True)
        self.lbl_url.setStyleSheet(f"color:{COLOR.text_dim};")
        self.lbl_url.setMaximumHeight(50)
        right_layout.addWidget(self.lbl_url)

        splitter.addWidget(right)
        splitter.setSizes([700, 380])
        root.addWidget(splitter, 1)

        # Knoppen onderaan
        btn_row = QHBoxLayout()

        self.btn_save = QPushButton("💾 Opslaan als...")
        self.btn_save.setFont(QFont(base_font().family(),
                                     base_font().pointSize(), QFont.Bold))
        self.btn_save.setMinimumHeight(44)
        self.btn_save.setMinimumWidth(160)
        make_primary(self.btn_save)
        self.btn_save.clicked.connect(self._on_save_as)
        self.btn_save.setEnabled(False)
        btn_row.addWidget(self.btn_save)

        self.btn_quick = QPushButton("⚡ Snel opslaan")
        self.btn_quick.setFont(base_font())
        self.btn_quick.setMinimumHeight(44)
        self.btn_quick.setMinimumWidth(160)
        self.btn_quick.setToolTip(
            f"Sla op in standaard downloads-map ({downloads_dir()})"
        )
        self.btn_quick.clicked.connect(self._on_quick_save)
        self.btn_quick.setEnabled(False)
        btn_row.addWidget(self.btn_quick)

        self.btn_copy = QPushButton("📋 URL kopiëren")
        self.btn_copy.setFont(base_font())
        self.btn_copy.setMinimumHeight(44)
        self.btn_copy.setMinimumWidth(160)
        self.btn_copy.clicked.connect(self._on_copy_url)
        self.btn_copy.setEnabled(False)
        btn_row.addWidget(self.btn_copy)

        btn_row.addStretch()

        btn_close = QPushButton("Sluiten")
        btn_close.setFont(base_font())
        btn_close.setMinimumHeight(44)
        btn_close.setMinimumWidth(120)
        btn_close.clicked.connect(self.close)
        btn_row.addWidget(btn_close)

        root.addLayout(btn_row)

        # Lijst-items vooraf maken met placeholder
        self._make_placeholders()

    def _lbl(self, t):
        lbl = QLabel(t)
        lbl.setFont(base_font())
        return lbl

    def _make_placeholders(self):
        """Maak voor elke afbeelding een lijst-item met '...' placeholder."""
        for i, info in enumerate(self.images):
            label = f"...\n{info.get('width', 0)}×{info.get('height', 0)}"
            item = QListWidgetItem(label)
            item.setData(Qt.UserRole, i)
            item.setSizeHint(QSize(160, 180))
            item.setTextAlignment(Qt.AlignCenter)
            # Placeholder icon (donker vakje)
            placeholder = QPixmap(140, 140)
            placeholder.fill(Qt.darkGray)
            item.setIcon(QIcon(placeholder))
            self.lst.addItem(item)
        # Selecteer expliciet het eerste item — zo is de UX voorspelbaar.
        # _on_selection() ververst de preview zodra de thumbnail binnenkomt
        # (zie _on_image_loaded).
        if self.lst.count() > 0:
            self.lst.setCurrentRow(0)

    # ------------------------------------------------------------------
    # Async laden van thumbnails
    # ------------------------------------------------------------------
    def _start_loading(self):
        self.bar.setMaximum(len(self.images))
        self.bar.setValue(0)
        self.lbl_status.setText(f"0 / {len(self.images)} geladen...")

        self._loader = ImageLoaderThread(self.images, parent=self)
        self._loader.progress.connect(self._on_progress)
        self._loader.image_loaded.connect(self._on_image_loaded)
        self._loader.image_failed.connect(self._on_image_failed)
        self._loader.finished_loading.connect(self._on_loading_done)
        self._loader.start()

    def _on_progress(self, current, total):
        self.bar.setValue(current)
        self.lbl_status.setText(f"{current} / {total} geladen...")

    def _on_image_loaded(self, index, raw_bytes):
        """Vervang placeholder door echte thumbnail."""
        try:
            pm = QPixmap()
            if not pm.loadFromData(raw_bytes):
                # Niet alle formats werken (bv. .webp soms) — toon placeholder
                self._on_image_failed(index, "kon afbeelding niet decoderen")
                return
            self._raw_bytes[index] = raw_bytes
            # Schaal thumbnail behoudend
            thumb = pm.scaled(
                140, 140,
                Qt.KeepAspectRatio,
                Qt.SmoothTransformation,
            )
            item = self.lst.item(index)
            if item:
                item.setIcon(QIcon(thumb))
                info = self.images[index]
                w, h = info.get("width", 0), info.get("height", 0)
                if w == 0 or h == 0:
                    # Gebruik daadwerkelijke afmetingen
                    w, h = pm.width(), pm.height()
                    self.images[index]["width"] = w
                    self.images[index]["height"] = h
                item.setText(f"{w}×{h}")

                # Als dit het GESELECTEERDE item is: refresh de preview rechts
                # (anders blijft die op "(nog niet geladen)" staan)
                current = self.lst.currentItem()
                if current and current.data(Qt.UserRole) == index:
                    self._on_selection()
        except Exception as e:
            print(f"[picker] thumb-fout {index}: {e}")

    def _on_image_failed(self, index, error):
        """Markeer item met foutmelding."""
        item = self.lst.item(index)
        if item:
            item.setText(f"⚠ fout\n{error[:30]}")
            broken = QPixmap(140, 140)
            broken.fill(Qt.darkRed)
            item.setIcon(QIcon(broken))

    def _on_loading_done(self):
        loaded = len(self._raw_bytes)
        total = len(self.images)
        if loaded == 0:
            self.lbl_status.setText("⚠ Geen afbeeldingen konden geladen worden")
            self.lbl_status.setStyleSheet(f"color:{COLOR.error};")
        else:
            self.lbl_status.setText(
                f"✓ Klaar — {loaded} van {total} afbeeldingen geladen"
            )
            self.lbl_status.setStyleSheet(f"color:{COLOR.success};")

    # ------------------------------------------------------------------
    # Selectie + acties
    # ------------------------------------------------------------------
    def _on_selection(self):
        item = self.lst.currentItem()
        if not item:
            self.btn_save.setEnabled(False)
            self.btn_quick.setEnabled(False)
            self.btn_copy.setEnabled(False)
            return

        index = item.data(Qt.UserRole)
        info = self.images[index]

        # Voorbeeld groot tonen (als geladen)
        if index in self._raw_bytes:
            pm = QPixmap()
            pm.loadFromData(self._raw_bytes[index])
            scaled = pm.scaled(
                self.preview.width() - 20,
                self.preview.height() - 20,
                Qt.KeepAspectRatio,
                Qt.SmoothTransformation,
            )
            self.preview.setPixmap(scaled)
            self.btn_save.setEnabled(True)
            self.btn_quick.setEnabled(True)
        else:
            self.preview.setText("(nog niet geladen)")
            self.btn_save.setEnabled(False)
            self.btn_quick.setEnabled(False)

        # Details
        w, h = info.get("width", 0), info.get("height", 0)
        source = info.get("source", "?")
        alt = info.get("alt", "")
        details = f"📐 {w} × {h} px   ·   🔍 bron: {source}"
        if alt:
            details += f"\n📝 {alt[:80]}"
        self.lbl_info.setText(details)
        self.lbl_url.setText(info.get("src", ""))
        self.btn_copy.setEnabled(True)

    def _on_save_as(self):
        """Opslaan met file-dialog."""
        item = self.lst.currentItem()
        if not item:
            return
        index = item.data(Qt.UserRole)
        if index not in self._raw_bytes:
            QMessageBox.warning(self, "Niet geladen",
                                "Wacht tot deze afbeelding geladen is.")
            return
        info = self.images[index]
        url = info.get("src", "")
        suggested_name = self._suggest_filename(url)

        # Start file-dialog in onze eigen downloads-map (consistent met
        # video/audio downloader)
        path, _ = QFileDialog.getSaveFileName(
            self, "Opslaan als",
            str(downloads_dir() / suggested_name),
            "Afbeeldingen (*.png *.jpg *.jpeg *.gif *.webp *.svg);;Alle bestanden (*)",
        )
        if not path:
            return
        try:
            saved_path = Path(path)
            with open(saved_path, "wb") as f:
                f.write(self._raw_bytes[index])
            self.lbl_status.setText(
                f"✓ Opgeslagen: {saved_path.name}   ·   in {saved_path.parent}"
            )
            self.lbl_status.setStyleSheet(f"color:{COLOR.success};")
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Opslaan faalde: {e}")

    def _on_quick_save(self):
        """Direct opslaan in onze downloads-map (geen dialog)."""
        item = self.lst.currentItem()
        if not item:
            return
        index = item.data(Qt.UserRole)
        if index not in self._raw_bytes:
            return
        info = self.images[index]
        url = info.get("src", "")
        suggested_name = self._suggest_filename(url)

        # Gebruik dezelfde downloads-map als video/audio downloader
        downloads = downloads_dir()
        target = downloads / suggested_name

        # Als al bestaat: nummer toevoegen
        n = 1
        while target.exists():
            stem = Path(suggested_name).stem
            ext = Path(suggested_name).suffix
            target = downloads / f"{stem}_{n}{ext}"
            n += 1

        try:
            with open(target, "wb") as f:
                f.write(self._raw_bytes[index])
            self.lbl_status.setText(
                f"✓ Opgeslagen: {target.name}   ·   in {target.parent}"
            )
            self.lbl_status.setStyleSheet(f"color:{COLOR.success};")
        except Exception as e:
            QMessageBox.critical(self, "Fout", f"Opslaan faalde: {e}")

    def _on_copy_url(self):
        item = self.lst.currentItem()
        if not item:
            return
        index = item.data(Qt.UserRole)
        url = self.images[index].get("src", "")
        if url:
            QApplication.clipboard().setText(url)
            self.lbl_status.setText("✓ URL gekopieerd naar klembord")
            self.lbl_status.setStyleSheet(f"color:{COLOR.success};")

    def _suggest_filename(self, url: str) -> str:
        """Bepaal een goede bestandsnaam uit de URL."""
        try:
            # Pak het laatste path-segment
            from urllib.parse import urlparse, unquote
            parsed = urlparse(url)
            name = os.path.basename(unquote(parsed.path))
            # Schoonmaken — illegale chars
            name = re.sub(r'[<>:"/\\|?*]', '_', name)
            if not name or "." not in name:
                name = "afbeelding.jpg"
            return name[:120]
        except Exception:
            return "afbeelding.jpg"

    def closeEvent(self, event):
        """Stop loader-thread netjes bij sluiten."""
        if hasattr(self, "_loader") and self._loader.isRunning():
            self._loader.cancel()
            self._loader.wait(2000)
        super().closeEvent(event)


# ============================================================
# DOWNLOAD PROGRESS — voortgang met cancel
# ============================================================

"""
ui/download_progress_window.py - Voortgangsvenster tijdens downloads.

Toont:
  - Status-tekst (huidige stap)
  - Voortgangsbalk (0-100%)
  - Cancel-knop (stopt yt-dlp proces)
  - Klein log-veld onderaan (uitklapbaar)

Wordt EERST getoond, DAARNA pas thread.start() — geleerde les uit
DeskButler: bij snelle downloads zijn anders de eerste signals al
verstuurd voordat de UI ze kan opvangen.

Twee soorten threads kunnen worden weergegeven:
  - ToolsInstallerThread (tools installeren)
  - DownloaderThread (echte download)
Beide hebben compatibele signals.
"""
import os
import sys
import subprocess
from pathlib import Path




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, mono_font, make_primary, make_danger)


class DownloadProgressWindow(QMainWindow):
    """
    Voortgangsvenster — werkt voor zowel installer- als download-threads.

    Gebruik:
        win = DownloadProgressWindow(title="Downloaden...", parent=self)
        win.bind_thread(my_thread)
        win.show()
        win.raise_()
        my_thread.start()    # ← NA show()!
    """

    closed = Signal()

    def __init__(self, title: str = "Bezig...", parent=None):
        super().__init__(parent, Qt.Window)
        self.setWindowTitle(title)
        self.resize(700, 460)
        self._thread = None
        self._final_path: Path = None
        self._build_ui()

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(20, 16, 20, 16)
        root.setSpacing(12)

        self.lbl_title = QLabel(self.windowTitle())
        self.lbl_title.setFont(title_font())
        root.addWidget(self.lbl_title)

        self.lbl_status = QLabel("Voorbereiden...")
        self.lbl_status.setFont(base_font())
        self.lbl_status.setWordWrap(True)
        self.lbl_status.setTextInteractionFlags(Qt.TextSelectableByMouse)
        self.lbl_status.setMinimumHeight(48)  # ruimte voor 2 regels
        root.addWidget(self.lbl_status)

        self.bar = QProgressBar()
        self.bar.setRange(0, 100)
        self.bar.setValue(0)
        self.bar.setMinimumHeight(24)
        self.bar.setTextVisible(True)
        root.addWidget(self.bar)

        # Log-veld
        root.addWidget(self._lbl("Details:"))
        self.txt_log = QPlainTextEdit()
        self.txt_log.setReadOnly(True)
        self.txt_log.setFont(mono_font(9))
        self.txt_log.setMaximumBlockCount(500)  # voorkom dat het oneindig groeit
        self.txt_log.setStyleSheet(
            f"QPlainTextEdit {{ background:{COLOR.bg_deep}; "
            f"color:{COLOR.text_dim}; border:1px solid {COLOR.border}; "
            f"border-radius:4px; padding:6px; }}"
        )
        root.addWidget(self.txt_log, 1)

        # Knoppen
        btn_row = QHBoxLayout()

        self.btn_open_folder = QPushButton("📂 Open map")
        self.btn_open_folder.setFont(base_font())
        self.btn_open_folder.setMinimumHeight(40)
        self.btn_open_folder.setMinimumWidth(140)
        self.btn_open_folder.setEnabled(False)
        self.btn_open_folder.setVisible(False)
        self.btn_open_folder.clicked.connect(self._on_open_folder)
        btn_row.addWidget(self.btn_open_folder)

        btn_row.addStretch()

        self.btn_cancel = QPushButton("✕ Annuleren")
        self.btn_cancel.setFont(base_font())
        self.btn_cancel.setMinimumHeight(40)
        self.btn_cancel.setMinimumWidth(140)
        make_danger(self.btn_cancel)
        self.btn_cancel.clicked.connect(self._on_cancel)
        btn_row.addWidget(self.btn_cancel)

        self.btn_close = QPushButton("Sluiten")
        self.btn_close.setFont(base_font())
        self.btn_close.setMinimumHeight(40)
        self.btn_close.setMinimumWidth(120)
        self.btn_close.setEnabled(False)
        self.btn_close.clicked.connect(self.close)
        btn_row.addWidget(self.btn_close)

        root.addLayout(btn_row)

    def _lbl(self, t):
        lbl = QLabel(t)
        lbl.setFont(base_font())
        return lbl

    # ------------------------------------------------------------------
    # Thread binding
    # ------------------------------------------------------------------
    def bind_thread(self, thread):
        """Verbind signals van een ToolsInstaller of Downloader thread."""
        self._thread = thread
        # Beide threads hebben deze signals:
        if hasattr(thread, "progress"):
            thread.progress.connect(self._on_progress)
        if hasattr(thread, "log"):
            thread.log.connect(self._on_log)
        if hasattr(thread, "finished_ok"):
            thread.finished_ok.connect(self._on_finished)

    # ------------------------------------------------------------------
    # Slot handlers
    # ------------------------------------------------------------------
    def _on_progress(self, *args):
        """
        Verschillende signal-types:
          progress(int pct, str msg)    — Downloader
          progress(str msg, int pct)    — ToolsInstaller
        We accepteren beide volgordes.
        """
        pct = -1
        msg = ""
        for a in args:
            if isinstance(a, int):
                pct = a
            elif isinstance(a, str):
                msg = a

        if pct >= 0:
            self.bar.setValue(pct)
        if msg:
            self.lbl_status.setText(msg)

    def _on_log(self, line: str):
        self.txt_log.appendPlainText(line)

    def _on_finished(self, *args):
        """
        finished_ok signal-variant:
          (bool ok, str msg)           — ToolsInstaller
          (bool ok, str msg, Path|None) — Downloader
        """
        ok = False
        msg = ""
        path = None
        for a in args:
            if isinstance(a, bool):
                ok = a
            elif isinstance(a, str):
                msg = a
            elif isinstance(a, Path):
                path = a

        if ok:
            self.bar.setValue(100)
            self.lbl_status.setText(msg or "✓ Klaar")
            self.lbl_status.setStyleSheet(f"color:{COLOR.success};")
            self._final_path = path
            if path is not None:
                self.btn_open_folder.setEnabled(True)
                self.btn_open_folder.setVisible(True)
        else:
            self.lbl_status.setText(msg or "Mislukt")
            self.lbl_status.setStyleSheet(f"color:{COLOR.error};")
            # ALSnog open-map knop tonen bij failure — bestand kan er
            # toch staan (gedeeltelijk of door eerdere poging)
            self._final_path = path
            if path is not None:
                self.btn_open_folder.setEnabled(True)
                self.btn_open_folder.setVisible(True)

        # Schakel over van Annuleren naar Sluiten
        self.btn_cancel.setEnabled(False)
        self.btn_cancel.setVisible(False)
        self.btn_close.setEnabled(True)

    # ------------------------------------------------------------------
    # Acties
    # ------------------------------------------------------------------
    def _on_cancel(self):
        if self._thread:
            self.lbl_status.setText("Bezig met afbreken...")
            self._thread.cancel()

    def _on_open_folder(self):
        """Open de map met het gedownloade bestand in Explorer/Finder."""
        if not self._final_path:
            return
        try:
            # Als het een bestand is: pak de parent
            target = self._final_path
            if target.is_file():
                folder = target.parent
            else:
                folder = target

            if sys.platform == "win32":
                # Explorer met /select om het bestand te highlighten als het
                # een bestaand bestand was
                if self._final_path.is_file():
                    subprocess.Popen([
                        "explorer", "/select,", str(self._final_path)
                    ])
                else:
                    os.startfile(str(folder))
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(folder)])
            else:
                subprocess.Popen(["xdg-open", str(folder)])
        except Exception as e:
            QMessageBox.warning(self, "Fout", f"Kon map niet openen: {e}")

    def closeEvent(self, event):
        if self._thread and self._thread.isRunning():
            # Niet sluiten als nog aan het werk
            r = QMessageBox.question(
                self, "Bezig",
                "Download/installatie loopt nog. Wil je echt afbreken?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
            )
            if r != QMessageBox.Yes:
                event.ignore()
                return
            self._thread.cancel()
            self._thread.wait(3000)
        self.closed.emit()
        super().closeEvent(event)


