"""
ui/settings_window.py - Centraal instellingen-venster.

Tabs:
  1. 🌐 Algemeen     - homepage, zoekmachine, taal, AdBlock
  2. 🔐 Privacy      - vault auto-lock, klembord auto-clear
  3. 📂 Downloads    - locatie tonen, "Open map" knop
  4. ℹ️  Over         - versie, paden, links

Strategie:
- Wijzigingen worden DIRECT toegepast (geen "Toepassen" knop)
- Bij dingen die herstart vereisen (taal-wissel): expliciet melden
- "Reset naar standaard" knop onderaan elke tab
"""
import os
import sys
import subprocess
from pathlib import Path




# (intra-import gestript: from core.styling import COLOR, base_font, title_font, mono_font, make_primary)
# (intra-import gestript: from core.config import config, DEFAULTS)
# (intra-import gestript: from core.paths import data_dir, downloads_dir, tools_dir, cache_dir)
# (intra-import gestript: from core.lang import _)


class _HorizontalVerticalTabBar(QTabBar):
    """
    Aangepaste tab-bar die verticaal aan de zijkant staat maar de
    tekst horizontaal tekent in plaats van 90 graden gedraaid. We
    overschrijven sizeHint zodat de tabs breed genoeg zijn voor de
    tekst, en paintEvent zodat de tekst rechtop wordt getekend.
    """

    def tabSizeHint(self, index):
        """Tab-grootte op basis van horizontale tekst."""
        # Bereken de breedte op basis van de tekst en padding
        fm = self.fontMetrics()
        text_width = fm.horizontalAdvance(self.tabText(index))
        # Voeg padding toe (links en rechts)
        width = max(180, text_width + 40)
        # Vaste hoogte zodat alle tabs gelijk zijn
        height = 44
        return QSize(width, height)

    def paintEvent(self, event):
        """Teken elke tab handmatig met horizontale tekst."""
        painter = QPainter(self)
        for index in range(self.count()):
            opt = QStyleOptionTab()
            self.initStyleOption(opt, index)
            # Achtergrond tekenen met de standaard stijl (geeft hover,
            # selected, etc. de juiste look)
            self.style().drawControl(
                QStyle.CE_TabBarTabShape, opt, painter, self
            )
            # Tekst handmatig tekenen, rechtop, met linker uitlijning
            rect = self.tabRect(index)
            # Pas een lichte inset toe zodat tekst niet tegen de rand plakt
            text_rect = QRect(
                rect.x() + 16, rect.y(),
                rect.width() - 24, rect.height()
            )
            # Kleur op basis van selected state
            if index == self.currentIndex():
                painter.setPen(Qt.GlobalColor.cyan)
            else:
                painter.setPen(Qt.GlobalColor.lightGray)
            painter.drawText(
                text_rect,
                int(Qt.AlignVCenter | Qt.AlignLeft),
                self.tabText(index)
            )


# Versie-string (handmatig bijhouden — past beter dan iets parseren)
DRAVENLOCK_VERSION = "5.5.2 (download via GitHub)"

# Donatie-link uit memory
PAYPAL_DONATION_URL = "https://paypal.me/roger076"


class SettingsWindow(QMainWindow):
    """Instellingen-venster met tabbladen."""

    # Signaal als de gebruiker een setting wijzigt die in andere delen
    # van de app van invloed is (bv. AdBlock toggle, taal)
    settings_changed = Signal(str)  # key

    def __init__(self, parent=None):
        super().__init__(parent, Qt.Window)
        self.setWindowTitle("⚙️ Instellingen")
        self.resize(820, 620)
        self._build_ui()

    def _build_ui(self):
        central = QWidget()
        self.setCentralWidget(central)
        root = QVBoxLayout(central)
        root.setContentsMargins(16, 14, 16, 14)
        root.setSpacing(10)

        title = QLabel("⚙️ Instellingen")
        title.setFont(title_font())
        root.addWidget(title)

        # Tab-widget — verticale tabs aan de linkerkant zoals macOS
        # Settings. Dit voorkomt dat de tabbladen-balk te krap wordt
        # bij meer dan vier tabs, en past visueel mooi bij de Snelgids
        # die dezelfde links-navigatie heeft. De Over-tab is verwijderd
        # omdat die nu een eigen menu-item heeft.
        # De objectName 'verticalTabs' wordt door styling.py gebruikt
        # om specifieke regels voor verticale tabs toe te passen
        # zonder de browser-tabs te beinvloeden.
        self.tabs = QTabWidget()
        self.tabs.setObjectName("verticalTabs")
        # Custom tab-bar die de tekst horizontaal tekent ondanks
        # verticale orientatie van de tabs
        self.tabs.setTabBar(_HorizontalVerticalTabBar())
        self.tabs.setTabPosition(QTabWidget.West)
        self.tabs.setFont(base_font(11))
        self.tabs.addTab(self._build_general_tab(), _("settings_tab_general"))
        self.tabs.addTab(self._build_privacy_tab(), _("settings_tab_privacy"))
        self.tabs.addTab(self._build_tts_tab(), _("settings_tab_tts"))
        self.tabs.addTab(self._build_email_tab(), _("settings_tab_email"))
        self.tabs.addTab(self._build_history_tab(), _("settings_tab_history"))
        self.tabs.addTab(self._build_downloads_tab(), _("settings_tab_downloads"))
        root.addWidget(self.tabs, 1)

        # Onderaan: sluiten + reset
        btn_row = QHBoxLayout()

        btn_reset = QPushButton(_("settings_reset_all"))
        btn_reset.setFont(base_font())
        btn_reset.setMinimumHeight(40)
        btn_reset.clicked.connect(self._on_reset_all)
        btn_row.addWidget(btn_reset)

        btn_row.addStretch()

        btn_close = QPushButton(_("btn_close"))
        btn_close.setFont(QFont(base_font().family(),
                                 base_font().pointSize(), QFont.Bold))
        btn_close.setMinimumHeight(40)
        btn_close.setMinimumWidth(140)
        make_primary(btn_close)
        btn_close.clicked.connect(self.close)
        btn_row.addWidget(btn_close)

        root.addLayout(btn_row)

    # ------------------------------------------------------------------
    # Tab 1: Algemeen
    # ------------------------------------------------------------------
    def _build_general_tab(self) -> QWidget:
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(14)

        # Intro
        intro = QLabel(
            _("settings_intro_general")
        )
        intro.setFont(base_font())
        intro.setWordWrap(True)
        intro.setStyleSheet(f"color:{COLOR.text_dim};")
        layout.addWidget(intro)

        form = QFormLayout()
        form.setSpacing(12)

        # Homepage
        self.txt_homepage = QLineEdit(config.get("homepage"))
        self.txt_homepage.setFont(base_font(12))
        self.txt_homepage.setMinimumHeight(36)
        self.txt_homepage.editingFinished.connect(
            lambda: self._save_string("homepage", self.txt_homepage.text())
        )
        form.addRow(self._lbl(_("settings_homepage")), self.txt_homepage)

        # Zoekmachine
        self.cmb_search = QComboBox()
        self.cmb_search.setFont(base_font(12))
        self.cmb_search.setMinimumHeight(36)
        engines = [
            ("duckduckgo", "DuckDuckGo (privacy-vriendelijk)"),
            ("startpage", "Startpage (Google-resultaten, geen tracking)"),
            ("google", "Google"),
            ("bing", "Bing"),
            ("brave", "Brave Search"),
            ("ecosia", "Ecosia (plant bomen)"),
        ]
        for key, label in engines:
            self.cmb_search.addItem(label, key)
        current = config.get("search_engine")
        for i in range(self.cmb_search.count()):
            if self.cmb_search.itemData(i) == current:
                self.cmb_search.setCurrentIndex(i)
                break
        self.cmb_search.currentIndexChanged.connect(
            lambda *_: self._save_string("search_engine",
                                          self.cmb_search.currentData())
        )
        form.addRow(self._lbl(_("settings_search_engine")), self.cmb_search)

        # De taal-keuze is verwijderd nu de browser automatisch de
        # OS-taal detecteert bij eerste run. Een handmatige taal-
        # toggle gaf de illusie dat de UI volledig vertaald was,
        # maar de uitgebreide Snelgids content is nog Nederlands.
        # Door de detectie te volgen krijgen NL-gebruikers automatisch
        # NL en EN-gebruikers automatisch EN, zonder verwarrende
        # half-vertaalde tussenstand.

        layout.addLayout(form)

        # Scheidslijn
        layout.addWidget(self._separator())

        # AdBlock toggle
        self.chk_adblock = QCheckBox(_("settings_adblock_enable"))
        self.chk_adblock.setFont(QFont(base_font().family(),
                                        base_font().pointSize(), QFont.Bold))
        self.chk_adblock.setChecked(config.get("adblock_enabled", True))
        self.chk_adblock.stateChanged.connect(
            lambda s: self._save_bool("adblock_enabled",
                                       s == Qt.Checked.value)
        )
        layout.addWidget(self.chk_adblock)

        adblock_info = QLabel(_("settings_adblock_info"))
        adblock_info.setFont(base_font())
        adblock_info.setStyleSheet(f"color:{COLOR.text_dim};")
        adblock_info.setWordWrap(True)
        layout.addWidget(adblock_info)

