    def _reapply_extensions_to_tabs(self):
        """
        Bij wijziging in extensies-status: herlaad enabled extensies in
        alle open tabs. Eenvoudige aanpak: herlaad de tab — dan triggert
        loadFinished opnieuw en wordt de juiste set ingespoten.
        """
        # Voor nu doen we niets — extensies werken pas na volgende pagelaad.
        # Een refresh() zou de gebruiker mogelijk irriteren (verlies van
        # ingevulde formulieren). Tonen we als info-melding:
        self._set_status(
            "Extensies-wijziging actief bij volgende paginalaad"
        )

    # ------------------------------------------------------------------
    # Afbeeldingspikker
    # ------------------------------------------------------------------
    def _on_open_image_picker(self):
        """
        Verzamel afbeeldingen van de huidige pagina en toon het venster.

        Drie veiligheidsnetten (lessen uit DeskButler):
        1. JS retourneert JSON-string → json.loads aan Python kant
        2. Volledige try/catch rond alles, met _popup_info bij fouten
        3. Safety-timer van 8 sec: als JS-callback niet terugkomt → melding
        """
        tab = self.current_tab()
        if not tab:
            self._set_status("Geen actieve tab", error=True)
            return

        url = tab.current_url()
        if not url or url == "about:blank":
            self._set_status("Geen pagina geladen", error=True)
            return

        print(f"[picker] start voor: {url}")
        self._set_status("🔍 Afbeeldingen verzamelen...")

        # (intra-import gestript: from core.image_picker import COLLECT_IMAGES_JS, parse_images_result)

        # Safety-flag: als callback niet binnen 8s terugkomt
        self._picker_callback_received = False

        def on_result(raw):
            """JS-callback: ontvangt JSON-string (of list) met afbeeldingen."""
            self._picker_callback_received = True
            print(f"[picker] callback type={type(raw).__name__}")

            try:
                images = parse_images_result(raw)
                print(f"[picker] {len(images)} afbeeldingen gevonden")
                for i, img in enumerate(images[:5]):
                    print(f"  {i}: {img.get('source', '?')} "
                          f"{img.get('width', 0)}x{img.get('height', 0)} "
                          f"{img.get('src', '?')[:80]}")
                if len(images) > 5:
                    print(f"  ... en {len(images) - 5} meer")

                # Check op fatale JS-fout
                if (images and isinstance(images[0], dict)
                        and images[0].get("src") == "_error_"):
                    err = images[0].get("source", "onbekend")
                    print(f"[picker] JS-fatal: {err}")
                    self._popup_info(
                        "JavaScript-fout op pagina",
                        f"De pagina blokkeert het uitlezen van "
                        f"afbeeldingen:\n\n{err}"
                    )
                    return

                if not images:
                    self._popup_info(
                        "Geen afbeeldingen gevonden",
                        "Op deze pagina kon ik geen afbeeldingen vinden.\n\n"
                        "Mogelijke redenen:\n"
                        "  • De pagina is nog niet volledig geladen\n"
                        "  • Afbeeldingen worden dynamisch geladen "
                        "(scroll eerst naar beneden)\n"
                        "  • De website gebruikt een ongebruikelijke techniek"
                    )
                    return

                # Open picker venster
                print("[picker] venster openen...")
                # (intra-import gestript: from ui.image_picker_window import ImagePickerWindow)
                self._picker_win = ImagePickerWindow(images, parent=self)
                self._picker_win.show()
                self._picker_win.raise_()
                self._picker_win.activateWindow()
                self._set_status("")
            except Exception as e:
                import traceback
                print(f"[picker] callback-fout: {e}")
                traceback.print_exc()
                self._popup_info("Fout in picker",
                                 f"Er ging iets mis: {e}")

        # Safety-timer
        def safety_check():
            if not self._picker_callback_received:
                print("[picker] !!! Callback kwam NIET binnen 8 seconden")
                self._set_status("")
                self._popup_info(
                    "Geen reactie van pagina",
                    "De pagina reageert niet binnen 8 seconden. "
                    "Mogelijk blokkeert de site JavaScript-uitvoering. "
                    "Probeer de pagina te verversen."
                )

        QTimer.singleShot(8000, safety_check)

        try:
            tab.page.runJavaScript(COLLECT_IMAGES_JS, on_result)
            print("[picker] JS geïnjecteerd, wacht op callback...")
        except Exception as e:
            print(f"[picker] JS-injectie faalde: {e}")
            self._set_status("")
            self._popup_info("Fout",
                             f"JavaScript starten mislukt: {e}")

    def _popup_info(self, title: str, message: str):
        """
        Toon een eenvoudige info-dialoog die GEGARANDEERD bovenop komt.
        QMessageBox kan soms achter een QWebEngineView verdwijnen.
        """
        

        dlg = QDialog(self, Qt.Dialog | Qt.WindowStaysOnTopHint)
        dlg.setWindowTitle(title)
        dlg.setMinimumSize(520, 220)

        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(14)

        # (intra-import gestript: from core.styling import COLOR, base_font, title_font, make_primary)

        title_lbl = QLabel(title)
        title_lbl.setFont(title_font())
        layout.addWidget(title_lbl)

        msg_lbl = QLabel(message)
        msg_lbl.setFont(base_font())
        msg_lbl.setWordWrap(True)
        msg_lbl.setStyleSheet(
            f"background:{COLOR.bg_2}; padding:14px; "
            f"border-radius:6px; color:{COLOR.text};"
        )
        layout.addWidget(msg_lbl, 1)

        btn_row = QHBoxLayout()
        btn_row.addStretch()
        btn_ok = QPushButton("✓ OK")
        btn_ok.setMinimumHeight(44)
        btn_ok.setMinimumWidth(140)
        make_primary(btn_ok)
        btn_ok.clicked.connect(dlg.accept)
        btn_row.addWidget(btn_ok)
        layout.addLayout(btn_row)

        dlg.show()
        dlg.raise_()
        dlg.activateWindow()
        dlg.exec()

    # ------------------------------------------------------------------
    # Video / audio downloader
    # ------------------------------------------------------------------
    def _on_open_downloader(self, url: str = None):
        """
        Open de downloader voor de huidige pagina (of een specifieke URL).
        Stroom:
          1. Check of tools (yt-dlp + ffmpeg) aanwezig zijn
             → nee: vraag of we ze automatisch mogen installeren
          2. Vraag format-keuze
          3. Toon voortgangsvenster + start download
        """
        # 1. Bepaal URL
        if not url:
            tab = self.current_tab()
            if not tab:
                self._set_status("Geen actieve tab", error=True)
                return
            url = tab.current_url()
        if not url or url == "about:blank":
            self._set_status("Geen pagina om te downloaden", error=True)
            return

        # 2. Tools check
        # (intra-import gestript: from core.tools_installer import tools_ready)
        if not tools_ready():
            
            r = QMessageBox.question(
                self,
                "Tools installeren",
                "Voor downloaden zijn yt-dlp en ffmpeg nodig.\n\n"
                "Wil je deze nu automatisch installeren?\n"
                "(circa 80 MB, eenmalig)\n\n"
                "Ze worden geplaatst in:\n"
                "<data-map>/tools/",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes,
            )
            if r != QMessageBox.Yes:
                return
            # Start installer — daarna onthouden wat de URL was zodat we
            # door kunnen gaan met de download
            self._pending_download_url = url
            self._run_installer(then_download=True)
            return

        # 3. Format-keuze
        self._show_format_dialog(url)

    def _show_format_dialog(self, url: str):
        """Toon de format-keuze + start download."""
        # (intra-import gestript: from ui.dialogs.download_dialog import DownloadFormatDialog)
        dlg = DownloadFormatDialog(url, parent=self)
        
        if dlg.exec() != QDialog.Accepted:
            return
        self._start_download(dlg.url(), dlg.format_id())

    def _start_download(self, url: str, format_id: str):
        """Start het download-proces met voortgangsvenster."""
        # (intra-import gestript: from ui.download_progress_window import DownloadProgressWindow)
        # (intra-import gestript: from core.downloader import DownloaderThread)

        # Voortgangsvenster EERST tonen (anders mist UI de eerste signals)
        win = DownloadProgressWindow(title="Downloaden...", parent=self)
        thread = DownloaderThread(url=url, format_id=format_id, parent=win)
        win.bind_thread(thread)

        # Houd referenties zodat ze niet door GC worden weggehaald
        self._download_win = win
        self._download_thread = thread

        win.show()
        win.raise_()
        win.activateWindow()

        # Pas NU thread starten — geleerde les uit DeskButler
        thread.start()
        print(f"[downloader] gestart: {format_id} voor {url}")

    def _run_installer(self, then_download: bool = False):
        """
        Start de tools-installer met voortgangsvenster.
        Als then_download=True: na succesvolle install gaan we door met
        de pending download.
        """
        # (intra-import gestript: from ui.download_progress_window import DownloadProgressWindow)
        # (intra-import gestript: from core.tools_installer import ToolsInstallerThread)

        win = DownloadProgressWindow(title="Tools installeren...", parent=self)
        thread = ToolsInstallerThread(parent=win)
        win.bind_thread(thread)
        self._installer_win = win
        self._installer_thread = thread

        if then_download:
            def on_installed(*args):
                # args[0] is ok (bool)
                ok = args[0] if args else False
                if ok and getattr(self, "_pending_download_url", None):
                    url = self._pending_download_url
                    self._pending_download_url = None
                    # Sluit installer-venster en open format-dialog
                    QTimer.singleShot(500, lambda: self._after_install(url))

            thread.finished_ok.connect(on_installed)

        win.show()
        win.raise_()
        win.activateWindow()
        thread.start()

    def _after_install(self, url: str):
        """Na succesvolle install: sluit installer-venster en ga downloaden."""
        if hasattr(self, "_installer_win") and self._installer_win:
            self._installer_win.close()
            self._installer_win = None
        self._show_format_dialog(url)

