    def _build_favorites_submenu(self, menu):
        """Bouw de favorieten-submenu (hergebruikt favorieten-manager)."""
        try:
            # (intra-import gestript: from core.favorites import get_favorites_manager)
            mgr = get_favorites_manager()
            roots = mgr.root_favorites()
            folders = mgr.all_folders()

            if not roots and not folders:
                act = menu.addAction(
                    "(geen favorieten — gebruik ☆ om toe te voegen)"
                )
                act.setEnabled(False)
            else:
                # Eerst items op root-niveau
                for entry in roots:
                    title = (entry.get("title")
                             or entry.get("url", ""))[:60]
                    act = menu.addAction(title)
                    act.triggered.connect(
                        lambda checked=False, u=entry.get("url", ""):
                            self.new_tab(url=u, switch_to=True)
                    )

                if folders and roots:
                    menu.addSeparator()

                # Dan per folder als submenu
                for folder in folders:
                    name = folder.get("name", "(zonder naam)")
                    favs = folder.get("favorites", [])
                    if not favs:
                        continue
                    sub = menu.addMenu(f"📁  {name}")
                    for entry in favs:
                        title = (entry.get("title")
                                 or entry.get("url", ""))[:60]
                        act = sub.addAction(title)
                        act.triggered.connect(
                            lambda checked=False, u=entry.get("url", ""):
                                self.new_tab(url=u, switch_to=True)
                        )

            menu.addSeparator()
            act_mgr = menu.addAction("⚙️   Favorieten beheren...")
            act_mgr.triggered.connect(self._open_favorites_window)
        except Exception as e:
            import traceback
            traceback.print_exc()
            print(f"[hamburger] favs-submenu fout: {e}")
            act = menu.addAction(f"(fout: {e})")
            act.setEnabled(False)

